/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201130-8","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"建設委員会","time":"午前１０時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","topics":[{"id":"topic-01","title":"第９２号議案、北品川一丁目地内特別区道路線の認定","agenda":"第９２号議案、北品川一丁目地内特別区道路線の認定","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"必ずこれ、道路を認定して、いつ頃こうやって道路になるのか。一応、お話では２０２７年頃ということだと、それから解体があって、大体２０３０年頃ではないですかというのが我々の理解なのだけれども、その理解でいいのかということ。それから、先ほど区道III－２０号の付け替えという話があったのだけれども、これは付け替えで、道路自体は大体面積的に一緒なのかという話。","respondent":"稲田土木管理課長","answer":"面積的な話がございましたけれども、区道III－２０号という既存の路線ですが、ずっともう少し下のほうから来ておりまして、下のほうからずっとつながっている路線です。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど言ったように、事業完了後というのは、立体化の事業完了後だろうから、２０３０年頃と我々は理解しているので、それでいいのかということと、あと、地域の方からお話があったから、先ほど言った清水横丁の話。だから、多分、ここの角は、今、計画のところに入っていないけれども、これはこれで地域の方々と話してこういう形になっているという理解でいいのかというところだけお願いします。","respondent":"中道まちづくり立体化担当課長","answer":"清水横丁につきましては、都市計画決定の際にもいろいろと意見交換をいただきまして、道幅であったり、景観であったりを配慮してほしいという言葉をいただいてありますので、地域の方の意見を踏まえまして、また整備の内容等については検討してまいります。","id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"今までも幾度かご説明があったと思うのですが、確認も含めて、重複になるかもしれませんが、お願いいたします。黄色い部分というのは現状どうなっているのかということと、結局、最終的には区道III－２０号というのはなくなるわけであるので、ここはどういう状況になっていくのでしょうかということ。それから、６ｍのところで、歩道が２ｍ。","respondent":"中道まちづくり立体化担当課長","answer":"今現在、詳細については、東京都が検討中です。６ｍの道路につきましては、今、車道が４ｍ、歩道が２ｍです。車道上に自転車のレーンを設置するかというところにつきましては、今現在、調査というか、詳細な検討をしています。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"自転車のところは検討中ということなのですが、やはりそんなに広い幅ではないと思うので、ただ、分離をきちんとして、交通事故が起きないような形をぜひ検討していただきたいと思います。すみません、１点、答弁漏れというか、黄色いところは今どうなっているのでしょうかという。今どういう状況になっていますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"線路。今、どういう状況になっているのですかというのを。","respondent":"中道まちづくり立体化担当課長","answer":"黄色い区域の部分につきましては、今現在、線路上というところで、京急が用地を持ってあります。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"今、交通広場を整備していくという中で、区道の認定というのも出されておりますけれども、この交通広場ができることによって、やはりまちの方々が心配されている旧東海道の道幅ですとか、先ほども少しお話がありましたけれども、横丁がきちんと守られるのか、そこを伺いたいのと、交通広場になると、つまりは道路になるということで、地域の方はその場所を気軽に使いたいというお話が出ていますけれども。","respondent":"中道まちづくり立体化担当課長、稲田土木管理課長","answer":"現在もこちら、町会長または区民の方々と意見交換をして、こちらのほうの駅前広場をどういう広場にしたらいいかと、地域の方を併せまして、検討している最中です。一般的に道路の使用についての手続きの話というのですか、おまつりやイベントや、そういうことで道路を使用しようとするときは、交通管理者の警察の許可が要るというところでございまして。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"景観については、今、意見交換をしているということですけれども、実際に今回の右側の広場のところというのは、建物が旧東海道から広場のところまでかかっている状況のところが多くありますので、そうなると、そこの建物が除却されてしまって、旧東海道の景観というのが壊されてしまうのではないかと思うのですけれども、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"建物が除却されて空間がオープンになるのではないかですが、そこの境につきましては、生け垣や、また、そうした壁等のしつらえ等で景観を守っていきたいです。そうしたことも踏まえまして、今現在、地域と意見交換をしながら進めているところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"意見交換をしているというところはいいと思うのですけれども、やはり建物がなくなることで景観が変わってしまうということになりますので、そこは守れないのではないかと私は思っております。今回、こういった区道の認定の話が出てきましたけれども、この前に都市計画審議会で審議されて、意見書の募集なども行われておりますが、意見書の賛成・反対の数というのがどうなっているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画決定を取る際に、この事業、２回、意見をいただいてあります。当初は、２０通、５８名の方から、変更のときには１５通、１６名の方からいただいているです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"意見書のほうは、たしか最近行われたものでは、賛成２件、反対十何件という感じだったと思うのです。その中で、つまりは、反対している人のほうが多いということだと思うのです。やはりそうしたところでやっていくということが必要だと思いますので、そういった住民の声をしっかりと聞いて反映をさせていくということがまちづくりの基本だと思いますので、ぜひそのように進めていただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどの変更のときの意見書の数、賛成・反対の数ですが、賛成が２通、反対は１２通、その他といたしまして１通あります。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"改善してほしいと思います。そして、スケジュール感なのですけれども、もう一度確認させていただいてもいいですか。ここには、都市計画道路事業認可と認定のことしか書いていないので、先ほどほかの委員から解体とか完成の時期とかも出ていたのですけれども、私の調査漏れなのか、そういったことがもうどこかで報告されていたのかというところも併せて伺いたいと思います。そして、なぜ今認定が必要なのか。","respondent":"稲田土木管理課長","answer":"それともう一点、なぜ今の時期かということですが、これは事業認可が４月に下りておりますので、速やかにというのですか、そういう形でこのような手続きをしているものです。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"その根拠がもしあれば、お知らせいただきたいというのと、あと、これから認定をするということは、この道路にしていきたいということですよね。ただ、今、感染症が広がる中で、シーリングがかけられているときに、なぜこのタイミングなのか。区としても、今この認定を出す時期なのかというところもお知らせいただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"こちらの事業のスケジュールですが、今年の６月３０日の建設委員会での報告で、事業決定をしましたので事業を進めるというところで、地域に対して事業の概要等を説明した経緯があります。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"都のほうでも、工事とかは、この感染症に予算がすごく使われるということで削減していくということだったのですけれども、では、都としてもこちらのほうは進めていくということなのですか。そのスケジュール感を先ほど伺ったと思うので、そちらもお知らせいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"この事業を進めるか進めないか、まず１点目のご質問ですけれども、進めてまいります。東京都も中止する考えはないというところは確認しています。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"今のご答弁からも、やはり道路としての必要性というのがそれほど伝わらなかったというか、広場とにぎわいを求めるためにとしか思えなかった。この道路を造ったら、学生の滞留が解消されるのですかというところと、あと、車ですよね。というところとかも、利便性が、広場を造ってにぎわいがというところが主だったのかというのを思ったのですけれども、そこら辺を確認させてください。","respondent":"中道まちづくり立体化担当課長","answer":"東京都が行います連続立体交差事業で、こちらにあります踏切が３か所解消されます。その３か所が１時間に遮断量が４０分以上の、いわゆる開かずの踏切と言われるものの解消になります。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"タクシーのお話も、前の議事録とかを追ってもお話が出てきたのですけれども、それほどここでタクシーを利用するというのが、地域でもあまりないのかというのは感じていまして、地域の方からもそういうお話を伺っています。立体化が地域から求められているのはすごく分かるのです。改めてそこの部分をご説明いただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今の流れでいきますと、来年度には用地を譲っていただける方がいらっしゃるような傾向がありますので、先ほどご説明いたしました国費の申請をする前に、道路をきちんと位置づけたいというところで、今、行政手続きを進めている最中です。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"今回、区道にするということですと、財源がどうなるのかということで、区が施工して予算をつけていくのかどうかというところを、先ほど少し補助金の話もありましたけれども、財源がどうなるのかというところを伺いたいと思います。先ほど広場使用のところでは、警察の許可が要るということで、そうすると、住民の方が気軽に使えなくなってしまうのではないかと思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長、稲田土木管理課長","answer":"財源ですが、事業主体が区ですので、まず区がそちらのほうのお金を用意する。その中で、国費が約５０％、また都費が約２０％ということで、約７割の補助金を入れて事業を進めていきたいと考えています。委員のおっしゃっている使い方がどのようなものか、はっきりしませんけれども、普通に道路は皆さん使ってもらって結構ですので、普通に広場としての使い方を区民の皆さんがしていただく分には、特にそういう許可とか。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"今、普通に使う場合は許可は必要ないということでしたけれども、普通というのはどういうことですか。おまつりとか、そういうときに使う場合には許可が必要だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"認定については、今なぜこのタイミングなのかというところも、やはりお話を伺ってもよく分からなかったというところと、あと、道路にしてからの利便性というところも分からなかったというところで、ここの認定については反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"令和２年陳情第６０号、「大井町駅周辺地域まちづくり方針」のＣ地区に関する陳情","agenda":"令和２年陳情第６０号、「大井町駅周辺地域まちづくり方針」のＣ地区に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この中で、防災面の課題ということも言われておりますけれども、区が捉えている課題は何か、伺いたいと思います。それと、この辺りは昔からの再開発の動きがありましたけれども、その際に、以前の数十年前のときに再開発の準備組合ができたということで、まだそれは解散していないという話も聞いているのですが、区の認識として、この準備組合というのは残っていると考えているのか、伺います。","respondent":"多並都市開発課長","answer":"ここの高層ビルという先ほどのキーワードがありますけれども、そこにつきましても、この勉強会の中で５回開催されておりますけれども、この勉強会の位置づけとしましては、地域の方がこれからまちづくりを進めていく上の手法がいろいろと幅広くあるので。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"やはりそういった中で、この陳情の中でもありますように、「まちの良さを残しながら改善を図る手法」というのが、私も必要だと思います。そうしたよさを残しながら改善をしていく手法というのはどういったものがあるのか、伺いたいと思います。実際にこの再開発の場合、損失が出たときは地権者が負担する仕組みとなっているのか、伺いたいと思います。そのまま残ってしまうのか、伺います。","respondent":"多並都市開発課長","answer":"もう一つの、例でありましたように、市街地再開発事業が事業として、先ほど破産というお話がありましたけれども、そのようなことがないように、まず事業の最初のスキームであったり、検討していくことが重要でありますけれども。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"地域の皆さんで話していくことが重要ということがところどころで言われているのですが、まず、仕組みとして、再開発の仕組みというのが、事業が成り立たなくなった場合、損失が出た場合、地権者が負担するということがあるのかということと、あと、借金が既にある方たちが再開発に巻き込まれた場合、この借金がどうなってしまうのかというところで、仕組み上の話で伺いたいのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そのときにご自分がお持ちの、今までの資産の借金についてもどうするかという、もちろんそれもなくなるわけではありません。借金がなくなるわけではありませんから、そういうのも全体を含めて皆さんで考えていただくというのが答えかと思います。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"つまり、借金も残ったまま、もし事業が破綻してしまった場合は、地権者の方が負担する可能性があるということだと思います。この間、再開発というのが、合意がなくとも進められているという実態がありまして、大井一丁目南第１地区ですかね、そのときには合意していない方が多くいらっしゃったと思うのですけれども、本組合の設立をしたときの地権者数と同意人数を伺いたいのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"要するに、賛成だ、反対だというわけではなくて、やはりまちづくりというのは非常に難しい部分もありますから、それをまず知っていただくということで、みんなでそういうのをやっていただく段階だとご理解いただければと思います。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり住み続けたいという方もいらっしゃるということがありますので、この陳情にもあるとおり、真の意味で住民主体のまちづくりということで、住民合意のもとで進めてほしいということですので、進めたいことも含めてですけれども、よりよいまちにしていくと。まちのよさを活かしながら進めていくということでやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"区のほうにこの陳情について何か伺うというのはとても変な形だと思うのですけれども、先ほどから何回も皆さんで考えていただくということをお話しされていたので、やはりこの地域の実情等を踏まえた方針の見直しというのは、区のほうも認めていらっしゃると思うので、陳情にはぜひ皆さんに賛成していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"多分、ここの地域は、そういう対策を取らなければいけないという地域という認識でよろしいのでしょうか。それについてはどう考えられるかということ。ですので、こういうのは、まず１つは、区の関与というのがどこまでできるのですか。分からない。それから、最後のところ、下のほうです。ただ、やはり住民にしてみれば、Ｃ地区というのが決められていて、それは品川区がＣ地区と囲ったわけではないですか。","respondent":"多並都市開発課長","answer":"ここにつきましては、耐火、いわゆる構造物の防災上の課題があるような建物の割合につきましては、大井町周辺の他地区ですと６０％くらい耐火の構造物がある中で、このＣ地区については４割程度ということで。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、先ほど来、委員からの話で、「思います」とか、賛成・反対とかという、多分に主観の混じられた質疑応答がありまして、私はそのように受け取りましたので、客観的にお話を聞きたいと思いますけれども。これ、おおむねどのくらいの期間、今までやられているのか。改めて教えてください。","respondent":"多並都市開発課長","answer":"勉強会のほうが、令和元年５月から第１回目で、令和元年７月、９月、１１月、あと、令和２年１月で５回ということをやられていると認識しています。心配する会が令和２年２月、３月ということで、２回やられているということで認識しております。","id":"exchange-025"},{"speaker":"大沢委員","kind":"意見","question":"ということは、まだその中では意思の疎通というか、心配されている方は分かりますが、その中では双方の意思の疎通が十分に行われていないということが見受けられるのですけれども、そこのところをどのようにお考えになりますか。","respondent":"多並都市開発課長","answer":"まちづくり勉強会の事務局の方は、まだどの手法だと選んでいる前の段階ですから、その段階ではないというご説明をして、行き来をしているような、そういう認識で区としては思っているところです。","id":"exchange-026"},{"speaker":"大沢委員","kind":"確認","question":"それだと、ここのところの方針については、かなりの弾力性というか、遊びがあると考えます。その中で、再開発の手法については、まだこれからの双方のまちづくりに対する考えを聞きながら決めていくわけであって、ここに言う、都市再開発法で定めた権利変換なるものに対して決まったというわけではないということで、そこは一回確認させてください。","respondent":"多並都市開発課長","answer":"今、委員のお話のとおり、まさにそのとおりで、権利変換というのはもっと本当に先の話で、まだその本当の前の前の段階とご理解いただければと思います。","id":"exchange-027"},{"speaker":"大沢委員","kind":"意見","question":"となると、基本的にまだ始まったばかり、初期段階で方向性が決まっていないということですので、初期段階であれば、今後の様々な調整方が必要になってくるわけだと思います。その中でいずれかはやってくるだろう双方の意思疎通も含めた会合なるものも必要になってくると思うのですけれども、そこのところの段取りはどのようにお考えになりますか。","respondent":"多並都市開発課長","answer":"今、皆様にひと通りこれからのまちづくりの手法を勉強していただいていますので、その次の段階として、ほかの地区の例では、まちづくり協議会だとか、そこの中でまずは話し合っていただくことになるかと思いますけれども。","id":"exchange-028"},{"speaker":"大沢委員","kind":"確認","question":"先ほど来、課長のご答弁にもありましたように、あくまでも助言、それなりの方向性を導くために、この双方の勉強会にそのような考えのもとに出席をされ、よしとする方、それに対して違うという方の平らけく意見を聞かれているということが現状ですね。もう一回確認させてください。","respondent":"多並都市開発課長","answer":"委員のおっしゃるとおり、区としては、双方、いろいろな方のご意見ということで捉えているところです。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"今だからこそこういう議論が出るべきだと思います。いろいろな手法を選んでいる段階というご説明があったのですけれども、何でこの勉強会が選ぶのですか。今、そのご答弁を聞いて、私、やはりこれは地域の方たちが主体になっていないではないですかと思って、思わず聞いてしまったのですけれども、まさかそうではないですよね、というのを確認させてください。確認させてください。","respondent":"多並都市開発課長","answer":"協議会と先ほど言ったのは、一般的にほかの地区でいえば、そう進むことが一般的で、それも含めて皆さんで考えることですから、そういうご理解でいただければと思います。ただ、そういう段階というのですかね、というご理解という説明を先ほどさせていただいたところです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"選んでいる段階ではなくて学んでいるということで、分かりました。ですので、勉強会をされている方たちはいろいろな手法をご存じで、それを学んでいるということだと思うので、それが地域の方たちとも共有されて、それで本当に地域の方たちとともに進むまちづくりに、先ほど冒頭の説明にもあった、その地域主体でのまちづくりが進むように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは、必ず地域の課題を解決するためにはどのような手法が必要だ、それこそ第一種市街地再開発事業のお話も、もちろん先ほど来出ているけれども、では、第二種にすればいいのか、共同化にすればいいのか、様々な手法があるわけで、それは地域の方々が、先ほど来、一緒にともにやってもいいのではないですかという話もあったけれども、品川区はオブザーバーで出ているわけでありますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"本日結論を出していただいて、不採択でお願いします。理由は、先ほど来、都市開発課長とのやり取りの中で、区ができる限りの地域課題、あるいは地域意思、住民意思を起こすべく取組みをしております。よって、ここにおきまして採択をすることによって一定の方向性を出すことについては、反対をいたします。よって、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"若林委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。品川区の活力の源であり、また、そういったものを今後ぜひ創造していってほしい。機会をなくしてしまうということにも私はつながると思いますので、そういう意味では、区の方針は現状のまま見直しはしないで、Ｃ地区の皆様の意見を闘わせたり、議論をしたりという機会をしっかりと継続したほうがいいかと思った次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、今、いろいろとお話もありましたけれども、やはりまちづくりというのは住民合意が前提でありますので、まちのよさを活かした修復型という手法で進めていくのが私たちもいいと考えていますので、これはそうした中で住民合意で進めていくということを今回も求めている陳情ですので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。先ほど来、お話があったように、やはりこの陳情で訴えているのは、今、地域主体の方針となっていないということから、地域の事情等を踏まえた方針の見直しの要望が出されています。そして、丁寧に議論する必要があると私たちは考えていますといった、議論を求めているので、私は本当にこれは採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出して、採択でお願いします。いろいろ議論して、区の意思も確認をしたわけですけれども、陳情の趣旨の中のまちづくり方針というところが、やはり住民サイド、今回の心配する会の方々と区が言っていることが少しずれている部分があると思うのです。今後の対応も含め、柔軟な対応と、それから、区の考え方をさらに示していただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"先ほどのご説明の中の、高架下貸付可能面積のところで、高架下の検討委員会が立ち上がって議論がされるといったお話があったと思うのですけれども、その検討委員会のメンバーについて、都と区とというお話があったのですけれども、ほかにどのようなメンバーで構成されるのかというところをお知らせいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"詳細については、今後協議ということになってきますが、一般的に、東京都、区、鉄道事業者、この３者で構成されます。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"今後ということだったのですけれども、この検討委員会が立ち上がった後の検討状況というのは、基本的にこれまでは公開されてきたのか、今後されるのかどうかというところとか、お知らせいただきたいと思うのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"検討委員会の公開についてですが、そちらも踏まえまして、今後調整ということになっていきます。今までの経緯につきましては、現在、把握はしてございません。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"上位計画のところをお聞きしたいのですが、この関係性なのですけれども、東京都の都市整備局が策定したものが上位ということなのですが、それを基にして品川区まちづくりマスタープランというのができたのかという、その上下関係というのか、それを知りたいのですけれども。そういう場合は、品川区から東京都に申入れをしてという形ができるのかどうか。その辺はどういう仕組みになっているのでしょうか。","respondent":"鈴木都市計画課長、中道まちづくり立体化担当課長","answer":"東京都の計画と区のマスタープランの関係性ですが、当然、鉄道の立体化にあたっては、まずは東京都が東京都内全体の計画のようなものを持っていますので、その中身を踏まえてマスタープランで位置づけていくですが、ただ。こちらのほうが、２０２５年度までに重点的に対策を実施すべき踏切という位置づけです。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"今、踏切の中で２０か所というお話がありました。全体ではどのくらいあるのかなと思うのですけれども。その辺の力関係も含めて、やはり強く言ってもいいのではないかという部分があるのですけれども、例えば、十分に聞いていただいているのですということなのか、まだまだ十分ではなくて、品川区の現状をもっと伝えて、それを酌み取っていただきたいという状況なのか、その辺はいかがですか。","respondent":"中道まちづくり立体化担当課長","answer":"鉄道事業者や東京都との交渉ですが、そういった意見交換をする場というものが年間に幾度か設けられていたりとか、今現在、先ほど言いました重点踏切をまず解消というところで意見交換はしていますので、そういった中で、特に上下関係というわけではなく、同じ方向を向いて。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"例えば、横須賀線とかは乗り入れが結構多くなってきていて、開かずの踏切というのが増えてきているのです。見直しをある程度するという仕組みがあるのか。鉄道事業者も経費もかかることなので、その辺の調整というのは、東京都がやるのだろうかと思うのですけれども、どのようにされているのでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"戸越公園駅を例に挙げますと、もともとはシステムの改築とかで解消する方向性でいたのですけれども、先ほど説明いたしました生活道路のボトルネック踏切というところで、連続立体交差事業の方法で踏切を解消していこうという形で、手法をその都度。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"戸越公園駅のところで伺いたいのですけれども、交通遮断量が示されておりまして、差し引きで車が１,３３６台になるのかと思うのですが、その上に歩行者等ということで、１１万３,６８０台（人）ということになっていますけれども、歩行者と自転車の数、内訳が分かれば教えていただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"そういった形で、今ここに書かれているのは原則であって、また検討会の中でいろいろと柔軟に活用していくです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"ピーク時の遮断時間というのがあるのかないのかというところもお聞きしたので、後でご答弁いただければと思います。今回の一般質問でも取り上げさせていただきましたけれども、そこのところはどのように考えていらっしゃるのか、伺いたいと思います。今、戸越公園駅のところは調査中ということで、事業効果等を検討しているということも書いてありますけれども、今の検討状況がどうなっているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今現在調査中ですが、東京都のほうで、こちらの連続立体交差事業を実施する費用対効果であったり、詳細設計をしまして、実際のそこの工法選定、地下であるのか、高架であるのか等、今現在調査をしている段階で、それを踏まえまして。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"交通量のところなのですが、私が言ったのは、車の交通量が商店街のところで増えてしまうと困るということで、生活道路のボトルネックになっているので、歩行者は当然より通りやすくなると思うのですけれども、車の交通量が増えてしまうということにもなりかねないと思うのですが、そこはどう考えているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今、ここでは補助２９号線のお話がありますが、またそれは延焼遮断帯機能を形成するという目的のために東京都が進めている事業です。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここは日頃車が少ないところになりますので、そういった商店街を残していくということが必要だと思うのですけれども、歩行者の方のボトルネックになっているというのは、以前から言われておりまして、６か所が解消するということで、立体化は、安全のためにも、スムーズな生活を送っていくためにも、ぜひ進めていただきたいと思いますが、そこと一体に駅周辺で行われている再開発を進めていくということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えていただきたいのですが、今お話を進めている、戸越公園駅のほうは私はあまり詳しくないのだけれども、京急の部分については、地元では３０年来ずっと要望してきたことであって、国会議員にもお願いをしたけれども、当時は技術的にもなかなかできないというようなことがあったりして、やっとここへ来て念願が叶う。確認したいのは、駅をこうやって立体化をやるのだと。","respondent":"中道まちづくり立体化担当課長","answer":"そういったことを踏まえまして、今、東京都では、連続立体交差事業を進めていくにあたりまして、地域の状況がどうなっているのかというところで、そこで一つ駅前広場というものを地元区はどのように考えているのかというところが、全体を事業を進める中で一つの条件といいますか。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"駅前広場というと言葉が微妙になってしまうから。駅前広場は、北品川駅も９９％の人は賛成だと。それが、交通広場だといったら、逆に９割くらいの人が反対になってしまった。それは違うだろうと。そうしたら、その次に、これは交通広場なのだという話になって、いきなり９割くらいの人が反対。交通広場という位置づけ、これも必須だよねということを聞いているので、そこをもう一回答弁してほしい。","respondent":"中道まちづくり立体化担当課長","answer":"今後、地域におかれましても、やはり駅前広場という一つの単語だけですと誤解を招くというところもありますので、交通機能を持った広場であったり、交流機能、にぎわいを創出する機能を持った駅前広場といった形で、柔軟に説明を工夫してまいりたいと思います。","id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど来、地域とともにやってくださるのはいいのだけれども、どうしても風穴が開けづらいのが、高架下。今、立体化になっているところは、駐車場だとか、いろいろな店舗も入っているのも事実なのだけれども、ぜひそういうところを地域として、せっかくここは品川区の区道でもあるし、そういういろいろなことができないかと思っているのだけれども、そこら辺の点はどうお考えになるのか。","respondent":"中道まちづくり立体化担当課長","answer":"もちろん駅前ということになりますので、そこににぎわいを生むような施設というのは、区としても要望していきたいと考えています。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"でも、ご説明の中では、都では、地域の方たちが求めているかどうかの確認でいいといったご答弁だったのかというのと、それと、必須なのかどうかというのになると、法的に定められて広場を造らなければいけないというものになっていくのかという認識なのですけれども、どちらなのかという確認をさせてください。","respondent":"中道まちづくり立体化担当課長","answer":"区としましては、戸越公園駅を例にしますと、やはり区はそこに６か所の踏切がありますので、また踏切事故もあるというところで、そこを解消していきたいというところで、昨年度、まちづくりビジョン基本計画編というものを策定いたしまして、そういった連続立体交差事業。","id":"exchange-050"},{"speaker":"田中委員","kind":"意見","question":"交通広場と駅前広場の使い分け、駅前広場は行政用語ということで、区民の方が誤解しやすいといったことから交通広場にして、バスとかも通るイメージをしてもらうといったことだったのですけれども、本当に２つの名前が出てしまうと混乱してしまうので、統一していただければうれしいです。もし違うというならば、もう一回ご説明いただければと思います。ごめんなさい、私、理解ができていなくて。","respondent":"中道まちづくり立体化担当課長","answer":"ですので、今後、そういった形であれば、交通機能、あとはにぎわいを持った、両方の機能を持たせた駅前広場とか、少し表現の仕方というのは工夫していきたいと考えています。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"申し訳ありません。資料の２枚目の右側に「【参考】駅前広場の役割」というのがあって、要は、場所によっていろいろと目的を考えて造っていきますということなのだろうと思うのです。すみません、先ほど議案審査をした北品川駅のほうで言うと、ここは何になるのですか。だから、そういう意味は分かるのですけれども、北品川駅の例で言うと、どういうイメージをすればいいのでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"これが全部そこに入るかどうかというのは、今後また地域も含めまして、私たちも詳細に検討はしていきたいとは思うのですけれども、今、そういった交通と都市の機能２つを併せた駅前広場の事業をしていきたいです。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"そこまでご説明いただかないと理解できなかったと思っているのですけれども、誤解されるというのが往々にしてあると思うのです。すみません、理解力がなくて申し訳ないのですけれども、今やっと理解できた状況なので、これからもご配慮いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"確認","question":"２日目のこんの孝子議員の災害対応についてのところで、災害のときの外国人向けの情報発信についての質問があったと思うのですけれども、その中で、要配慮者と外国人への情報提供を今後どのように図っていくのかという部分を伺いたいと思います。特に外国人の方に向けてが、当事者の方への聞き取りが行われていないといった答弁があったと思うので、そこの部分を確認させていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":42457,"voices":156}},{"id":"r02-20201130-9","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"文教委員会","time":"午前１０時００分～午後 ５時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を117件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそものところで申し訳ないのですけれども、区立幼稚園教諭のほうの給与水準の体系の基本的な考え方というのは何なのか、改めて伺いたいというのが１点です。それと、管理職員というのは、具体的にはどの役職以上を指すのかというのをお伺いします。それと、前回の１１月９日の委員会で報告がありましたけれども、それ以後の労使交渉の結果について、妥結したのでしょうか、伺いたいと思います。","respondent":"工藤指導課長","answer":"幼稚園教育職員の給与につきましては、区職員と同じというところで伺っているところです。管理職につきましては、園長、副園長が管理職として勤務しているものです。交渉のところにつきましては、１１月１９日に妥結したと情報をいただいているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"今回の引下げという改定なのですけれども、これは何年ぶりになるのかというのと、前回、勧告の概要を報告いただきましたが、そのときに、今回は特別給ということなのですけれども、８月１７日から９月３０日までに行った月例給の民間企業調査について、行われたということもありましたが、そちらのほうはどのような結果になったのでしょうか。改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"すみません、引下げ改定が何年ぶりかというのが手元に資料がないところなので、回答が難しいところです。月例給につきましては、まだ必要な報告・勧告が出されていないという現状です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"地方公務員法ですとか、人事委員会の勧告のルールというのがあると思うのですが、教員の賃金の低下というのは、こういう倍率が下がっていくということにも一つ表れているのかなと思うのですけれども、教育の質の低下にどうしてもつながってくる問題だと思うのですが、区教委のお考えはいかがでしょうか、伺います。","respondent":"工藤指導課長","answer":"ただ、その選考の中で採用等に至った者につきましては、教員としての資質・能力が認められるというものですから、もちろん育成も含めながら、しっかりと進めることが必要であると認識しています。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"この引下げで、実際に平均でどのくらい下がるのかという試算はされていますでしょうか。幼稚園のほうと学校のほうと、両方を教えてください。","respondent":"工藤指導課長","answer":"これにつきましては、どちらも職員の平均年間給与としては、約２万円の減になるです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"労使で妥結しているということですので、それはもちろん尊重する立場なので、あえて反対はいたしません。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"確認","question":"一応、確認なのですけれども、約２年間の間ぐらいで、今までは、その都度被害がここにありましたということは、１回も相手の持ち主の方から学校のほうになくて、取り替えるとなったときに、そういえばということで、まとめて請求が来たという認識でいいのかということと、もし仮にそうだとすると、今までは対応ができなかったのかもしれないけれども、今後新しいものに替えたときには。","respondent":"有馬庶務課長","answer":"これを受けまして、今回の補修につきましては、ポリカーボネートの、今までの波板よりも少し厚いものでやるということですので、ボールが飛んだからといってすぐに壊れないようなものにするということと、それから、防球ネットの高さは１０ｍ近くあるのですが。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。大丈夫だと思いますけれども、通行人だとか人に、テニスの硬球だから、それほどとは思うけれども、ご高齢の方とか小さい子どもに行った場合には、物とは違う部分での損失になりますので、そういうのは一応、大変だと思いますけれども、注意していただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"細かいお話なのですけれども、飛び出したものというのは、この駐車場の上にしか行っていないのでしょうか。近隣も一応、調べられたのでしょうか。ほかのところからは一切お話もなく、被害もなくて、この屋根だけに硬球が集中したということでしょうか。何かお分かりですか。","respondent":"有馬庶務課長","answer":"基本的にここは、先ほども申し上げましたように、シャッターが下りていた奥の駐車場ということで、そこが入って探しにくかったというところがあったです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"意見","question":"練習場所を変えられたということで、いいと思うのですけれども、その状態が分からないので、そこからまた新たにどこかに出てしまって、何か別のところに被害が行くということはないように、慎重に対応をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"筒井委員","kind":"確認","question":"防球ネットはすぐに取り替えられないので、練習場所を変えるなどの対策をされるということなのですけれども、気になるのは、平成３０年４月から令和２年５月までの間という、この期間だけ起きたという認定ですけれども、これはあまり考えたくないことなのですが、ふだんの練習中、自然と練習していてこうなったのか、それとも故意に飛ばすような生徒がいたのか、その辺りの解明というか、事実確認というのは。","respondent":"有馬庶務課長","answer":"部活ですので、顧問なり上級生なりがいて練習いたしますので、あえて故意に出すということは、学校からの報告は聞いておりませんので、たまたま新入生が慣れないときに、ラケットとボールがうまく当たらないで。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ただ、練習場所を変えても、またなお飛び越えるようなことなどもあり得るかもしれないので、いろいろな対応はあると思うのですけれども、今後は近隣の人とかにも直撃すると、もっと大変なことになってしまうので、再発防止をしっかりと行っていただくよう、よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"専決処分の報告について（報告第２４号）","agenda":"専決処分の報告について（報告第２４号）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"庁有車のほうの被害額というのは、どれくらいなのでしょうか。","respondent":"横山品川図書館長","answer":"廃車という形になりましたので、１２８万５,２００円です。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"車を運転するのも職員の方のお仕事だと思うのですけれども、その辺の安全管理ですとか、あるいは、逆に最近、車の運転免許をあまり持っていないとか、日頃運転されない方も増えてきているのかなと思うのですけれども、その辺は何か役所としては、運転技術や経験みたいなものというのは勘案しつつ、庁有車というのは運転することになっているのですか。","respondent":"横山品川図書館長","answer":"職員採用の際にも運転免許の申告と、実際に免許を持っているだけではなくて、運転できるかどうかの確認をしながら、配置をしていますが、事実上は不足というか、なかなかきつい状況で、図書館でも実質上、１人しか運転できる人はいないという形です。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"特別この事故というわけではないのですけれども、運転ができる人が減っている中で、運転する人だけに運転業務が集中するようになってしまって、その方に事故リスクや違反リスクも集中していくというのは、何かちょっと引っかかる。今後その辺の公平性というか、考えていらっしゃることはありますでしょうか。これは役所全体の話だと思うのですけれども。","respondent":"横山品川図書館長","answer":"なので、図書館としては、運転できる人を必ず異動の際にお願いするという形を取っています。ですが、区全体ですと、限られた人材ですので、そこを工夫しながらという形が、今のところの実態です。","id":"exchange-014"}]},{"id":"topic-03","title":"令和２年請願第１４号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年請願第１６号、「子どもたちの安全と学びの保障」に関する請願","agenda":"令和２年請願第１４号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年請願第１６号、「子どもたちの安全と学びの保障」に関する請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"議事進行の関係なのですけれども、中途議決の関係もあって、結構項目も多いので、午前中だと中途半端になってしまうと思うので、こちらの審査なのですけれども、午後に回してもらえないかと考えています。","respondent":"こんの委員長","answer":"時間的に、これから説明を受けて質疑に入ると、途中になってしまうと。午後の予定を考えると、１１時をめどに、こちらの会議を一旦止めするという予定でいますので、その時点で、あとは午後に回るという話になります。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"かなりの人数の方が署名を提出されていると思うのですけれども、傍聴の関係もありまして、午後からの予定だと考えている方も結構いらっしゃるので、そういった関係もありますので、できれば午後からに割り切って配慮してもらえるとありがたいのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"今のご説明に沿って何点かお伺いしたいと思います。確認なのですけれども、国の基準が何時間だったか、今の時数は学年ごとに国でどのくらいの時数になっていましたか。それで、品川区の１・２年生の部分はプラス何時間になっていたか、一応、数字で確認をさせてください。それから、スクールカウンセラー等々のお答えで、現在でも効果的なアプローチができていると。はそこまでお願いします。","respondent":"工藤指導課長、篠田学務課長、矢部教育総合支援センター長","answer":"３年生以上は国と同様ですので、教育課程、私どもの教育要領の時数で申し上げますと、３年生が９８０時間、４年生から６年生までが１,０１５時間。基本的には、それをすることによって、学級編制上、そういった対応が非常に取りやすくなっているということもありますので、子どもたちにとっても比較的。もう一つ、スクールカウンセラーが十分かということでありますが、本当に朝から晩まで、週１回でも週２回でも。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"それぞれありがとうございました。そういう意味では、国が法改正をするなら従いますということだけではなくて、よりよい教育環境というのを品川区の教育委員会としてはどのように考えていらっしゃるかということを、もう少しお伺いできればと思います。それから、スクールカウンセラーの件ですけれども、十分に仕事をされているか、それは一生懸命されていると思います。","respondent":"篠田学務課長、齋藤教育次長、矢部教育総合支援センター長","answer":"それは国なりに、様々なメリットを考えてということだと思うのですけれども、私どもとしましても、例えば中身に応じて、先ほども申し上げたとおり。創立記念日をやりますと、大体７０年以上ということで、ご案内のとおり、ベビーブームの世代に対応した学校ですので。ですから、複数回いても相談できない場合もあるということで、繰り返しになりますが、目安箱とかアンケートとか相談窓口。","id":"exchange-018"},{"speaker":"あべ委員","kind":"意見","question":"学級人数は、平均でいうと大体３０人前後、そういう数字になると思うのですけれども、これは平均は平均で、学級編制の大きいところは大きいところで分けて考える必要があると思うのです。その中には、とても小さい学級もあれば、４０人学級のところもあって、あまり私は平均というのは関係ないと思っています。むしろ後半でおっしゃっていた、４分の１の学校が４０人になっているという。違いましたか。","respondent":"齋藤教育次長","answer":"１クラスでも４０人のいる学校が４分の１で、ほとんどの学校では３０人学級となっています。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"了解しました。そういう議論というのは、教育委員会の中ではされないのでしょうか。そこの姿勢の部分をお伺いしたいというのが１点です。なので、最初のご答弁で引っかかってしまったのが、既にできていると言われると、もうこれ以上改善する気はないのか、改善の余地はないと考えているのでしょうかという思いも込めて、質問させていただきましたので、それぞれお願いします。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"したがいまして、学級編制に当たっては、そこを軸に置いた上で、個別の対応については、少人数での対応もできるとか、体制を取っているですので、逆に言うと、何人であればいいという理想的な学級人数。教育相談につきましては、これから子どもたちの実態把握をしっかりと常々しながら、きちんと対応できるように体制を整えてまいります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"もちろん、頑張っていらっしゃるとは思いますが、たまにしか学校に来られないので、どういう状況なのかというのも日常的に把握できないですし、私は、常勤化で毎日いるという、常にその学校でどういうことが行われているか、子どもたちの様子を毎日見られる、その上で相談に乗る体制というのが、今こそ必要だと思うのですけれども、区の考えをお伺いします。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"ですから、そういったものを公表するというのはあろうかと思いますが、私どもは標準授業時数を上回って、教科の内容を定着させるために増やしているということではないと認識しています。それと、先ほども区としては目安箱、生活アンケート、相談電話の窓口で対応したいです。あくまでもお子さんの実態とか社会の状況なども踏まえて、丁寧に対応していきたいという考えです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと授業数のほうは、実際に区が示す標準授業数より増やしているというところが、何校あるのか、どれぐらいあるのかというのを伺ったので、それが分かればお答えいただきたいのと、あと、区自身が国の標準時間数を上回る標準時間数を設定しているわけですけれども、それの目的は何なのですかというのも伺ったので、お聞かせください。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"毎日常駐することで、必ずしもお子さんが全てそこのスクールカウンセラーにつながって、上手に対応できるかというのは、まだ分かりませんけれども、委員ご指摘のとおり検討していく、考えていくというのは。本区で国の学習指導要領を上回っているところは、本区一貫教育の特色であります英語科、市民科などの推進に必要な時数を増やしています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"さらに大変なストレスがかかっている状況でありますので、なるべく時間をあまりかけずに、早急に検討して具体化していただきたいと要望いたします。伺いたいのは、今年度中に、コロナで失われた１４０時間を全て取り戻す学校というのは、どれぐらい生まれているのでしょうか。７時間授業の実施というのは何校で行われたのか、全体の何割ぐらいで行われたのでしょうか。それも伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"基本的に学習のほうも、全ての時間をきちんとやることができないのですから、一つ一つの単元という、例えば算数の小数だったら小数を、本当は１０時間でやらなければいけないところを９時間や８時間でやっているということで、ねらいを達成するようにしています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"この時点で１４０時間は既に取り戻しているのがほとんどという状況なのかなと、答弁では伺いましたけれども、それをどう見るかということなのですが、まだ３学期にもなっていない時点で、もう取り戻したということになると、これまで相当な無理をしたのかなと思ってしまうのです。これが１点です。それが２番目です。これは具体的にはどういう対応なのでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"７時間授業のほうは、当初いただいていた数からすると、半数程度と認識していますが、既に学校では学習が追いついたということで、３学期は戻そうと考えているという声も聞いてあります。授業の工夫のところですが、私どもは個に応じた丁寧な対応をするため、例えば算数、数学などを少人数、例えば加配をいただいている場合は、２学級を３つに分ける、いわゆる３展開という言い方をいたしますが。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。そういうご答弁をいただきました。習熟度別というのはやめるべきだと私は思っています。この対応というのは、区もやっているのだと、場面に応じてやっているのだと度々言いますけれども、この対応というのは習熟度別で、学校生活を送る単位としてのクラスというのを、そもそもふだんから少人数にするということとは全く違うことだと思うのですが、いかがお考えでしょうか、伺いたいと思います。","respondent":"工藤指導課長","answer":"先ほど申し上げた少人数指導、いわゆる習熟度別指導も行ってありますが、そのほかに私ども区といたしましては指導助手ということで、各教科担任の授業の中に指導助手、それぞれ個別に児童・生徒を見るような人材も配置していますので、そういった場合は。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういうことだと思うのです。一つは、少人数なら一人ひとりが活躍する場が増えますと。子どもの学習体験を豊かにするのだ、活躍できるのだと書いております。私は先ほどの習熟度別ですとか指導助手では、このような少人数学級が持つ教育における本質的な生活面・学習面のメリットの代わりにはならないと思うのですけれどもいかがでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"そういったデメリットもある。だけれども、大人数については、先ほど委員がおっしゃったようなこともありますので、裏腹のところで、本区の現状としては、大人数と少人数をバランスよくやりながら、そのメリットとデメリットを見極めて進めていくというところがスタンスです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"提案","question":"やはり私は、大規模によるメリットというのを具体的に何と考えているのかを伺いたいのですけれども、後で聞かせてください。ですから、伺いたいのは、多様な子ども一人ひとりの個性を理解して、それを支えるのが私は教育の理想だと思いますけれども、今はそれが強く求められる時代になっていると思いますが、そういう実現のためには、少人数学級の実施というのは、私はプラスになると思うのです。","respondent":"矢部教育総合支援センター長","answer":"人数が多くても少なくても、多様性を認めるということは大変大事で、そのケースが多いといいますか、人数が多くなれば分母が多いわけですから、出会うことも多くなります。それを皆で一緒に考えて理解するという経験も、大人数の中でもできると考えております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"確認","question":"後日、議事録を確認してもらえばと思いますけれども、同じ趣旨の質問をしていることはないと思いますが、最後の意見に対しては、意見で終わりますけれども、大人数であっても少人数であっても多様性を認めることはできるとおっしゃいますが、一人ひとりの子どもたちが見られたり、支援されたり、あるいは発言できたり、表現できたりという機会が多いというのが、一人ひとりが活躍できるという点で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問・要望","question":"請願の第１６号のほうですが、先ほど午前中の答弁、やり取りで、5)番、用務主事の増員ということについては、学校から特に声は聞いていないというお話があったと思うのですが、1)から4)の、今、それぞれ質疑がありましたけれども、保護者の方とか、子どもたちからというのはないのかもしれませんが、主に保護者の方、また学校側から、例えばスクールカウンセラー、また少人数学級。","respondent":"工藤指導課長、篠田学務課長、矢部教育総合支援センター長","answer":"私どもの教育要領に関するところでいきますと、例えば英語科を１・２年生から教科として行っているところですが、これまで行っている保護者アンケート。ただ、先ほどからお話させていただいているとおり、少人数展開にしたりというときに、教室がいろいろと必要だとか。保護者からの声もございませんが、直接スクールカウンセラーを受けてもいいような事情をこちらが受け取るときがありますので。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"請願第１６号についてです。１番で、授業時数を削減してくださいということなのですけれども、実際、授業時数を削減してしまったら、教育効果に与える影響というのはあるのでしょうか。ほかの学年のお子さんたちとの公平性、同じような内容の授業を受けなければいけないと思っているのですけれども、実際に削減してしまったら、どういう影響があるのでしょうか。","respondent":"工藤指導課長","answer":"実際にという仮定のお話ではありますけれども、私どもが定めている標準授業時数というのは、国の学習指導要領、また、その内容はもちろん踏襲していますが、私どもの教育要領で定めている学習内容を定着させるのに必要な時数ということですので、それを削減するということは。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。当然、予算で人件費が、用務主事を増員するとかかってしまうのですけれども、人件費はどこが増員というお求めなのか分からないのですが、かかるとしたら人件費と、繰り返しになりますけれども、現状の対応で消毒は十分なのか、この２点をお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"そのためには、教員の方たちやスクールサポートスタッフの方たちも、職員室だとか、そういうところで当然協力してもらっているとは思いますけれども、基本的な手すり、ドアノブ、スイッチといったところは、きちんと用務の方のほうで対応できて。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"費用対効果というのも考えなくてはいけないのかなと考えています。消毒は十分できているということで、分かりました。これで教室が狭くなって、先生が通路が狭いので通れなくなっているというお声も聞いておりますので、そこの辺りの改善を、なるべく現在の環境で工夫してできることはないのかなと思っているのですけれども、その辺りについて、どうお考えなのでしょうか。","respondent":"篠田学務課長","answer":"ただ、相当厳しくなっている学校もありますので、そういった学校に関しては、新たに外に何らかの形で、仮設の校舎みたいなものを造るのかどうかといったことも含めて、検討していく必要はあろうかと考えているところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。それで、２０人ということなのですけれども、３０人で今、国が相当そのことで争点になっているときに、いきなり２０人ということなのですが、２０人学級というのは今の品川区で、やろうと思えば可能なのでしょうか。","respondent":"篠田学務課長","answer":"２０人というのは、学級編制を２０人にした場合という形で捉えますと、これは第３回定例会のときにもご答弁申し上げたとおり、単純にいけば、教室数が倍近くになりますという話ですので、今ある数、七百何十教室を、一気に１,５００ぐらいの数にするというのは。","id":"exchange-033"},{"speaker":"芹澤副委員長","kind":"質問","question":"本日、結論を出すで、不採択でお願いします。それぞれの項目をご説明いただきましたけれども、中には既に実現しているものと、あとは今、お話がありましたとおり、実現がなかなか不可能に近いものが多くありますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せお委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いします。今、自民党もおっしゃっていたように、私たちの会派でも、一部実現しているものもありますし、不可能なものもありますということで、今の品川区の現状では不可能かなということで、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"たけうち委員","kind":"確認","question":"不採択でお願いします。質疑で確認させていただいたとおり、そういう保護者、また関係の声というのはそれほど多くない、もしくはほとんどないと承っているところですし、また、人数に関して言えば、少人数というのは確かにあるでしょうけれども、区独自でという、どこを目指しているのかがよく分からない部分もあります。そういったことで、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"ほかの様々な項目についても、これまでも国連子どもの権利委員会から、既に再三にわたり、過度な競争教育が指摘をされて、その下での子どもの権利が危機になっているということが指摘をされてきていましたけれども、その矛盾がこの中で一層浮き彫りになっているわけですから、加速しているわけですから、どの子も安全に楽しく学べる環境を保障するために、私は採択すべき内容だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"筒井委員","kind":"確認","question":"本日、結論を出すで、不採択でお願いいたします。必要な授業数はやらなくてはいけないですし、あと、様々、先ほど答弁で確認させていただきました。それを踏まえて、今回は不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"項目は５つに分かれておりますけれども、特に今年はコロナということですので、授業の時数が非常にイレギュラーなことになりました。スクールカウンセラーについては、午前中も言いましたけれども、現状で満足することはなく、様々な心のケアの仕組みを整えていただきたいと思いますし、それから５番目のほうも、学校の教職員も用務主事も、増務になっているのは確実だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。それぞれの質疑ですとか、ご答弁をお伺いしてまいりましたが、特に学級編制については、法の規定や都の基準にのっとって対応していただいて、教える教科、単元、内容によって、少人数指導や習熟度別学習などを適切に実施していただきたいと私は考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"芹澤副委員長","kind":"意見","question":"本日、結論を出すで、同じく不採択でお願いします。そういう意味では、３０人の少人数学級は、わざわざ意見書を出すまでもなく動いているかなと思っていますが、ここに、１学級の人数を２０人程度にすることは必須の条件と書いてあって、２０人というのは、どのエビデンスを持って出てきたのかがまだ分かりませんので、不採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"せお委員","kind":"質問","question":"本日、結論を出すで、不採択でお願いします。先ほど質疑でもありましたが、３０人ですけれども、文科省で少人数という発言もあって、あと答弁で、法改正があったら対応していくという話がありましたが、そこら辺は長期的なビジョンとかを持って学級編制を考えて、シミュレーションとかだけはしておいてほしいと思っています。ただ、現実、２０人というのは不可能に近いと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"何で子どもたちだけが、アナウンサーがテレビで離れてしゃべっていますけれども、そういう場面を見せつけられているのに、自分たちはずっとソーシャルディスタンスを取れないのだという問題もありますし、欧米などを見てみますと、子どもの規模をもっと少なくして、教育の質の面からも、そういう流れが出ていますので、私は２０人学級を展望して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。よって、不採択としますけれども、先ほど述べましたとおり、現在起きている課題の解決のためと、少なくとも３０人学級に向けての備え、準備という点で、今できること、転用とか、そうした工夫をぜひ検討していっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"単に国が決めたらやりますではなくて、地方としても３０人というのは歓迎するという形で、同じ目標で動いていただけるといいなと思いますし、それから先、３０人よりさらに減らしていくかどうかというのは、今、日本の学級編制は上限規定になっているので、それを３０人よりさらに、上限規定のままで減らすというのは、あまりにも学級編制が小さくなり過ぎる可能性があるので、そこはまた数字ではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"本日、結論を出すで、採択なのですけれども、こちらの陳情でも２０人程度にと書いていますので、クラスそのものを２０人ぐらいの規模にするようにしてほしいということだと理解しています。クラスを２０人程度にするというのは、一人ひとりの子どもに行き届く教育環境を実現することになりますし、私はメリットは大きいと思います。コロナなどの感染症対策にもつながると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日、結論を出すということで、不採択でお願いいたします。繰り返しになりますけれども、国が３０人学級として打ち出しているということで、先ほども言いましたが、７割の学級というのは既に３０人以下になっているわけですから、それ以上の学級を抱えている自治体が、積極的にこの３０人学級というのをぜひ応援していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-04","title":"令和２年陳情第５５号、学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情","agenda":"令和２年陳情第５５号、学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"学校のほうは休止ということはまだ出ていないのですけれども、そういう考えは表明されていないのですが、なぜもっと影響を受ける小さな子どもたちが通う保育園のほうは、休止という方針が既に発表されているのか。私は継続すべきだと思うのですけれども、いかがでしょうか。つかんでいらっしゃるところがあれば、伺いたいと思います。","respondent":"立木保育課長、篠田学務課長","answer":"それから他区の状況ですが、２３区の状況ですと、令和３年度実施予定は、品川区を含めまして１１区あります。令和２年度も実施は１１区ということで、今のところ把握をしているところです。これまで、ピーク時では２３区全体のうち２１区で検査を実施してきたところですが、今のところ大体半分ぐらいになってきたというような状況です。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、休止という判断はやめたほうがいいのではないですか、むしろ継続したほうがいいのではないですかという、なぜ保育園のほうはそのように舵を切ろうとしているのかが分からなかったので、伺ったのです。反対ですとか慎重な扱いを求める意見書が県議会、あるいは県内５９市町村のうち４１市町村議会で可決をしているという状況もあります。","respondent":"立木保育課長、篠田学務課長","answer":"保育園のほうだけ休止という言葉を使っているですけれども、休止という言葉を使っておりますが、区内の子どもたちのことですので、当然教育委員会ともちゃんと連携を取って、今後細かいところは詰めさせていただきたいと考えていますが。今この時期に、どちらかといえば拡充ではないかというようなお話です。私どもも１０年間にわたって検査を続けてまいりまして、教育委員会のほうでは１件も検出されてきていないという状況があります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"それをやめてしまうということは、あってはならないのではないかと思います。最後、陳情に少し書いていますけれども、一部に検査することそのものが福島の風評被害を生むという議論がありますがということで書いていますけれども、区としては検査するということそのものは、この風評被害を生むとお考えになっているのでしょうか。それも伺いたいと思います。","respondent":"篠田学務課長","answer":"ただ、今回こういった形で、福島県のものということでクローズアップされた中で検査が始まったということですから、どうしても福島県との絡みというのは、これは私どもだけではなくて一般の区民の方から見てもそういう態勢で見ておられるだろうなということからすると。","id":"exchange-050"},{"speaker":"安藤委員","kind":"確認","question":"やはりそれを防ぐためには、しっかりと検査を行うということが、そういう事実をもって安全性を確認することになるし、むしろ風評被害を防ぐことになるのではないかと私は思いますので、これはしっかりと継続をしていく必要があると考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問・要望","question":"原発事故からもうすぐ１０年が経つわけですけれども、基本的なスタンスとして、私自身は放射能に対する警戒そのものは解いてはいけないと考えています。それをそれぞれ教育委員会なり保育課のきちんとした担当を、別に専門でなくてもそういうことをし続けるという体制だけは残していただきたいと思うのですけれども、いかがでしょうか。","respondent":"篠田学務課長、立木保育課長","answer":"給食の担当は別にこの放射能検査だけをやっているわけではなく、通常の給食業務と一緒にやってきたということがございまして、例えば食材の検査だけではなくて、これまでも過去には、例えば牛の干し草から放射能が出たということで。今後も引き続き、正しい知識を子どもたちに伝えるということも大事だと思っていますので、そういったことも含めてしっかりとやっていきたいと考えています。","id":"exchange-052"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この放射性物質についての食品検査というものは、東京都と、またさらにその食材の生産地でも検査が行われていて、そして問題がないとされているものが流通しているという理解でよろしいのでしょうか。","respondent":"立木保育課長、篠田学務課長","answer":"生産地のほうで、きちんと自治体のほうで出荷にあたりまして検査をした上で流通しておりますので、安全なものが流通していると考えてよろしいかと思います。食材に対する流通上の問題ですので、これはあくまでそれぞれの産地の中で間違いのないものが、国の施策の中で流通していると考えているところです。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"東京都でも検査されているということでよろしいですか。その点もお伺いしたいのですけれども。","respondent":"こんの委員長","answer":"筒井委員、今のご答弁で、いわゆるそういうものが、東京都も含めて検査しているものが流通されて、それを使っているのでというご説明と私たちは理解しています。ご答弁はちゃんとされたと思いますけれども。","id":"exchange-054"},{"speaker":"筒井委員","kind":"質問","question":"生産地はもちろん、生産地と東京都、両方ということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。それで、陳情の要旨（２）で、１８歳未満の入所者のあるすべての施設でも検査をお願いしたいということなのですけれども、品川区では今まで学校給食、保育園の給食のみ検査されていたということでよろしいのでしょうか。（２）のように、１８歳未満の入所者のあるすべての施設で検査されていたということはあったのでしょうか。","respondent":"篠田学務課長","answer":"私どもも担当ではないものですから、細かいことは把握してございませんけれども、基本的に区の中でそういった施設があったとしても検査をしているといった事例は聞いたことがないので、そういった対応は取っていないのではないかと思います。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"一旦休止というご答弁が再三あったかと思うのですけれども、先ほど福島の処理水放出の件とかがありましたが、当然状況によっては、また再び放射性物質に関する事故とかが起きた場合は、それは柔軟にやはり適宜対応、また再開ということもあり得るという理解でよろしいのでしょうか。","respondent":"立木保育課長","answer":"一旦検証をした上で中断することになりましても、また必要に応じてそういったものにすぐに対処できるようなことは常に頭に置きながらと考えているところです。","id":"exchange-057"},{"speaker":"芹澤副委員長","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由としまして、約１０年間検査をしてきて、先ほど一定の成果というお話がありましたが、この成果というのが納入前の検査と品川区の検査に相違がない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"せお委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。（１）のほうですが、先ほどからお話がありますように、一旦休止するということがあっても、またアンテナを張っていただいて、あと何かあったら検査していくというお話がありましたので、そこら辺を必ず実施していただければいいかと思います。（２）のほうは、コストなども考えて現実的ではないと思いますので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"たけうち委員","kind":"意見","question":"理由としては、ずっと１０年間続けてきて、また来年度まで計画に基づいてやられるということで、ある意味では来年度までは継続なのかと思うのですが、その後も廃止というよりは一旦休止して、状況を見ながら対応していくと。（２）については実質、なかなかぴったり当てはまるような施設があまり該当しない中で、また拡充ということについては難しいと考えていますので、不採択ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由としましては、先ほど冒頭でありましたとおり、東京都と食材の生産地でしっかりと検査されており、それで問題ないものが流通されているということでありまして、品川区も検査していましたけれども、１０年間問題がなかったと。さらに何か特段の状況に陥れば柔軟に再開ということもあり得るということを伺いましたので、以上の理由で不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。今後は検査という形ではなくて、情報収集という形でこの問題に引き続きあたっていただきたいと思います。ふだんから情報収集をするとともに、何かあったらすぐにまた検査に戻せるような形でいっていただければ、そういう体制を取っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。検査については、これまでの経過と今後の検査結果や情勢の変化、また他自治体の状況ですとか運用のリソースに関する課題など、引き続き子どもたちの安全確保のために総合的に対応をしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"}]},{"id":"topic-05","title":"議案審査に戻りまして、(6)第６３号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"議案審査に戻りまして、(6)第６３号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"子ども食堂の運営費補助ですけれども、今回手が挙がったのは６施設ということですが、全食堂から希望を伺ったと伺いましたけれども、その中で子ども食堂運営主体者の現状とか要望ですとか悩みですとか、区として、もしつかんだことがあれば教えていただきたいと思います。やはり不要不急な事業は大胆に見直すなど、大局を見て財政出動とか公助というのはやはり大事なのではないかと。","respondent":"三ッ橋子育て応援課長、吉田保育施設調整担当課長、若生保育支援課長、有馬庶務課長","answer":"例えば今、コロナ禍においてフードパントリーを実施するにあたっても、確かに消毒など非常に気をつけながら実施しているということ。引き続き現場と確認しながら、必要なものは充足させるとともに、また心の支援等のバックアップを行っていければと考えています。ただその一方で、どうやって園内の感染を防いでいくかというところの情報提供、どういったやり方があるかというところでは。残念ながら中止とした学校は７校です。残りの６校につきましては、一応３月ということで予定をしているものです。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"あるのは勉強とテストだけなのだといわれてしまったそうなのです。区の教育委員会としても、そういう学校での工夫を後押しするような柔軟な環境ですとか、あるいはそういうのを現場に提供してあげてほしいという思いがあるのですけれども、そこら辺はいかがでしょうか。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"修学旅行が未実施だった学校については、どこかで判断しなければいけませんので一応中止にしていますが、今でも代替案を考えるという学校もありますし、これまでも基本的には実施するという方向でこちらも促してまいりました。生徒が工夫しながら何か考えてということ、それはそれぞれの学校がそれぞれ考えて、思い出づくりに取り組んでいるということもありますし、このたびの決算特別委員会でのご意見を受け、教育委員会が背中を押して。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、中止になってしまったところ７校というのは、やはりもう大体中止になって終わりというのではなくて、ほとんどはそういう代替的なものを何か実施される予定になっているのかというのが１つと、それと３月に延期になったところが、仮に感染状況などでどうしても、ぎりぎりなのですけれどもそこで中止になってしまったという場合は。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"１点目についてお答えしたいと思います。７校中、数はまだ十分把握できてございませんが、代替を考えているということで、こちらとしては日帰りとか近い距離でということでご案内をしております。今後予定している学校、３月に無事に行けたらぜひ行っていただきたいと思いますけれども、感染状況で万が一そういうことになれば、ほかの学校と同様、キャンセル代等については公費負担をしていきたいと考えております。","id":"exchange-066"},{"speaker":"たけうち委員","kind":"質問・要望","question":"子ども食堂ですが、ここに６施設ということなのですが、そうするとほかの施設については、今こういうコロナ禍の中で子どもたちが来ることを心配して、今、本来の子ども食堂の活動も休止してしまっていて、それで致し方なくお弁当とかそういう部分でこの６施設が手を挙げたという理解なのか、今通常の子ども食堂の活動はもう再開されているのか、その辺の状況が分かれば教えていただきたいのが１つです。","respondent":"三ッ橋子育て応援課長、若生保育支援課長","answer":"通常開催が５カ所あります。その中で、コロナで中止をしているところが一方で４カ所あります。こちらで６カ所今回申請していただいたところは、すべてフードパントリーを実施しているところ、また通常開催されているところもあります。保育園等に対するクラウドファンディング等で寄附いただいたものを活用させていただいてというところで、今回基本的に金額等もそこまで大きくないというところもございまして、物品等で工夫をする形を取るということで。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問","question":"申請しなかったところは何でしなかったのでしょうか。なぜ６カ所だけの申請になったのかは把握されているのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"今回、子ども食堂につきまして、６カ所の中で、この補助金と申しますのは、新型コロナウイルスにおきまして影響を受けている、そしてその中でフードパントリー等を実施しているところであったり、内容が東京都の内容に基づいて対応しています。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問","question":"すみません。お金が要らないというだけのことではないのではないかと思うのですけれども、そこら辺はもう少し突っ込んでいないのですか。ある程度の規模のところではないと駄目とか、申請したいけれども、この条件があるからできなかったところがあるとか、そういうことは把握されていますか。","respondent":"三ッ橋子育て応援課長","answer":"しかしながら申請してこなかったということで、特に書類も難しいものではないですし、内容につきましても十分ほかの補助金をもらっているところもあると思われますので、これを使わなくても対応できているのだと考えています。","id":"exchange-069"},{"speaker":"あべ委員","kind":"質問","question":"今のお話を伺っていると、結構広範に補助が出るにもかかわらず、休止中もありますけれども、２４カ所あるうちの実際に稼働しているのが１５カ所で、申請６件というのはどうも腑に落ちないのです。","respondent":"三ッ橋子育て応援課長","answer":"今回、申請は一旦締め切らせていただいているところですけれども、実際に第３回の募集が東京都であるのかどうかは確認しますが、今回にあたりましてはもう募集期間を終わっていると認識しておりますので、申請をされていないところに対しては。","id":"exchange-070"},{"speaker":"横山委員","kind":"質問","question":"そして補助の内容についてなのですけれども、これまで現場のほうからどのような意見がありますでしょうか。実はこういうものが欲しいけれども、補助の中ではちょっと買えないので困っているということがあるのではないかということを懸念しているのですが、そのあたり、現状をお聞かせください。","respondent":"若生保育支援課長","answer":"そういったお声も伺いながら、今後も感染防止対策に総合的に対応してまいりたいと考えています。","id":"exchange-071"},{"speaker":"横山委員","kind":"質問・要望","question":"そういった様々な現場との意見交換ですとか要望を吸い上げていただいているということで、安心をいたしましたけれども、またそうした現場の情報、ニーズですとか意見といったところを、例えば国や都などにそうした意見・要望をスピーディーに情報共有するなどの働きかけもお願いしたいと思うのですが、そうした情報共有の現状についてもお聞かせいただけないでしょうか。","respondent":"若生保育支援課長","answer":"今後ともそういったところを活用しながら、適切に要望を上げていきたいと考えております。","id":"exchange-072"},{"speaker":"筒井委員","kind":"確認","question":"この感染拡大防止対策物品購入費についてなのですけれども、保育園とか幼稚園のもので、これは物品の対象を限定しているとかはあるのでしょうか。こういう品物でないといけないとか、それを確認したいのですけれども。","respondent":"若生保育支援課長","answer":"今のところ一つに限定をしているのではなく、幅広く選べるような形で複数の物品をこちらのほうで選定して、それでご希望に応じて選んでいただくという形を想定しているのですけれども、何にするかという特定に関しては。","id":"exchange-073"},{"speaker":"筒井委員","kind":"提案","question":"ある程度ご提案されるということなのですけれども、これから寒い時期になってきまして、乾燥というのもある程度防がなくてはいけませんし、また換気もかなり有効にやっていかなければいけないということもあるので、こういった季節、これからの寒い冬の時期に対応した物品の選定、提案というのもぜひ行っていただきたいと考えていますが、そのあたりはどのようにお考えでしょうか。","respondent":"若生保育支援課長","answer":"そういったご意見等々も園のほうにお伺いしながら、今のところこちらで想定しているものはあるのですけれども、ご案内いただいたようなご要望がございましたら、柔軟に対応してまいりたいと考えています。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"１点だけ、先ほどの子ども食堂のあべ委員の質疑の中で申請が６カ所というのがあって、私もちょっと少ないかなと思ったのですけれども、申請が終わってしまったということで、今後に活かすためにアンケートを取ったりとか、お声を聞いたりとか、そういうことをしたりする予定はないのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"今回の子ども食堂のこの補助金に関して、期間を長くて取って、なおかつネットワーク事務局とも何回もやり取りをしておりまして、各子ども食堂も十分理解した上での申請と捉えておりますので、また改めてアンケートを取ることは今のところ考えていません。","id":"exchange-075"},{"speaker":"芹澤副委員長","kind":"確認","question":"１０分の１０なので少ないと思うのですが、これは私もぱっとしか見ていないのですけれども、同趣旨の補助を受けている場合は申請できないみたいなことが書いてあったように思っていて、子ども食堂というのは飲食店の経営されている場所でやっていたりとかいうのがよくあると思うのですが、例えばそこの飲食店のほうで販路拡大なり何なりいろいろな感染症対策の補助金を例えば申請されている場合。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、例えば飲食店が子ども食堂をしているところも、申請しているところは実際にありますので、それは大丈夫です。","id":"exchange-076"}]},{"id":"topic-06","title":"議案審査に再び戻りまして、(1)第６６号議案、品川区立保育所条例の一部を改正する条例","agenda":"議案審査に再び戻りまして、(1)第６６号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"三ツ木保育園と八潮西保育園は民営化対象園ですけれども、なぜ民営化の直前に建替えや大規模改修行うのか、民営化との関係は何なのでしょうか、伺います。それと、ひろまち保育園のほうですけれども、６月の当委員会で報告がありました在園児３１名の優先転園の結果はどうなったのか。子どもや保護者の評価はどのように聞いていらっしゃるでしょうか。伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"現在のところ、優先転園ができなかったという方はおりません。それから、ひろまち保育園の現在の運営状況についてというところですけれども、事業者変更後は特に問題もなく進んでまいりまして、現在は閉園に向けた準備を進めているところです。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"定員が多いひろまち保育園が縮小、なくなることで、周辺地域、あるいはここは最も厳しい１歳児園ですので、１歳児の入園ですとか、あるいは２歳児までしかいられない認証保育園の在園者などに、やはり厳しい影響が出ることになると思うのですけれども、いかがでしょうか。それをカバーする方策というのは区は持っていらっしゃるのでしょうか、伺いたいと思います。","respondent":"立木保育課長","answer":"そのほかご希望されなかった方が３名いらっしゃるのですが、そういったご希望された方の転園先のほうは、すみません、どちらにということは今手元にないので個別には申し上げられないのですが、今回の優先転園による来年４月の入園枠への影響というのは。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"３１名の方が転園を余儀なくされる、あるいは３名の方は希望しないということは、これを機会に保育園を退園してしまうということだと思うのですけれども、せめて今いる在園児が最後まで、この園で卒園するまで存続するべきだと、保育部門として思わないのかなと私は思うのですが、それができない理由を具体的に改めて伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"ひろまち保育園につきましては、開園当初より５年間の期間限定園ということで進めてまいりました。そのため、平成２８年から数えまして５年間になります今年度をもって、閉園することにした次第です。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのはこれができない理由で、別に今のはできない理由にならないと思うのです。約束していましたという、約束したかもしれませんが、約束したにしてもしていないという話もありますし、不十分という話もありますし、仮に百歩譲ってそうだったとしても、それはやはりできない理由にはならないと思うのですけれども、もう一回お伺いします。","respondent":"吉田保育施設調整担当課長","answer":"大井町周辺の開発の関係もありますけれども、都市計画部門とともにＪＲと調整した結果、来年度以降、現在のひろまち保育園がある場所を使うことが難しいところもありましたので、今年度予定どおりの閉園ということにさせていただいてあります。","id":"exchange-080"},{"speaker":"あべ委員","kind":"確認","question":"保育園の移転のほうなのですけれども、三ツ木保育園は前も出ていたかもしれませんが、どのくらい距離があるのでしたっけ。はそこの確認をお願いします。","respondent":"吉田保育施設調整担当課長","answer":"三ツ木保育園と新しく移転する先の間の距離ということかと思います。約１km程度と考えております。","id":"exchange-081"},{"speaker":"あべ委員","kind":"質問","question":"転園ですから、全体のキャパシティから言えばプラス１、マイナス１なので、保育行政としては大きな負担にはなるわけではなく、かつお子さんの年齢や兄弟の状況などによっては、やはり一定の距離以上のところというのは、むしろ転園を認めるということも、優先転園の仕組みを作るということも一つの考え方ではないかと思うのですが、これまでやっていなかったのは承知していますけれども。","respondent":"立木保育課長","answer":"そうした中で適用できたのがひろまち保育園、それからほうさん保育園ということになるのですけれども、それ以外、こういった例えば改築にあたって、通常１kmですと、ある程度通える範囲というところで。","id":"exchange-082"},{"speaker":"あべ委員","kind":"質問・要望","question":"すぐに結論が出る問題ではないかもしれませんけれども、やはりもともとの園のすぐ近くであれば１kmなんですが、既に遠くてさらに１kmとなると、かなり毎日のということを考えると負担にもなってくるかと思います。ぜひご検討をいただければと思います。要望にしておきます。それともう一点、ひろまち保育園ですが、こちらの事業者は今年度以降どうなるのかということも教えてください。","respondent":"吉田保育施設調整担当課長","answer":"契約のときから、閉園した際に、自社で本人の希望を聞きながら別の園だとか、そういうところに移れるようなことができるようにということをお願いしているところがありますので、閉園した際はそのような対応を取るものと考えております。","id":"exchange-083"},{"speaker":"あべ委員","kind":"質問","question":"多分関係者の中でも、園の毎年の保育展などに足を運ばれているだろうと思っているのですけれども、あれだけの保育をされている保育園というのは品川区内の中でもやはり上位に入るのではないかと考えています。むしろ、今後の品川区の保育に積極的に活かしていっていただくほうが、区の保育のためではないかと思うのですけれども、そうした視点はお持ちでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"確かにおっしゃるとおり、ひろまち保育園を作るときに、元品川区の職員が何人か勤めているというところもあります。今後、その辺がどうなるかは難しいところもありますが、考えてまいりたいとは思っております。","id":"exchange-084"},{"speaker":"安藤委員","kind":"意見","question":"態度は反対なのですけれども、老朽化した区立園の建替えの必要性は理解するところなのですけれども、南ゆたか保育園について行政上の目的であり、異論はありません。しかし三ツ木保育園、八潮西保育園の所在地変更については、やはりやるべきでない民営化を前提にして、改築してきれいな保育園を民間に渡していくための住所変更だということで、賛成できないと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-07","title":"第７５号議案、指定管理者の指定","agenda":"第７５号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この選定委員会の有識者なのですけれども、２名というのはどのような分野のどのような肩書の方なのか、なぜその方々を選んだのかを伺います。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"有識者２名です。こちらは８月の総務委員会に資料が出されているのですが、今年度、外部委員の導入をいたしております。これまで対応していた虐待の対応ですとか養育困難の対応については、これも順次今引継ぎをしておりまして、来年度からはすべて子ども家庭支援センターが担当するといったことで進めているところです。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。これを所管としてはどう両立しようと考えているのかを伺いたいと思いますし、それぞれの選定基準についての点数というのが書かれていないのですけれども、これはなぜなのかというのを併せて伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"経費縮減についてのご意見もございました。委員がご指摘のように、確かに福祉部門におきましては、やはりサービスの向上と経費の縮減というのは非常に難しいバランスがあるということもご意見としていただいておりました。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、選定基準の（３）なのですけれども、管理を安定して行う物的能力および人的能力を有しているというところで、その対応している理由が、経営基盤、公認会計士のみとしか書いていないのですけれども、これはちょっと、それは関わらないとは思いませんけれども、そういう問題なのかなと思っていまして、これだけなのですかというか、人的能力という意味では。","respondent":"三ッ橋子育て応援課長","answer":"人的能力につきましては、例えば組織体制のところで家庭あんしんセンターですと、すべてそうですけれども、国の基準よりも定数が、多くの人数で対応しているということが大きいと思われます。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"聞けばいろいろと答えていただけるのですけれども、そういったところはやはり大事な点だと思うので、ここの文面では全くそういうのが見えてこないので、またしっかりと区民に運営実態を明らかにするためにも、そこら辺はきちんと記載を今後充実・工夫していただきたいと重ねて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"あべ委員","kind":"提案","question":"この事業は継続性が大切だというのは分かるのですが、もう何年もやっているところですので、今回選定理由の中で提案ですとか計画といったところが書いてあるのですけれども、これまでやってきたことの評価はどうなっているのかというのが、この資料からは全く分からないのです。もしやっていたのだったらどのような評価でしょうか。これまでの事業の評価というのをどのように見ているのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"委員の言われましたようにアフターケアの部分ですが、これまでも退所された方に対しても十分なアフターケアをしておりまして、実際にご相談であったり、また行事に呼ぶなど、切れ目のないように対応しています。","id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"本当にニーズに応えていけるのか、それとも自分たちのペースでしかサービスを提供していないのではないかというような疑問を持っているのです。そこはもう十分にニーズに応えているという評価の中で、再度こちらを指定管理者にしようということなのでしょうか。区としては十分だと思っているのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"そのときそのときのニーズもやはり変わっていくことも考えられますので、今あるニーズに対しては応えていきますし、今後の令和３年からの事業計画の中においても、実際にこのようなニーズに応えていくという提案をなされているところです。","id":"exchange-091"},{"speaker":"あべ委員","kind":"質問・要望","question":"それと今回指定管理者の指定については、この指定管理料というのは出てきていないわけですけれども、これは前回の５年間と金額的には、例えば横ばいなのか下がるのか上がるのか、数字が出せれば数字を出していただければと思うのですが、どのくらいになりそうなのでしょうか。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"ニーズにつきましては、確かに委員おっしゃるように右肩上がりだったと思われますので、それに対応していけるように、この指定管理者候補者に対して求めていこうと考えています。そういった部分で言いますと、相談の業務について一部区の直営化を図ったところでありますので、そういった部分も含めて、来年度以降の予算については検討を進めているところです。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"右肩上がりにニーズは増えているという見解が共有できてよかったと思います。それから予算のほうなのですけれども、予算を見ていますと年間でこのあんしんセンターは大体５,６００万円ぐらいかと思います。今後あんしんセンターでは、本年度と来年度以降、次の指定管理では子育て支援センター部分に関わる人数というのは変更があるのでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"今委員からお話がありましたように、令和３年度からの基本計画書の案をいただいているところなのですけれども、そこでも子育て支援センターの人員については今年度よりも減ということでいただいておりまして、それを精査させていただいた上で。","id":"exchange-093"},{"speaker":"あべ委員","kind":"意見","question":"実績と経験を持った方々がそれをどこかで活かせるような形で、しかしながらその業務に応じた組織にしていただければと思います。こちらの選定理由の中で経営基盤が良好とありますけれども、業務が大きく減っても同じ金額である。それは確かに経営基盤が良好になると思うのです。そういうことではなくて、しっかりと運営の面での健全性というのを図っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"横山委員","kind":"提案","question":"７番の部分なのですけれども、アフターケアについてです。退所後も関係機関と連携したアフターケアを実施する提案がなされたこととあるのですけれども、こちらはこれまではどういった機関と連携をしてきたのかを教えてください。事業計画書の案が提出されたということなのですけれども、今後の人材育成についての考え方、何か計画にありますでしょうか。そのあたりも教えてください。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"退所後の関係機関につきましては、子育て応援課であったり、子ども家庭支援センターであったり、こちらが関係機関と捉えております。委員ご指摘のように、漏れのないように対応してまいりたいと考えております。","id":"exchange-095"},{"speaker":"横山委員","kind":"提案","question":"アフターケアの新たな提案というのは、今回なかったということなのでしょうか。人材育成の部分について、ご答弁をお願いできたらと思います。","respondent":"三ッ橋子育て応援課長","answer":"アフターケアの新たな部分ですが、同様と捉えております。人材育成に関しましては、やはり人事異動などで新人が来る場合などがありますので、そちらに関しましても研修をしっかりとすること、また質の高いサービス提供ができるようにしていくことと捉えております。","id":"exchange-096"},{"speaker":"横山委員","kind":"質問・要望","question":"人材育成についても、新しい方というのもいらっしゃると思うのですけれども、子ども家庭支援センターですとか、またこちらのひまわり荘ですとか、様々な経験のある方がいらっしゃると思いますので、そうした区が常に持っている経験とか知識などを新しい方にうまく伝達したり、共有したりということもぜひ進めていただきたいと思っていますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"あべ委員","kind":"質問","question":"トワイライトステイなのですけれども、今年齢の下限の制限があったと思います。ただ、虐待死などは１歳未満が大多数なのですね。そういうことを考えると、今たしか１歳６か月以上でないと預けられなかったかと思うのですけれども、その指定管理が代わるタイミングでも、これをもう少し広げられるようにぜひ法人と話をしてほしいのですが、いかがでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"この家庭あんしんセンターで実施をするのか、それとも乳児院で実施をしていくのかというところについては、今後引き続き検討していきたいと思います。","id":"exchange-098"},{"speaker":"あべ委員","kind":"意見","question":"賛成ではありますけれども、長年同じところに指定管理をさせていることが影響しているのかどうか、やはりより改善をしていく、それから委託費用などのお金の面についてもきっちりと積算が外に出せるような形でしていくということ、もう一度この機会に見直しながらやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"}]},{"id":"topic-08","title":"第７６号議案、指定管理者の指定","agenda":"第７６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"こちらについてもかなり簡素な資料なので、ぜひ所管としてはもう少し充実していただきたいということを要望しつつ伺いますけれども、同様に有識者２名はどのような分野のどのような肩書の方なのでしょうか。なぜその方々を選んだのでしょうかというのが１つです。","respondent":"吉田保育施設調整担当課長","answer":"そのため今回の指定管理期間が３年間というのは、当初決めた残りの残有期間と認識しています。","id":"exchange-100"},{"speaker":"安藤委員","kind":"提案","question":"ちょっと理解できないところがあるのですけれども、私が先ほど伺ったのは、選定理由の（１）というよりも（５）のほうを伺ったのです。これは要するに保育士が引き継がれますよという提案のことなのか、この７の（５）はどのような提案がなされたのかというのを伺ったので、それだけ最後に聞かせてください。","respondent":"吉田保育施設調整担当課長","answer":"そちらにつきまして、区としても十分に大事な施設として考えているところと、あとはこの７の（５）というところにはそれを１６年間ずっと続けてこられたというところと、あとはこの仕組みを維持したまま、次の福栄会にその職員。","id":"exchange-101"},{"speaker":"あべ委員","kind":"質問","question":"とすると、今回福栄会というのは、保育や教育についての実績を持たない法人なのです。とすると、外形的に社会福祉法人ということではありますけれども、保育の施設の指定管理をするにあたって、保育・教育の実績が今のところゼロであるという法人に移行させるということに外形的に躊躇はなかったのか。指定管理でそういうことをしていいのかという思いはなかったのですか。","respondent":"吉田保育施設調整担当課長","answer":"社会福祉法人の福栄会を紹介するにあたりまして、ＮＰＯ子育て品川のほうからも、ぷりすくーる西五反田におけるこれまで１６年間培ってきた乳幼児教育について、引き続き提供できる社会福祉法人というのを望まれたところです。","id":"exchange-102"},{"speaker":"あべ委員","kind":"質問","question":"母体がそっくり法人に入るということなので、その母体というのは何ですか。母体というのは通常組織を指す言葉だと思いますけれども、どういう組織がＮＰＯから法人に内包されることになるのでしょうか。ちょっとそこを具体的に教えてください。","respondent":"吉田保育施設調整担当課長","answer":"ご説明が雑駁で申し訳ございませんでした。組織としましては保育士の部門と、現場における事務部門、それから現場における管理をしている部門、そこの今現在ＮＰＯ子育て品川が運営していた部門がそのまま福栄会のほうに行くという形になります。","id":"exchange-103"},{"speaker":"あべ委員","kind":"質問","question":"ＮＰＯの理事も福栄会の理事に入るということなのですか。今、そういう答弁があったので、そうすると、逆にそういう条件があればここに移したいと思うＮＰＯの気持ちは分からないでもないですけれども、それはあまりにも心情的なものであって、指定管理者制度とその事業者の変更という意味で、それが妥当なのかどうかというのは、お話を伺っていて余計にちょっと不明瞭になってきました。","respondent":"吉田保育施設調整担当課長","answer":"ぷりすくーるを運営をするために、ぷりすくーる運営委員会というものを新たに福栄会のほうで立ち上げます。そちらの委員になるというところが、全員ではありませんが、ＮＰＯ側の一部の理事の参加する場所となります。","id":"exchange-104"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはぜひ強調しておきたいと思います。福栄会は障害児施設なども運営している法人ですので、ここの選定理由に全く出てきていないのですけれども、こうして幼児教育・保育を行うのであれば、そうした面を逆に活かしていくということもぜひアピールをして実施していただきたいところなのですが、そこについて全く触れられていないのは大変残念なのです。そうした話は出ているのでしょうか。","respondent":"柏原子ども未来部長","answer":"その後についてはこの事業をやっていきたいという区の思いもあったので、今のＮＰＯに指定をしたのですが、社会福祉法人化というところにはまだ課題が残っていましたので、それをずっと検討していたというところがあります。","id":"exchange-105"},{"speaker":"あべ委員","kind":"質問・要望","question":"いろいろと課題があると思いますが、賛成はいたします。ただ、この指定管理の持つ制度的な危うさというのをぜひ前例にはしないでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"}]},{"id":"topic-09","title":"令和２年請願第１４号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和２年請願第１４号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"そうすると、この入園料１０万円補助ということで、実際に所得によって若干お支払いされている差額が違ってくるとは思うのですけれども、大体平均して入園料にどのぐらいの負担が出ているのか。その２点をお願いします。","respondent":"若生保育支援課長","answer":"ただ、品川区におきましてはこれまでも就園奨励費という形で補助していた部分がありますので、そういったところを今回上乗せの部分として、園児保護者補助金という仕組みは残した上で負担軽減を図っているというところで、保育料等はそれぞれの園によって異なるので。","id":"exchange-107"},{"speaker":"たけうち委員","kind":"意見","question":"詳しくありがとうあります。本当にそういった面では、保育料のほうも国においての無償化がされて、ほぼ７割が負担なしということで大変よくなって、また品川区もこの間、こちらにも紹介していただいているとおり、本当に数年単位で拡充を図ってこられていることに大変敬意を表するところです。","respondent":"若生保育支援課長","answer":"これまでも様々な補助メニューを拡大してまいりましたけれども、今般の私立保育園等の補助金を拡充しているところもございまして、そことの負担のバランスというところも考慮しつつ、今後の私立幼稚園のほうの教育の振興に資するために。","id":"exchange-108"},{"speaker":"あべ委員","kind":"質問","question":"昨年の幼児教育の無償化以降、全国では保育料の値上げをした園がかなり目立つわけですけれども、品川区内では把握をされていますでしょうか。","respondent":"若生保育支援課長","answer":"ただ、今年度に入ってからは、やはりこういった社会情勢等の中で若干値上げが、教育の充実をしたいですとか、職員の処遇をもう少し上げていきたいというような各園のご事情も踏まえて、数園が値上げをしたというところはあります。","id":"exchange-109"},{"speaker":"あべ委員","kind":"意見","question":"無償化の影響もあって、保護者負担は以前に比べればかなり軽減されてきたかなと思います。さらなる軽減というのももちろん理解をするところですが、今おっしゃったみたいに職員の処遇改善ですとか、あるいは特別支援にかけるサービスの充実ですとか、そうした形でのお金の使い方というのもバランスを持って進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"安藤委員","kind":"質問","question":"私立幼稚園保護者教職員連合会の活動について、区はどのように把握しているのかを伺いたいと思います。保護者と教職員との連携・交流というのは、よりよい幼稚園環境を作る上でも大切なことだと思いますけれども、いかがでしょうか。","respondent":"若生保育支援課長","answer":"保護者教職員連合会の活動ですけれども、こちらにつきましては、令和元年度の実績報告が協会から上がってくるのを見ますと、母親研修ですとか、保護者教職員連合大会、これは講演会ですね、そういったところに補助金が使われていると聞いておりますので、そういった活動や。","id":"exchange-111"},{"speaker":"安藤委員","kind":"質問","question":"今やはり重要だという話もあったので、やはりかつて区立の保育園ではこういう活動というのは、保育の質を保つ上で大切な役割を果たしていたと伺っていますけれども、幼稚園では行われているようなことが、区立の保育園では大分弱くなっているというか、むしろそれをあまりさせないような方向になっているように私は感じていまして、昨今、私も２年前までは区立園に子どもが通っていたのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"横山委員","kind":"確認","question":"現在の私立幼稚園を取り巻く社会情勢、そういった現場の状況というあたりを、区としては具体的にどのように把握をしておりますでしょうか、確認させてください。","respondent":"若生保育支援課長","answer":"幼稚園担当の職員は、書類のやり取りの中から各園のお話、ご要望を聞く機会もありますので、そういったところで状況等の把握に努めているところです。","id":"exchange-113"},{"speaker":"横山委員","kind":"質問・要望","question":"そうした現場の疲弊ですとか大変さ、つらさ、さらにコロナ禍という中で、保護者の方の様々な思いですとか、また現場の先生方の思いがあるのではないかと考えていますけれども、現在も既にいろいろとお話を聞く機会なども捉えていただいたり、書類の面でやり取りしていただいたりしていると思っているのですが、現場の皆様がどのようなことにお困りであるのかということを丁寧に聞いて。","respondent":"若生保育支援課長","answer":"今後のそういった私立幼稚園とどのように関わっていってよい教育をしていただくかというところ、ニーズ等をどうくみ上げていくかというところは、ご意見を伺いながら検討してまいりたいと考えています。","id":"exchange-114"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。ただ、私は先日の決算特別委員会でもちょっと発言させていただいたのですけれども、途中で退園を促すなどの不適切な対応がないかというのを、私立だから区から口を出せないとかそういうことではなく、補助金を出していますので、区で調査、把握していただいて、指導などはしていってほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。公私の教育費格差の解消に向けて進めていっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。子育てに関する広範な費用の軽減を進めていただきたいと思います。この件も、そしてその他のことについても区として指導していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":81736,"voices":382}},{"id":"r02-20201130-5","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"総務委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"勤務条件に関する条例の一部を改正する条例、(8)第９５号議案、職員の給与に関する条例の一部を改正する条例、および(9)第９６号議案","agenda":"勤務条件に関する条例の一部を改正する条例、(8)第９５号議案、職員の給与に関する条例の一部を改正する条例、および(9)第９６号議案","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"併せて、第９３、９４号議案のほうですけれども、品川区特別職報酬等審議会ではどんな意見やどんな議論がされたのかお伺いしたいのと、先ほど、職員に準じたということですが、下げ幅だけを単純に見ると、職員がマイナス０.０５月で、特別職はマイナス０.０４月なのですけれども、現行の月数がもちろん違いますが、先ほどの説明の準じたというところで、この差は何なのかと単純に疑問に思いまして。","respondent":"黒田人事課長、立川総務課長","answer":"労使交渉の中での、交渉の論点というところですが、私どものほうで伺っているのは、再任用職員の引下げの月数が０.０５月というところで、一般職員と同じ月数になっているところが。別の意見といたしましては、やはり国の人事院、また、特別区の人事委員会等の意見を尊重して、おおむね連動するような形でこれまでどおり実施したほうがよろしいのではないか。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"第９３号議案、第９４号議案のほうでもう一度伺いたいのですけれども、品川区特別職報酬等審議会ではそういった意見があったということですけれども、やはり、区議会議員も含めて、区長や区議会議員は区民から選挙で選出されているというところにしっかり目を向けると、今の景気の悪化が、ご承知のとおりリーマンショック以上だと言われる中、しかも今回、調査期間がいつもとちょっと違う部分と。","respondent":"立川総務課長","answer":"特別職の報酬等につきましては、まず第１点が、特別区人事委員会等の勧告、職員の給与の状況というものはどういうものかということがまず第１点です。それを踏まえまして、品川区特別職報酬等審議会のほうに諮問をしてご意見をいただいた上で、区としてまず判断をすると。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"いずれにしても、今回下げるという内容ですから、それはそれで、特別区人事委員会勧告や品川区報酬等審議会の答申と逆の方向に行くべきだとは言いませんけれども、さらに厳しい判断というのが必要ではないかなと、意見だけ述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、今のご答弁の中で、品川区特別職報酬等審議会では、特別職は下げなくてもいいのではないかというご意見だけでしたけど、それはどういうふうな理由でそういうふうな意見が出たのか分かれば教えていただきたいのです。","respondent":"立川総務課長","answer":"先ほど、品川区特別職報酬等審議会の意見の主なものにつきましてお話をさせていただいたところですが、理由等につきましては、原則この審議会における議論の内容は非公開ですので、そこまでの答弁は控えします。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。品川区の公務員であり品川区の中の特別職であり議員なわけですから、品川区では企業のほとんどが中小企業、多くが中小企業という中では、もっと厳しい状況であるということを踏まえて、審議されてもよかったのではないかなというふうに思います。これも意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"お聞きしたいのは、特別区人事委員会の勧告に対して、区として意見、声明とかそういうものをきちんと申し伝えるところ、そういう手法というのはあるのでしょうか。再度お聞きします。この人事委員会勧告に対して、きちんと意見を伝えるという手法、その手段はあるのでしょうか。そして、今現在、人事課長もご存じのとおり、世相は大変厳しい状況になっていますが、それに対してどのようにお考えでしょうか。","respondent":"黒田人事課長","answer":"勧告内容につきましては、調査内容については国の人事院の調査の基準と同様の調査を、東京都と特別区と国と合わせて行っているという中では、このいわゆる公務員の給与制度をどうするんだという大きい議論の中で調査対象が決まっているですので、まずはその調査した期間が少し。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"これだったら必要ないというふうに言わざるを得ない。全く現在の社会、実社会、経済を見ていないということは非常に残念です。これから、特別区人事委員会が何かいろいろ改革していっていただいて、もっと国民に分かりやすい身近な勧告を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。第９５号と第９６号議案なのですけれども、特別区人事委員会の勧告を受けて特別給の支給月数の改定を行うということで、大体金額にして２万円ぐらいの減だと思うのですが、確かに今、このコロナ禍の中で、本当奮闘している職員に対して、私も頭が下がる思いです。もし所管のほうで何かお考えになっているようなことあれば、何か教えていただきたいと思います。","respondent":"黒田人事課長","answer":"ご指摘のとおり、その仕事の意欲に賃金というのが影響するというのは確かにそのとおりだと思うのですが、公務員ですので、やはり区民のために働くというところが一義的に非常に大切なところだと思いますので、先ほどのご指摘あった。","id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"第９３号議案について、先ほども意見述べさせていただきましたが、条例自体はボーナスを下げるという内容でありますので、反対をするものではありませんが、やはり厳しい社会情勢の中、さらなるカットというのが率直に必要だと意見を述べさせていただいて、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしても、今お二人がおっしゃったのと同じように、議論をする中では本当に反対しなければいけないのではないかというぐらい、ちょっとこの内容についてはある意味、こういう内容ではいけないのではないかというふうに考えました。しかし、下げるということについては反対するものではありませんので、賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"第９４号議案、教育長の給与等についてですが、第９３号議案と同じくやはり下げるという内容の条例でありますので、反対するものではありませんが、今の社会情勢を踏まえて、さらに厳しく下げるべきだという意見を述べまして、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"第９５号議案ですけれども、労使間の妥結を尊重して賛成したいと思いますが、交渉の中で論点となったこと、検討されるべきことは誠実に今後とも話合いを進めていただきたいと述べまして、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークといたしましても、下げ幅はもう少しあってもいいんじゃないかというふうに考えます。もちろん、現場の職員がすごく頑張っていらっしゃって、しかも今、人数が少ない中で頑張っているというのはよく理解しております。ただ、この下げるということについては賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"第９６号議案の会計年度任用職員の給与および費用弁償に関する条例の一部を改正する条例ですけれども、労使間の合意を尊重したいと思いますが、ここはやはり、もともとの月数が少ないということはしっかり踏まえていかないといけないと意見を述べさせていただきまして、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"もともと任用職員の給与等は確かに少ないので、私としてもちょっと悩むところはあるのですが、ただ、民間では、もう本当にゼロということで職を失っている方のことも考えますと、下げ幅については納得できないところはありますが、下げるということで賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"第９６号議案については、そもそも会計年度任用職員という立場がそう強いものではない中で、こういうことがあるというのは、本当にここはちょっと心が痛むのですけれども、でも公務員ということでやはりこれは下げるということについては、賛成したいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"１つ目は、代表監査委員が、これはあってはならないことであったと、遺憾に思うという見解を述べられていたのですが、２つ目の、本来使うべきではないお金を使ったということについての見解が、ちょっと見解としてよく分からなかったので、たしか、「限られた時間の中でそういうふうになったということを聞いております」ということはおっしゃったと思うのですが、それについての見解が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"称）品川区立環境学習交流施設新築工事請負契約、(2)第６９号議案、（仮称）品川区立環境学習交流施設新築機械設備工事請負契約、(3)第７０号議案","agenda":"称）品川区立環境学習交流施設新築工事請負契約、(2)第６９号議案、（仮称）品川区立環境学習交流施設新築機械設備工事請負契約、(3)第７０号議案","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ただ、この間、説明会が行われ、戸越公園内につくるということに対して、様々意見があるというふうに伺っております。質問ですけれども、まず地元理解は得られているのかということと、その反対意見の主な理由は何か、伺いたいと思います。","respondent":"提坂環境課長","answer":"施設を造ることによって音がうるさくなるというのはないかというご意見もございましたけれども、こちらについてはハード面で遮音性を考慮する、それからソフト面でも騒音を出さないようなプログラム等を検討するということで、対応させていただきたいと考えています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めてご答弁いただきたいと思います。説明会を何回もしていくと、そうしたものでなければ、施設ができれば引き続きその地域の方々の理解と協力なくしてその施設の運営は進まないと思いますので、改めて、地元の理解は得られているのか、引き続き理解を得られるよう丁寧な対応をしていく必要が、私はあるのではないかと思っているのですけれども、改めていかがでしょうか。","respondent":"提坂環境課長","answer":"今後、１２月に工事説明会を予定していますけれど、当然、工事の説明が主体となりますけれど、それ以外のご質問についても真摯に対応しますし、あと、個別のご質問等についても真摯に対応する所存です。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、疑問や意見に対しては丁寧に説明をしていただきたいと思いますし、１回限りで終わりとか、そういうような態度ではなく、継続対応しているというお話ですけれども、ぜひとも丁寧に説明のほうは尽くしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"藤棚のことはたしか何人もの方がおっしゃっていて、移植するということですが、それは、うまくいくといいと思うのですけれどもほかのご意見も少しでも反映させられるところがあれば反映させていくというふうに当時伺ったように思うのですけれども、何か周辺の方たちのご意見で反映させられたもの、例えば、ちょうど遊具がある所に整備するので、その遊具のことを心配される方もいらっしゃったと思うのですが。","respondent":"提坂環境課長","answer":"遊具の件ですけれども、現在の設置場所が建設場所となるため撤去ということで、それを補完するものを、施設の内外、両方に整備していくということで計画してございまして、例えば施設の中の１階にキッズスペースというものを設置するのですけれども、そちらの中で、保育園。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"環境学習交流施設ということですので、ここが品川区の今後の環境に対する姿勢を示す設備になっていくはずだというふうに私は思っているのですけれども、幾つか、再生可能エネルギーとか、いろいろなエネルギーも使いながら、ＺＥＢとかそういうものをこの建物自体が実現していくという施設になるというふうに思っているのですが、予算のこともありますし、どの辺まで進められたかということで。","respondent":"小林施設整備課長","answer":"それから地熱ですが、委員ご指摘のとおり、地下にあります、いわゆる密閉した空気、熱を用いまして、それをいわゆる冷房とか暖房とかに使っていくということを、これは計画の段階から進めているところですが、これにつきましても、設計の最中にボーリング調査等を行いまして。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"それらのことで、基本的には建物に使うエネルギーを賄えるものなのでしょうか。それとも、そこまではいかない、一部利用みたいな感じなのでしょうか。その辺分かったら教えてください。","respondent":"小林施設整備課長","answer":"それと、つくるほうにつきましては、施設で賄う電力のおおよそ２５％から３０％は賄えるだろうというところで、正味７５％から８０％程度の省エネになるかというふうに思っているところです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"説明会でのご意見でも、環境を壊しておいて環境学習もないだろうというようなご意見もあったかと思うのですが、ここに公園を潰して新たな建物を造って、これだけのことが実現できているということと、そこから区が発信して、どんどんそういう考え方を広げていくんだということをぜひアピールできるような展示内容とか、そういうことにもしていっていただきたいと思います。これは意見にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"各自治体でも品川区をはじめ、環境について啓蒙啓発活動をしている中で、どうしてこの環境学習交流施設の整備の必要性が出てきたのか、教えてください。今、全国でこういった環境学習施設を造っていますが、この事業については、国からこういうふうにやりなさいというような指導で来ているのか、そして予算も流れてきているから区でもこの事業を、施設を造ろうということになったのですか。","respondent":"提坂環境課長","answer":"もう１点は、３年前に品川区環境基本計画の策定にあたりまして、区でもアンケートを実施してございまして、アンケートの中で、環境というのは大変大切なものなのだけれども、そもそもまず何をしていいか分からないとか。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、この場所に人が来ないということになると、何とも言えないですけれど、教育委員会並びに様々な分野の所管と一緒になって、よりいいものをつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"すみません、もう一つ忘れていました。蓄電池の設備があったと思うのですが、どれくらいか、確かここはいざ災害となったときのため防災機能を備えるのではなかったでしたか。太陽光発電とか、それから蓄電池設備が災害時に使われる、いざ災害になって、ここに人が集まったときに、例えばここで蓄電されたものを提供できるのか、またそういう機能というのはどうなっているのか伺いたい。","respondent":"小林施設整備課長、提坂環境課長","answer":"私のほうから先に、蓄電池のハード面のお話についてご説明いたします。蓄電池の容量ですが、通常の学校等にやはり設置されております蓄電池の約１０倍から１２倍程度、比較的大きな充電池が入ってあります。これを補完するような位置づけの避難所となることが想定されていますけれど、詳細についてはこれから防災課等とも連携して、調整を進めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、分かりました。補完的なということなのですけれど、そういうエネルギーを発生させたり蓄えたりする機能があるわけですので、この地域の方たちに対してそういう防災機能を提供できるように、今後運営、これは運営になるのかもしれませんけれど、考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"この建物が建つ場所には公園管理事務所がありました。今、公園管理事務所は、豊町１丁目の品川区に寄附した土地に移っているのですが、ちょっと細かい質問になってしまうのですけれど、あそこの土地というのは、寄附した方が品川区に福祉施設を造ってほしいという思いで寄附された土地なんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"エコに関連しまして、今、生ごみとか紙おむつというのが、再利用しようという自治体も増えておりますので、この環境学習交流施設でそういったリサイクルが生まれて、品川のリサイクルの中心になるような施設になっていただければと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"第７１号議案、第二戸越幹線整備工事（下流部シールド）請負契約","agenda":"第７１号議案、第二戸越幹線整備工事（下流部シールド）請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"平成２９年度から始まったこの第二戸越幹線整備工事ですけれども、今回のこの下流部シールドで完成するということでよろしいのか、全体の計画を改めて伺いたいと思います。","respondent":"松本河川下水道課長","answer":"この第二戸越幹線工事の今回、下流部シールドということで工事契約をするのですが、残りの工事といたしましては、今回、取水工という工種において、Ｎｏ.３とＮｏ.４をやる予定です。取水工のＮｏ.１とあとＮｏ.２が残ってありますので、その工事発注を今後していく予定です。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"恐らくやり方としてはそんなに変わらないと思うのですが、そういう事故が起きたわけですから、恐らく規模が小さいにしろ、道路の下に空洞ができるということで今回、そういう危険性があるということが可能性として出てきたわけです。それとも、いや、もう絶対完璧にこれは安全だと。今、品川区の地下を相当、掘って工事をしていますけれど、どのようにお考えでしょうか。教えてください。","respondent":"松本河川下水道課長","answer":"調布市で陥没事故があったことということにつきましては、私たちも認識しています。今回のこの第二戸越幹線は、シールド工事といいまして、トンネルのように地中を掘りながら下水管を造っていくというような工事です。","id":"exchange-032"},{"speaker":"須貝委員","kind":"確認","question":"確認なのですけれど、過去にもう幾つも造っていますよね。相当な本数になると思うのですが、そういうところというのは、やはり念のためにその付近を調査するとか、そういうことというのは考えられていないのでしょうか。それと、恐らく手法が、工法が違うから、もう完全に安全だと、我々、考えていていいのでしょうか。教えてください。","respondent":"松本河川下水道課長","answer":"その後ということにつきましては、道路管理者のほうで適切に管理をしていくということになろうかと考えています。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、例えば区民に聞かれたときに、やはり不安はありますよというふうに、我々は回答しておいたほうがいいのですか。そんな高地ではないのですから、例えば戸越でもどこでも、そうすると、この事故を見たときに、非常にちょっと恐怖を抱いたものですから、それをどうやって払拭して、区民に、いや、絶対安全ですよと、できれば言い切りたいのですが、それはまずいですか。どうですか。","respondent":"松本河川下水道課長","answer":"ですが、今回のシールド工事につきましてしっかり管理をしていきたいと思ってありますし、過去に行われた水道工事の中で、今のところそういった事故が発生しているということは、品川区内の私たちが今までやってきた事業の中では。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、区民の財産と命を守るということがやはり基本ですから、何かありましたら、そこは早急に対応、また対策をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-05","title":"第７２号議案、第二戸越幹線整備工事（上流部シールド）請負契約の変更","agenda":"第７２号議案、第二戸越幹線整備工事（上流部シールド）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"変更の内容の（５）の現地精査に伴う家屋調査の件数増とあるのですけれども、この、いわゆる地下を掘るシールド工で地上の家屋の調査の増とは、ちょっとよく分からないので、ここだけ具体的に説明いただけますでしょうか。","respondent":"松本河川下水道課長","answer":"こちらは、今回上流部シールド工事を行うにあたって、トンネルから約４５度の範囲を家屋調査というものを実施しています。設計段階では６６０棟と見込んでいたのですが、現地の精査の結果、７１７棟あったということで、増額をさせていただいているところです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"なぜ変更が必要になったのかとか、それから防音ハウスの形状および設備の仕様というのも、どういう理由で仕様変更が必要になったのか。道路管理者の指示による舗装復旧面積の増工ですか、これは、もうちょっとこっちも舗装しなければいけないというような、現場での指示によって変わってきたということなのでしょうか。もうちょっと説明していただけるとありがたいのですが、いかがでしょうか。","respondent":"松本河川下水道課長","answer":"２番目の、防音ハウスの形状と設備の仕様の変更ですが、こちらは、防音ハウスを設置するにあたって、周辺住民の配慮だとか、現場での精査を踏まえ防音ハウスの出入口の配置や屋根の高さの形状を変更したものです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"２番なんかはやはり、工事をしてみたら前のそういうものが干渉してしまうということでずらさざるを得なかったということは分かるのですけれど、防音ハウスの形状とかは近隣への配慮ということもあると思うのですが、やはりやってみないと分からないということなのでしょうか。契約金額を決めるときだと、こういうことは、そうせざるを得ないものなのかどうなのかを改めて伺いたいのですがいかがでしょうか。","respondent":"松本河川下水道課長","answer":"防音ハウスの形状につきましては、近隣の状況を踏まえまして、やはり形状を変えないとご迷惑がかかるということが判明いたしましたので、変更しています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":26837,"voices":150}},{"id":"r02-20201130-10","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1163,"voices":8}},{"id":"r02-20201201-6","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"区民委員会","time":"午前１０時００分～午後 ０時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"「品川区スポーツ推進計画（素案）」およびパブリックコメントの実施","agenda":"「品川区スポーツ推進計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"パブリックコメントの実施についてという資料の「これまでの経緯」のところで、学識経験者、区内関係団体代表者等々、それぞれあるのですけれども、それぞれが何人で、全体が何人だったのかというのを教えていただきたいのと、学識経験者の方はどういう方なのかということをお聞かせください。","respondent":"中元スポーツ推進課長","answer":"策定委員会の委員の人数ですが、全体で１５名です。その中で、学識経験者の方が３名いらっしゃいます。筑波大学の体育系の名誉教授の方を委員長にさせていただき、もう１名の方が東海大学の体育学部の准教授の方にさせていただいてあります。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"この素案で、２０１９年にスポーツに関するアンケート調査やヒアリング等々をしたということが１７ページに書かれています。小・中学校、義務教育学校の子どもたちにも実施したということです。これは、区民委員会にも報告があったのでしょうか。それで、アンケートをどれくらい送って、どれくらい返ってきて、ヒアリング等々もどれくらいやっているか。ここら辺の状況を伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"こちらも、配布数が２,９７８件で、有効回答数が１,１７１件。有効回答率が３９.３％で、郵送のアンケートにしては大変高い回答率を頂けたところです。それと、先ほどの児童・生徒向け調査の回答率は、有効回答率９６.１％でございました。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"提案","question":"それで、共産党としては、スポーツが権利であるということを冒頭に入れるべきではないかということをずっと提案させていただいていたのです。ですので、こういったところで区の計画の中でも、スポーツは権利なのだということを明記していただいて、その下で、このような計画を作っていくという計画にしていただきたいなと思っているのですが、そこはいかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"もちろん、言葉として権利とは書いてございませんが、実際には素案の４ページをご覧いただきますと、「すべての人が元気に活躍し続け、安心して暮らす超長寿社会へ」や、「誰もがお互いに尊重し合い、活躍できる共生社会の実現」など、具体的な施策の方向性としては。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"障害者スポーツのところで、２４ページにアンケート等の声を聞き取られた状況も出ているのですけれども、私も障害者スポーツ推進計画を作るべきだということを求めてきたのです。そうした障害者の皆様のそれぞれの個性や、障害の種別等々で本当に一人ひとり違いますので、そういったところを酌み取った推進計画を改めてお願いしたいのですが、いかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"今回、委員会の中で分けましょうというご意見はなかったのです。総合的なものは、障害者のスポーツのことに関しましても、一緒にこの中で考えていきましょうという形で委員会の中では検討が進んでまいりました。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その声が反映されている。障害者が継続的に活動できる場の充実とあるのですけれども、そうした障害者スポーツセンターを城南地域でということで、東京都に求めているとおっしゃっていただいているので、そういったことも記載していただいて、品川区はこのように求めてくれているのだなということも分かる形にしていただくと、より一層いいかなと思ったのですが、そこら辺はいかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"それよりは、まず、区立小学校の体育館などで地域利用が進んですので、そういうところを会場にして、地域の中でやれる機会や実施できる機会をなるべく取り組んでいきましょうという方向性で、スポーツ推進委員などに取り組んでいただいていたり。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"「これまでの経緯」を拝見すると、第４回と第５回はコロナの関係もあって書面開催ということになっていると思います。そうすると、第３回の２月というのは、コロナが大きな問題になっていたかといったら、まだそこまでではなくて、５月、９月というところでいろいろ大きな問題になってきたと思うのです。書面で開催するとなると、どうしても議論がどこまでできたのかなというところがあると思います。","respondent":"中元スポーツ推進課長","answer":"その後、致し方なく、どうしても開催できない状況で、高齢の委員もいらっしゃったので、書面でこういう素案のベースなのでご意見をどうぞということで、２回ぐらい修正したものをもう一回送ってとやったのですが、最後、１０月２９日に何とか広い会議室で集まりましたところ。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"具体的な施策がコロナとの関係でどう反映されているかなというところでいくと、基本目標の４、７５ページで書いていただいているのかなと思います。計画の段階なので、そんなに具体的なところまではなかなか難しいとは思うのですけれども、どういった方向性というか、今のところのイメージがあれば教えていただければなと思います。","respondent":"中元スポーツ推進課長","answer":"都や国の役割分担もありますので、税金が二重投資にならないように、せっかく東京都で立ち上げてくださったのなら、そこに私どもも区外から参加いただける行事であればアップするなどして、なるべく無駄なことはしないように。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"まさに、どのレイヤーというか、国と都がどのようにやっていくのかというのは重要なところだと思います。少し話は変わりまして、次に地域スポーツクラブです。そうすると、部活動と地域スポーツクラブの関係性も、どちらがいいというのではなくて、整合性、あるいは方向性も考えていったほうがいいのかなと思うのですけれども、そういったものの検討は何かあったのか、お伺いできればと思います。","respondent":"中元スポーツ推進課長","answer":"その辺で国のモデル的なものを注視しながら、教育委員会といろいろ連絡を取り合いながら検討していく事項だなということは、課長としては考えてあります。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"今回、スポーツ推進計画ですから、この中にスポーツという言葉がたくさん出てくるのは当たり前というか、出てきます。そもそも品川区、行政が考えているスポーツの定義。体をご本人が動かすのがスポーツなのか。それとも、行政が考えているのは、施設に行き、指導者の方がいらっしゃって、団体や組織の中に入ることで体を動かす。行政が考えているスポーツというのは、どのようなことでしょうか。","respondent":"中元スポーツ推進課長","answer":"(2)で、「本計画におけるスポーツの定義と障害者スポーツの考え方」とあります。これは、実はスポーツ実施率何％という指標は、まず、国や都の考え方とそろえませんと、正しい比較ができませんので、はっきり申し上げると、国や都の考え方に倣って規定させていただきました。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"ぜひしていただきたいと思うのです。私個人的なことなのですけれども、本当にお散歩が好きなのです。私は歩くの大好きで、品川区内でしたら、ほとんど歩いて行くもので、そういう施設に行ったり、団体に入ったり、指導を受けなくても、今日は天気がいいですけれども、お日様に当たればビタミンＤができるというお話も聞きますし、歩くことによって骨粗鬆症の予防ということも伺っているのです。確認です。","respondent":"中元スポーツ推進課長","answer":"委員ご指摘のとおり、意図的に体を動かした方も入るということで、アンケートのお問い合わせのところに書いてあります。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"それで、最終目標が令和１２年度７０％以上となっているのですけれども、これはすばらしいと思います。それで、７０％以上を目標にするということは、１０年後のことですけれども、せっかくこの推進計画ができていくわけですから、今から具体的にどういう形かということを考えていかないといけないと思うのが１点です。その辺について、大きく２点伺ったと思うのですけれども、いかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"施策の中で、世代別にいろいろ施策をご紹介をさせていただいているところがございまして、素案の５７ページに「高齢者のスポーツの推進」ということで、スポーツ推進課だけではなくて、今回、庁内の施策調査をしましたところ、６５歳以上の高齢者の方に向けての介護予防的な視点。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうしてほしいという要望をこの委員会で要望しようと思ったのですけれども、さすがです。やられているのですね。ぜひやっていただきたいと考えていますし、人それぞれ意図的に個々の価値観において体を動かせるということは物すごく大事だと思います。間違いなく来るわけですから、その辺においてもうまく庁舎内で、もちろんお子様たちも、成人の皆様も大事ですけれども、高齢者。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問・要望","question":"大枠の部分でお伺いしたいのが、週１回のスポーツ実施率の部分なのですけれども、例えば自分の例に当てはめてみますと、いわゆる子育て世代。４０代。だとすると、なおさら我々のような４０代が２０年後、いわゆるリタイアしたときに高齢者スポーツ、スポーツに少しでも興味が湧くかどうかという部分。これは、あたかもスポーツをやろうと思っているけれども、実施しない理由ではないですか。","respondent":"中元スポーツ推進課長","answer":"今後も引き続き、様々検討してまいりたいと思います。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"そこの部分にかけて、もう一つ伺おうと思っていた部分なのですけれども、見るスポーツの部分です。様々なスポーツへの興味を掘り起こすための施策として、スポーツの施策を考える側の立場からしたら、スポーツに触れてみる。でも、それを実際に自分でやろうとは思わないのです。スポーツを見るのは大好きなのです。ウエートを割くつもりなのかを伺いたいのです。","respondent":"中元スポーツ推進課長","answer":"見るスポーツというのは、区の場合、まだまだこれからというところがあります。現在、どうしても記載のところは少ないかなです。まさに今後の課題として捉えているところです。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのは、このスポーツ推進計画に基づいて、今後、目標値としては成人のスポーツ実施率を上げていき、健康につなげていこう。この計画を立てて、様々工夫しながら取り組んでいかれると思うのですが、こうした中での施設のキャパシティも考えて、今後どうしていくかという検討が何かされているかどうかというのをお聞かせいただきたい。","respondent":"中元スポーツ推進課長","answer":"施設につきましては、やはり都心の品川区ですので、そう簡単に作りますという話にはならないところがあります。やはり既存の学校の施設や公園運動施設の公平な利用を引き続きスポーツ推進課で努めていきたいです。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"近くがいいのは当然そうなのですけれども、近くでなければ空いていますというのは大事かなと思っています。そういうところの把握や他区、他課との連携も、先ほどの中でも学校や地域というお話があったと思うのですけれども、そういった連携もしっかり実施していかれるということでいいでしょうか。","respondent":"中元スポーツ推進課長","answer":"現在、他区の利用というのは、条例や規則があってなかなか難しいのですが、品川区内の運動、体育の施設につきましては、施設予約システムで一本化しているところがあります。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"スポーツコンシェルジュということで、すばらしい。もう一個、今伺っていていいなと思ったのは、同じ競技があれば一緒にやってもらえば、また交流が生まれて、いろいろな形が出てくるというところではすばらしいなと思いましたので、引き続き頑張っていただきたい。１点。","respondent":"中元スポーツ推進課長","answer":"ただ、なかなか難しいのは、皆様昼間にお仕事をされている方、現役の方も多いので、部活といいますと平日の午後になってまいりますので、その辺のマッチングが課題かなと。今後、報酬面などで国や文部科学省で一定の方向性が出てくるのを期待しています。","id":"exchange-017"},{"speaker":"大倉委員","kind":"意見","question":"部活動でいえば、まさに平日の昼から夕方にかけてというところで、だからこそ団体などにうまく働きかけをしながら、団体なので、仕事を退職されて過ごされている方たちも一定数いるのかな。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"提案","question":"今年の第１回定例会で、質問でラジオ体操の提案をさせていただいて、ご答弁の中では、庁内でのデジタルサイネージなどを活用して、朝にやっていきますということを頂いています。それを教えてください。","respondent":"中元スポーツ推進課長","answer":"ラジオ体操は、職員のほうでは実施しておりませんが、実はスポーツ推進課は５時１５分になりますと割とお客様が落ち着きますので、私どもの部は３課ありまして、そこで音も出させてもらって。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"提案","question":"品川区だからしながわ体操の選択というのは、それはそれで別にいいわけですけれども、先ほど来、各委員からあったとおり、運動しない人や無関心層に、これまで健康課も含めて、筑波の先生など、しながわ健康ポイントも提案して、実施していただいて、もう４年目ですか。聞き方によって、７割、８割がやっていないとなるのかもしれないけれども、実際はやっているという、加点方式というのですか。","respondent":"中元スポーツ推進課長","answer":"庁内なのですが、実は、私が先ほど説明で漏らしてございましたが、この計画を作るに当たって、庁内検討会というものを立ち上げてあります。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"言われても、どうすることもできないではないかという質問だったと思うのです。現状、なかなか難しいという課題をあえてお伝えしたのです。何でもそうだと思うのですけれども、そう思います。ぜひその辺を今後もしっかり力を入れていただきたいなというのと、先ほど障害スポーツの件がありました。もしも既に何かお考えがあるのであれば教えてください。","respondent":"中元スポーツ推進課長","answer":"予算も取れていたのですが、本当に残念ながらできなくなっています。それは、今回、再計上ということです。来年度に向けて、落ち着いたら、いろいろ防止策をしながら何とかやれればなということで、ボッチャについては引き続き普及啓発に努めてまいりたいと考えているところです。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今ちょうど最後に出たので、３３ページにある４つの団体という理解でいいかなと思うのです。ぜひ来年度に新たな取組ができるといいわけですけれども、そういったことを使って、やはり出入り自由な雰囲気というのでしょうか。スポーツは本来そうした形で、おみこしでも、私も詳しく知らないけれども、詳しい人はいるけれども、誰でもが出入り自由など、いろいろルールがあるわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"私から、まず、商店街の影響に関連してお聞きしたいことがあります。７月の中旬だったと思うのですけれども、東大井にあります商店街でクラスターが発生しました。ちょうどクラスターが発生したのが、たしか７月の連休明けだったかと思うのです。その前に、口コミで、どうもクラスターが発生したらしい。そのキャンペーンを行った後の反響について、少し教えていただけますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、それが非常に有効に作用したところがありまして、それ以降は、大井町がクラスターだという話で区のほうに問い合わせが来るようなこともございませんし、商店街の方と別の機会に話をするときがあったのですけれども。","id":"exchange-023"},{"speaker":"小芝委員","kind":"質問","question":"そのお話を聞きまして、本当に安心しました。報道の在り方は、当然、報道の自由がありますから、それはそうなのでしょうけれども、真実があっての報道でありますので、区からもそこら辺の予防策というわけではないですが、何か事前の取組をしておかなければならなくなってくるのではないか。今後、どうなるか分かりませんけれども、その辺のご意見をお聞かせいただいてもよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"１つは、そういうものを繰り返し言っていく部分と、あとは、変なものというか、間違った情報が流れないように、あるいは過大に表現されることがないように見ながら、あるいは出てきた場合には。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"初めに、先ほど、ご報告でありました「商店街の混雑について」ということで、区民の声、区政に関するご意見３６件という話、あと、電話の対応が２２件ということです。これは、果たして区民の声がどのくらいあるのかなというところで、区外のものの割合はどのくらいなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"数字としては持っていないのですが、思っている以上、半分ぐらいは区外の方と考えております。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問","question":"やはりそこなのです。そのときに、１つ考えるのは、対抗言論ではないですけれども、どのように正しいことを伝えていくのかというところなのだと思います。それで、先ほどの東大井の件というのは、１つ参考になるかなと思うのです。記者会見をやられたということなのですが、これは、どういうところでどのように記者会見をやられたのか。ご存じの範囲でお伺いできればと思います。","respondent":"遠藤商業・ものづくり課長","answer":"記者会見は、その地域にある３つの商店街が、とにかく大井地域でかなり傷んでいるということで、それを払拭するような何らかのイベントをしなければいけないというところで、何をやろうかといろいろ考えられて、先ほど言ったＴシャツを作られたり。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"この記者というか、新聞社など、いろいろな報道機関に対して、やりますよという告知をしないといけないと思うのですけれども、プレスリリース自体は、商店街が同時にやられたのか、そこの部分は行政のほうが報道機関に対しての窓口を持っていらっしゃると思うのですけれども、品川区としてもプレスリリースのところにある程度ご協力されたのか。その辺りはどうなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"多分、商店街だけでは限りがあるかと思いますので、うちの広報部門が、それぞれの新聞社などですと、品川区担当みたいな形で個別に電話などもしていただいて、ぜひ来てくださいという形でやらせていただいたです。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問・要望","question":"多分、今後もそのようなことが起こり得る。なので、これからまた緊急事態宣言があるかどうかは分からないですけれども、もしこのような報道被害が起こり始めたというタイミングがあれば、ぜひとも商店街と、こちら側からも対抗する手段があるよということは共有していただきたいかなと思うのです。その辺りはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今までにないような状況の中で、正直、こちらからすると困ってしまうような報道がある中で、どう対応すればというのは、今回もいろいろなケースがございましたので、次回、そのまま使えるかどうかということはありますけれども、こちらから発信するという意味では。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"ぜひそちらもお願いしたいなと思います。今のは、まさに報道被害が起こった場合の対応だったかと思うのですけれども、一方で、もう一つ、品川区がプラスの面で報道されていたのが、例えば不動前で、商店街が宅配の支援をしているという話があったかと思います。この宅配の支援のところは、ほかの商店街も広く含めてどうなっているのか。この辺りの評価をお伺いできればと思います。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"不動前で宅配のサービスをやられていると聞いているところです。ただ、あちらの課題として、ボランティアに近い形でやられていたということで、それ以上はどうしても費用がかかってしまうということで、今はそれほどやっていらっしゃらないかなと認識しています。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に要望になりますけれども、やはり広げていくのはボランティア的になってなかなか難しいというのは、そうなのだろうなと思います。せっかく業態変更の協力金など、いろいろなところで移動販売などにも使えるという情報もありますので、ぜひその辺りは商店街の皆様とも共有していただきながら、引き続きご支援いただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたキャンペーンなどをやらざるを得ない状況になった。ですので、そういったことも国に求めていただけたらなと思うのです。自粛するなら補償もセットでということを私たちはずっと求めてきていたのですけれども、やはり感染してしまったときの補償というのを、ぜひ求めていただきたいし、やっていただきたいなと思うのですけれども、そこはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"仮にお店で感染したとしても、当然、感染した人は隔離という形になりますので出られないかと思いますけれども、マスクなどをしていれば濃厚接触者には該当しない形になろうかと考えています。そういうことであれば、引き続き営業は続けられるのかなと思っているところです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"だけど、もう第３波が来ていて、いつ感染してもおかしくないという状況の下で、感染対策は徹底しながら頑張られているのです。私たち、Ｇｏ Ｔｏ事業に関しては一旦止めて、コロナが収束してから、どんどんこうした事業を充実させていくべきだと言っているのですけれども、「Ｇｏ Ｔｏ商店街」は、現在申請はない状況だということです。その状況というのは把握されているでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"一応、聞いている限りですと、大体十五、六件で、３０弱の商店街が申し込むのではないかという形で、今認識しています。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今も時短が言われていますけれども、それがさらに強化されるということになってしまうので、やはり感染拡大を食い止めていくというところでは、こうした感染が広がってしまう可能性の大きい密集した商店街、飲み屋といったところは無症状でも検査をして、箇所を決めて、そこを始点に検査をして、出てしまったところには補償するというふうに、感染を防ぎ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"順次伺っていきたいのですけれども、まず、今ちょうど石田ちひろ委員からお話があったので、そこに引っかけてお話を伺います。「Ｇｏ Ｔｏ商店街」の部分なのですけれども、本日１１月３０日時点のデータを経済産業省のホームページから拝見しました。こちらに関して、今おっしゃったのが、最終的に３０件ぐらい申請があるような見込みだと伺っていらっしゃるのでしょうか。そちらの２点をお伺いしたいです。","respondent":"遠藤商業・ものづくり課長","answer":"その話の中で、約３０の商店街がやるという話も聞いているのですが、それも結局、担当者の方が言っているのか、商店街として正式な意思疎通ができた中で言っているのかが分からない状況です。その辺で、今のところ最大でそのぐらいではないかと考えているところです。","id":"exchange-034"},{"speaker":"くにば委員","kind":"質問","question":"先ほどの答弁でありました、最終的にこれは国の事業ということで、品川区として最終的な部分までは把握していらっしゃらないということだったのです。この「Ｇｏ Ｔｏ商店街」は、最終的に今おっしゃった３０件がやるのではないかとおっしゃっている中で、耳に届いている範囲で、具体的にどういった事業をやるという情報が届いているのか伺いたいのです。","respondent":"遠藤商業・ものづくり課長","answer":"どこまで正確か分からないのですけれども、例えばバーチャルで商店街のまつりをやられるとか、イルミネーションをやるとか、そのようなことをちょこちょこ聞いているのですけれども、アイデアの段階なのか、先ほども申しましたとおり、口頭で聞いている範囲なので。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問・要望","question":"それで、「Ｇｏ Ｔｏ商店街」の事業は、もちろん動向を見極めないと、なかなかアクセルを踏むのは難しいとは思うのですけれども、国の事業として活用できる部分は、ぜひとも品川区の商店や中小企業にも活用していただきたいなと思うので、そこに関して、国が行っている以上、推進できる部分は推進していっていただきたい、進めていただきたいなという要望が１点。これが、どのような事業に充てられたのか。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな形で、本当に商店街によってばらばらです。多くは感染症予防のためのアルコールやマスクを商店街で買われて、それを配るとか、あとは啓発的なもので使われたというところが多かったようなイメージがあります。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"そちらに関しては、最終的に全ての収支報告を受けるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらにつきましては、支援金という形をとっておりますので、一律に最初に給付しまして、そのときにこういうものに使いますというのを出していただくような形になっておりますので、終わった後に、このうち幾ら使ったという報告は求めないものになっております。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"アルコールやマスクといった、いわゆる消費してしまうものから、昨日も話がありました空気清浄機と、これから必要になってくるであろう物品に関して、この支援金は、全て使っていない商店街に関しては、これから使うことが可能なものなのでしょうか。まだ、これを使っていないから、これから充てようという形で、まだ使っていない部分に関してこれから使うことができるような支援金なのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの支援金につきましても、いわゆる商店街への支援という扱いになっておりますので、空気清浄機というものは事務所に設置する可能性はあるかと思いますけれども、そういう部分では余り可能性がないのかなと考えているところです。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問","question":"すみません。私の伝え方が曖昧だったみたいなのですけれども、空気清浄機はあくまで一例なのですけれども、まだ使っていない部分の支援金に関しては、今年度内に使い切らなければいけないとか、これは来年まで長引くであろうから、アルコールなどの消費されるものに関しては、翌年に持ち越せる形で取得しておけるような類いの支援金なのかを伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"それをどのようにいつ使うかということについては制限を設けておりませんので、そのタイミングでお使いいただければと考えているところです。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問","question":"その際に、第２弾、第３弾の商店街への支援金というのは、必ず必要になってくると思っているのです。現状、いつぐらいまでの対策を想定しているのか。そういったフェーズにおいて、こういった場合にはこういった策をしようと、現状考えている部分がいつぐらいまでで、大枠としてどれぐらいのボリュームなのかというのをお伺いしたいです。","respondent":"遠藤商業・ものづくり課長","answer":"支援の中身をどのぐらいまで考えているかというところなのですけれども、当然、いろいろなメニューを想定しています。一方で、支援の中身としては、うちといたしましては、いわゆる守りの部分と、産業振興部門がありますので、攻めの部分をどうしても意識しています。","id":"exchange-040"},{"speaker":"くにば委員","kind":"意見","question":"今、ワクチンの普及が１つのめどかなということを考えていらっしゃるとは思うのです。例えば直近の報道で、もしワクチンができたとしても、日本人がそれを接種しようと思うかどうかということに関して、たしか６８％でしたか。そういったアンケートが出ていたのです。区として、第３波を乗り越えた後、また第４波が来るかどうかみたいな情報や算段、予想はどこまでされていますか。","respondent":"遠藤商業・ものづくり課長","answer":"正直、新しい病気といいますか、今までの感染症ではないということで、第３波が来ましたので、当然、第４波もあるという想定はしておかなければいけないなですけれども、それがいつまであるかというのはなかなか判断できないところです。次に備えるというところで考えております。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう一つ、具体的な話に移りますけれども、コロナ対策の特別助成金。昨日、お話があった中の１つです。少なくとも２年、３年後には、誰もマスクをつけていない、誰も消毒をしない。そこまでになるかと言われると、なかなか警戒心が強い。例えばアクリル板１つについて細かく言及すると、そういったものの導入に関して、実効性が実際にあるかどうかというのは、区で何かデータなどは把握なさっているのですか。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる飛沫を浴びなければというところがありますので、そういう面では類推というのも変ですけれども、アクリル板で隣と遮断することで十分効果があるということで、区内に限らず、広くアクリル板が用いられているのかなと考えております。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問","question":"それがきちんと対策されている店に対しては入る動機になるという部分で、それは先ほど伺った実効性の部分なのですけれども、何かしらエビデンスがあれば、さらにお店を後押しする要因にもなると思うのです。もっと区から、例えばアクリル板の導入などを飲食店に積極的に促すというのは、広報の観点も含めて、施策を推し進めていくという部分の考えは何かあるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"マスクをしていない店員のお店もあろうかと思います。そういうところに対して、さらに区がアプローチする。そこまでやるべきなのかなというか、そこに力を強めるのだったら、ほかのところにかけたほうがというのが、今のところの現状です。そのように考えているところです。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問・要望","question":"結局、今おっしゃった部分は、商店街単位で、うちの商店街は全てのお店で知恵を出して、対策をきちんとやっているよという部分に対して助成があるわけではないですか。今、政策として行政が絡むのは難しいということだったのですけれども、そこは要望という形で、ぜひアクリル板の導入は、入店するモチベーションになると私は思うので、そこに関しては広報をお願いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分で、私どもで何か支援したり、予算を組むのであれば、実証実験などのお手伝いができるのかなと考えているところです。","id":"exchange-044"},{"speaker":"くにば委員","kind":"提案","question":"そこに関しても、何か区で集めた情報を五反田バレーにフィードバックして、五反田バレーの方々に、区からの提案でこういったことをもっとやってみましょうという提案は、様々なさっているのでしょうか。そこの部分をもっと推し進めていただきたいなという気持ちがありましてお伺いしているのです。","respondent":"遠藤商業・ものづくり課長","answer":"直接的には、五反田バレーでやっている事業がそのまま商店街にぽこっと結びつくというのはなかなか難しいところもあって、間に入る方というか、こういう形ならビジネスに結びつくのではないかというところが一番難しいと考えているところです。","id":"exchange-045"},{"speaker":"くにば委員","kind":"質問・要望","question":"先ほどおっしゃっていた２１の事業者の方が今回参加なさったという部分に関して、昨日の販路拡大支援助成の中で一番多かったのが、このＥＣサイトの構築の部分に大きく興味が持たれて、これを活用した方が多かった。伴走次第だと思うのです。そこに関して、ＥＣサイト作成セミナー、五反田バレーとの連携の部分で、作成した後の伴走や、アドバイス、カウンセリングをどの程度まで進めていく予定なのですか。","respondent":"遠藤商業・ものづくり課長","answer":"それを、前回やったものと、もう一回、実際に作業をやっていただいて、その次につきましても、個別相談などを受けるという話を聞いておりますので、それぞれの事業者がいろいろと困っている部分につきまして。","id":"exchange-046"},{"speaker":"くにば委員","kind":"質問・要望","question":"特にホームページ、今回のＥＣサイト等に関してなのですけれども、昔からそうなのですが、いろいろな企業がいざホームページを作りました。ホームページはこれからの時代必要だよと言われて、取りあえず作ったはいいけれども、その後が続かないというところが余りにも多い。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えばここまでの準備の経費は、チラシを作って、作ってしまったらお金がかかっているというところで言うと、その辺の資料があったのか分からないのですが、あれば、その辺の費用は、かかってしまって中止になって配れないとか、配ったけれどもできなくて結局中止になってしまって、その部分が費用負担として商店街に乗るということがあった場合、その費用は商店街が払わなければいけないのですか。","respondent":"遠藤商業・ものづくり課長","answer":"廃業の理由が事業承継といいますか、後継者がいないという部分なのか、あるいは別の理由なのか、いろいろとあろうかと思いますので、そういう部分での相談などを受け付けております。そういう部分での支援という形で考えているところです。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問","question":"そういうものを新たにというか、例年やっていて、多分、年４回という基準があったりして行っている部分でも、一応、今の状況だと、例えば４月のものはやらないよと分かるとは思うのです。そこと区との連携とか、商店街内の連携とか、五反田バレーとの連携というのもされているのかなと思うのですけれども、その辺の状況も合わせて教えていただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"五反田バレーのイベントで商店街が絡むものにつきましては、必ず商店街連合会と話をして、どういう形がいいか、こういうものをやってみたいなど、いろいろな話を頂戴しています。今後も商店街連合会のご意向などを聞きながら進めていければなと思っているところです。","id":"exchange-049"},{"speaker":"大倉委員","kind":"意見","question":"特に品川区にある企業のタクシー会社を見たらそうだったので、そのようなところも情報をとりつつ、連携できるといいのかなと思ったので、これは意見だけ伝えて、これからまたどうなるか分からない中で、商店街は非常に大変な部分があると思うので、ぜひ応援してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"つる副委員長","kind":"質問・要望","question":"長くなって、多分この話で最後だと思うのですけれども、今日、「商店街等」ということで銘打っていただいている所管事務調査なので、この「等」のところについて、いわゆる個店、商店街に属されていない小売店に対する支援策が、今、区がやるべきこととして、また、できることとして具体的にどういったことがあるのかということと、実際のいろいろな声を幾つか参考程度に教えていただきたい。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる一般の商店は普通の事業者という形になりますので、商店街はにぎわいを創出するところで、私どもは商店街支援という形にしています。個別の店舗につきましては、変な話ですが、飲食店だけではなく、製造業も含めて、いろいろなところが傷んでいるところがあります。","id":"exchange-051"},{"speaker":"つる副委員長","kind":"質問","question":"分かりました。四半期に１回出していただいている品川区の景況を見ると、逆に言うと、飲食というのはサービス業に入るのですか。製造など、いろいろと分かれていて、飲食というのは、その中でいうと、どのなりわいとして入ってカウントされているのですか。","respondent":"遠藤商業・ものづくり課長","answer":"物に付加価値をかけるという形になりますので、サービス業だったと認識しております。","id":"exchange-052"},{"speaker":"つる副委員長","kind":"質問","question":"分かりました。最初のご答弁のときに、商店街のにぎわいに対する支援のところで、その先の売上については、各商店街が形成しているところ、各個店についても、それぞれお店の営業努力という形になるのだと思います。そういった部分は非常にセンシティブだと思うのです。そうしたところに対しての支援というのは、今後、長期化という視点も含めて、どのように考えているのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"本当の個店について何か支援するということになりますと、金銭的な部分についてなかなか難しいところがあります。","id":"exchange-053"},{"speaker":"つる副委員長","kind":"質問","question":"最後に、５月ぐらいでしたか。品川区でテイクアウトメニューマップを試験的に区の職員がそれを活用して買うとか、持ってきてもらうのをやっていたのです。この辺の在りよう、また、区で「しながわ ＴＡＫＥ ＯＵＴ ＭＡＰ」でしたか。その活用など、その辺も含めて、商店街支援にもつながる消費者への支援についてあれば教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"消費者にとっては、３０％のプレミアムを乗っけて、それを軸に今年はやらせていただいたところです。ご指摘いただいた部分については、いろいろと広報等もあろうかと思いますので、今後も研究させていただければと考えています。","id":"exchange-054"},{"speaker":"つる副委員長","kind":"質問","question":"いろいろ答弁が抜けていたところが幾つかあると思うのだけれども、それは時間がないので、今あった商品券なのです。これは、国でキャッシュレスや、それこそマイナポイントなど、いろいろなキャッシュレス決済に対するポイントをつけている。もしかしたら先ほど答弁があったのかもしれないのですけれども、区共通のキャッシュレス決済の在りようというのは、何かできるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"課題としては認識していますので、引き続き研究させていただければです。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":51799,"voices":126}},{"id":"r02-20201201-7","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"厚生委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"電話相談センターが東京都に移って、保健所のほうはかなり少なくなったということですが、そうすると、保健所の今の体制というのは、どのような状況になっているのか、変わったのか、相談センターのほうの体制は多分、少なくて済むのかなと思うのですが、逆に、感染が２桁ぐらいずつ増えている状況だと、それに対してのフォローの体制というのがまた、トレーサーというか。","respondent":"鷹箸保健予防課長","answer":"現在、日々２桁台の報告がある中での保健予防課の体制ですけれども、発生届がありまして、その方の病状を聞き取り、昨日もお話ししたところですが、翌日の１０時までに、症状がある方は入院、あるいは施設療養というふうに振り分けて、そこはスムーズにいっているのですが。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１週間に一遍、感染状況というのをホームページに載せていただいているのですが、第３波でこれだけ増えているということになると、連日というのは少し大変かもしれませんが、もう少し早めに載せていただくというのはお願いできないものかなという思いをしているのですが、区によってはそういう感染者の状況というのが連日出ているところもあったりするのですが、品川区の全体というのが分かって。","respondent":"鷹箸保健予防課長","answer":"感染のレポートですけれども、当初、毎週火曜日にアップをしていたのですが、月曜日に祝日が多く、そうすると、火曜日１日で全てをやるというのが、かなり疑義のある症例、特に感染経路が不明とか、その後で分かったとか、いろいろなところを確認しながら。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"働く保健師さんたちも、課長さんももちろん、本当に大変な中、長い間にわたって緊張状態が続いていると思うのですが、そういう中でストレスが、やはり医療機関の人たちも本当にそうですし、保健所の皆さんもそのような状況になっていると思うのですが、それに対しての対応というのは、残業時間が同じように続いているというところが、何とか解消できるような対策というのは。","respondent":"鷹箸保健予防課長","answer":"私が保健予防課長の立場でどう答えるか……。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"品川区だけではなくて、東京都のほうの数を入れていただいたので、分かりやすくなったと思います。職場によってリスクが高いということを言ってしまっていいのかどうか分からないのですが、そういうことなのか、少しそのあたりの、今のところのご見解みたいなものについて、教えていただける範囲で教えていただければ。それは当然議会も例外ではないのですけれども、教えていただければと思います。","respondent":"鷹箸保健予防課長","answer":"ただ一部、保育園で第１波のときに、やはりこちらからの感染予防のお伝えがまだしっかりなされていなかったときに、保育士さんというのはお休みできる休憩室がとても狭くて、同じ時間帯にお昼を召し上がっていて。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"我々もなるべく接触は避けているのですが、どうしても面と向かってご相談を受けなくてはいけなかったり、お話を伺わなければいけない、やはり立場上あるものですから、そういう意味では本当に区の職員の方、特に保健所の方もそうですし、現業というのですか、そういう方たちも含めて、やはりどうしてもエッセンシャルワーカーのお一人だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"を再度、聴取いたします。 それでは、(1)第八期品川区介護保険事業計画概要（案）","agenda":"を再度、聴取いたします。 それでは、(1)第八期品川区介護保険事業計画概要（案）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ですから、定着のためには、賃金を上げていくというのも意識的にやらなければいけないのではないかと私は思っているのですけれども、そういうことを、こういう計画の中の１つの施策として、位置づけなければならないのではないかと思うのですが、その点はどうお考えになっているのか、１つお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ただ、賃金アップというのがなかなか難しいといたしましても、それ以外のところで、介護に関わるサービスの従事者に関わる様々な支援策というのは、講じてまいりたいと考えているところです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"いろいろ難しい問題があるのはそうなのですが、少なくとも問題点としてあるということは、指摘しておかなければならないし、外国人を導入というか、入れていくというところにすぐ逃げるのではなくて、少なくともこのプロジェクトの１つの課題、問題点として指摘しておくぐらいのことは、やっておいていいのではないかと私は思うのですけれども、いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"今回、こちらの計画の中にも、例えば外国人雇用を検討するという文言を入れさせていただきました。ただ、１つ申し上げておきたいのは、介護人材というのを、我々は決して安価な労働力として確保するつもりはないということです。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"もう一つ別の問題で、１６ページの表について質問したいと思います。１つは、３つの表が出ていますけれども、その真ん中の表で認知症高齢者グループホーム、第七期の中で、今年までの、これは需要ですか、推移がそれほど……。これはなぜなのか、グループホームを増やしていく考えはないのかというのが、第１点です。これは素朴になぜなのかというのをお伺いしたいと思います。お伺いします。","respondent":"宮尾高齢者福祉課長","answer":"２点目の、介護老人保健施設の令和２年度、２０２０年度の見込みが、他の年度と比べて若干低くなっているというご指摘ですが、すみません、これは手元に詳しい資料がないので、何ともというところではあるのですが、ただ、これはあくまでも一時的な現象ですので。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"次の１７ページ、介護保険料について、月額６,４００円程度が基準月額で、それに対して基金を充当して、６,１００円から６,３００円程度にするのを見込んでいるということですが、これをどのぐらい取り崩していくとお考えになっているのか。そして、取り崩した残額がどのぐらいになると見込まれているのかというのを、お伺いしておきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"そうしますと、３年間で３億円という数字が目安としています。それらを踏まえますと、例えば６,３００円に設定した場合は、今、見込みが６,４００円ですので、今、言ったばかりであれなのですが、３億５,０００万円の基金投入、充当が必要かと予想しております。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１３ページのプロジェクト７「多様な福祉人材の確保・育成と業務の効率化」というところで、品川区には本当にほかの自治体にはない、得難い品川介護福祉専門学校があるというところで、たしか前、ほかの会派からも出ていたと思うのですけれども、定員割れが続いているという中で、魅力ある、何というのですか、新しい人材をそこに呼び込むためには、その会派は。","respondent":"宮尾高齢者福祉課長","answer":"こちらにつきましては引き続きやっていくとともに、区としてもしっかりと支援をしてまいりたいと考えています。品川介護福祉専門学校のメリットといたしまして、私が思うのは、就学資金の貸付け制度がやはり大きいと思います。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"意見","question":"もうおっしゃるとおりですし、今、ホームページを見てみたら、卒業生から毎年、当然、９０％以上の方が３年のものを活用されて、区内のそういうところに人材の供給をされている。すみません、無責任なことを言って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"それは、先ほど説明があった、いわゆる準備基金から出ているため低いのか、平均ですから、多分２３区でも高いところはあったり、例えば２３区、様々な仕組みの中でこれを運営しているのかなと読み取れるのだけれども、何で品川区はこんなに安くできているのかというのを改めて説明いただきたいのと、それが今後、恒常的に続けられるのか。","respondent":"宮尾高齢者福祉課長","answer":"介護保険料は、先ほど１７ページのところで少し触れさせていただきましたが、サービス量を見込み、それから給付費を見込み、それに対して第１号被保険者の方がどのくらいで推移していくかというところをトータルで考えますと、全く素の数字でいきますと。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これまでは骨子（案）と書かれていたものが、今回は概要（案）となっているのですが、骨子（案）から概要（案）というものに変わった意味が何かあるのかというのを、１つお聞かせいただきたいのと、この計画を策定するにあたって、コンサルは入っているのでしょうか。もし入っているのでしたら、どこが入っているのかもお聞かせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"他区の状況につきましては、具体的にどこの区でどうというところまでは押さえておりませんけれども、説明会を実施している自治体が、保険者があるというところは、認識しております。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点で、私は、品川区は説明会をやらないということで一貫しているのですが、こういう機会に区民の意見をぜひ、介護に対して切実な思いが区民の中にはたくさんあると思いますので、そういうのを聞く機会としても捉えていただきたいし、また品川区の方針を区民にお知らせいただくという、双方向でのというところで、説明会については、改めてやっていただくようにということで。","respondent":"宮尾高齢者福祉課長","answer":"説明会につきましては、少し繰り返しになりますが、パブリックコメントを含め、アンケート調査、モニタリング調査等も行っておりますので、区として実施する考えはございません。それから、調査につきましては、まず、計画の改定に合わせて行う調査があります。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"７ページの「見守りのしくみの充実」のところで、「ひとり暮らし高齢者、高齢者のみ世帯等が増加しているため」ということで書かれているのですが、これまで品川区のひとり暮らし高齢者の捉え方というのが、５００メートル以内に親族がいない高齢者を、高齢者のひとり暮らしということで規定するというのがあったと思うのですが、今はそういうのは全くなく、どの範囲で親族がいる。","respondent":"寺嶋福祉計画課長","answer":"ひとり暮らし高齢者の捉え方ですけれども、先ほど副委員長からお話があったような５００メートル等の基準は、一応まだ消えてはいないのですけれども、実際にこれは、３年に一度、民生委員が実態調査ということで行っていて、民生委員のご判断の中で。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、３ページのところで、各地域ごとの高齢化率というのが示されていて、八潮地域の高齢化率がすごい急速に上がっていると思うのですが、３５.５％まで上がっているのだなと思ったのですが、高齢化率がこれだけ高いとなると、様々な介護の需要というのも、それに合わせて出てくるのかなという思いをするのですが、今後の見通しと、八潮に対しての対応みたいなものは何か考えられているところがあるのか。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"そういった事業者が民間も含めていますので、そういった支援をしていくということを地域づくりと併せて取組む、そのような動きに今なっています。こちらを、３か年のうちの３年目に実施できれば、一番新しいホットな情報ということで取れるのですが、そうしますと、その調査をして、調査結果を集めて、集計して、分析して、それを計画に生かすとなると。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域包括支援センターということであれば、この保健師の数を私は増やすべきではないかと思うのですが、その点をお聞かせいただきたいと思います。支援第一係、第二係のところが地域包括支援センターという考え方でいいのか、それから、地域包括支援センターの責任者というのは誰になるのか、その点についてもお聞かせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ただ、一般的にご相談いただく内容を対応するのは、委員がおっしゃったように、高齢者支援第一係、第二係が多いというのは実情としてありますが、課全体でセンターの位置づけを保っていると思っているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、保健師が専門職として必要だからこそ、３,０００人から６,０００人に１人ということで規定され、品川区の条例でも書かれているわけですから、これは何度も何度もこの場でも申し上げてきたところですが、本当にこのような区は品川区だけですから、保健師をぜひ条例に沿った形で配置していただきたいと私は思いますし、在宅介護支援センターをハブセンターということで位置づけるのであれば。","respondent":"宮尾高齢者福祉課長、寺嶋福祉計画課長","answer":"ですので、我々も、この人材確保、育成策というのは、そういったところもありますので、この重点プロジェクトの１つに掲げて、体制をしっかりと整備し、できる限りの支援をしてまいりたいと考えているところです。高齢者福祉関係の福祉避難所としまして、避難所には特養１２か所、老健２か所、ケアホーム１か所が今の段階で指定されているという認識です。それから、今後につきましては……。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１６ページの「介護サービス量の推移と見込み」というところの、２つ目の表「主要な地域密着型サービスの月平均利用者の推移と見込み」というところで、夜間対応型訪問介護が、８９だったのが３５まですごく減ったのですが、これは何か理由があるのでしょうか。それから、療養病床が、今度は介護医療院に変わっていると思うのですが、今、区内に、療養病床というのは実際あるのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"１６ページのサービスの推移のところで、まず、夜間対応型訪問介護と老健に関して利用が減っているですけれども、これは、はっきりとこれというところではないのですが、やはり考えられるものといたしましては。一時的に新規の受入れを止めたということがあります。その影響が数字として出てきているものです。それから、介護療養型医療施設から介護医療院への変更点ですが、大きな変更点というのは特にないと思っています。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは、計画のたびに保険料が値上げされてきたというもので、保険料を決めるためのものでもあると思うのですが、今回は５,６００円から、６,１００円から６,３００円ということで、５００円から７００円のすごい大幅な値上げになるということで、これは高齢者にとって本当に大変なことだと思っているのですが、前回の第七期で、この基金を結局どれくらい取崩すことになるのかという。","respondent":"宮尾高齢者福祉課長","answer":"現在、まさに本日現在の基金残高は約１４億円。今年度末に一部取崩しを行う見込みとなっておりまして、約１２億円、この金額をもって第八期を迎えるものと想定しております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高齢化率がどんどん増えている、高齢者が増えているわけですから。ここのところで、国負担というのが２５％、そのうち調整交付金が５％となっているのですが、この２５％のうち５％が調整交付金ではなくて、丸々２５％と、調整交付金はそれにプラスするようにという、たしか区長会とか市町村長会とかでも、そういう要望を国に対して出していたと思うのですが、今でもそういう方向で出されているのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"基金残高と、基金と保険料設定との兼ね合いですけれども、今時点で幾らが適正かというのは、そのときによって状況が刻一刻と変わっておりますので、私どもも、最終的にこれから年度末に向けて、しっかりとサービス供給量の見込み等を精査していって。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やはりこの介護保険の保険料というのは、高齢者にとって本当に大きな負担になっておりますので、たしかそういう形で、自治体のほうからも要望していたと思うのです。本来であれば、５割はもともと国が負担していたわけですから、そういう形で増やすような方向でぜひ国にも求めていただいて、高齢者が払える介護保険料にぜひしていただきたいと思います。そのことも要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"障害者就労のところで、Ａ型が２か所でＢ型が１２か所とあるのですが、昨日の陳情の中にもあったのですが、選択肢を増やしたいということを、やはり当事者の方、当然ご家族の方は思っていらっしゃるという中で、Ａ型の事業、当然、最低賃金をクリアしなければいけないということなのですが、今これは何の仕事をされていらっしゃるのか教えていただきたいということと、就労Ｂのほう。","respondent":"松山障害者福祉課長","answer":"２点目の重度障害者へのＩＴとかロボット等を使いました社会参加につきましては、非常に重要なことだと考えております。重度障害者の方が何か社会と関わる機会というのを、私どもも今現在検討しています。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういう中でも、やはりできるだけ選択肢を増やしていただきたいということと、今、そういうＩＣＴを活用したというところでの社会参加、就労につながれば一番いいのですが、品川区もモスバーガーの本社がありますが、そういうところも今、レジなんかもそういう形で、試験的にやっているというお話もありますので、ぜひそういったことも前向きに取組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"というのも、例えば下神明のパン屋さんでパンを買ったりしますが、例えばそういうところでお一人でも障害をお持ちの方を、軽作業でも雇用いただけないかというような働きかけとかをやれば、区内でもそれなりに、何というのだろう、ご協力いただける、ご協力というのがいい言葉か分からないけれども、そういうところも出てくると思うのだけれど、ただ。","respondent":"松山障害者福祉課長","answer":"区内の中小企業への障害者雇用の啓発についてですが、今現在行っておりますのは、「げんき品川」で、品川区の就労支援関係機関連絡会、あるいは企業見学会というのを予定しておりまして、まだまだ区といたしましては、今現在。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"医療的ケア児ですが、医療的ケア児、者も含めて、人数の正確な把握がなかなか難しいということで言われているのですが、この児の場合、今回はレスパイトと障害児支援等の利用者ということですが、医療のほうだけで、こういうサービスを利用していないという方はいらっしゃらないのか、これが全てと考えていいのか、そこら辺の考え方を１つ教えていただきたいのと。","respondent":"松山障害者福祉課長","answer":"ただし、この連絡会は非常に重要と区は考えておりますので、今年度中には何かしらの形で実施したいと考えております。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この連絡会は、コロナ禍でももういろいろなところで実践協議会もされていますし、いろいろなところで始まっていますので、今年度中にはということですので、ぜひ期待したいと思います。それは、どういう資格、専門職の方がされていて、何人くらいいらっしゃるのか、また一般企業に入られた方で辞めてしまう割合みたいなものが分かったら、教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"定着率ですが、先ほど申し上げました「げんき品川」で２４人の方が就職をしたということですが、その前の年から、支援開始１年後の定着率というのを、東京都にデータで報告するものがあるのですが、それによれば７３％の方。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それで、例えば品川区役所とか、それから区内の社会福祉法人だとか、そういうところの法定雇用率というのは、今度、自治体とかは２.６％になるということですが、どれぐらいになっていて、これはもうクリアしているという状況になっているのか、その点と、あとは、障害者団体の皆さんからも、種別に雇用をしてほしいという、結構身体障害の方とかの雇用が多いと思うのですが、知的とか、それから精神、視覚。","respondent":"松山障害者福祉課長","answer":"当然ながら、障害者福祉課としては、どの方も適正に、ご自分が働きたいところで働く機会が得られるというのを目標としておりますが、この制度上のものというのは、品川区だけで独自に何かを考えるということは、なかなか難しいと考えています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"どういうところでどういう仕事をつくり出すかというところは、様々工夫すればできる部分というのがたくさんあると思うのです。そういう点では、障害者福祉課が、そういう特性とか何かも一番よくお分かりだと思いますので、課のほうからもぜひ働きかけていただいて、こういう形で目標を上げるというところも出ていることですので、ぜひそういうところでは働きかけも併せてお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40823,"voices":100}},{"id":"r02-20201201-8","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"建設委員会","time":"午前１０時００分～午後 ０時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年１月区営住宅入居者募集","agenda":"令和３年１月区営住宅入居者募集","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１点だけお聞きします。年に何回かこの区営住宅の募集があるのですけれども、当然、入居されている方の状況にもよりますが、実績として年間にどのくらい入れているのですか。もちろん場合によってになると思うのですけれども、大体平均的にというところでお願いします。","respondent":"森住宅課長","answer":"年間の募集住宅ですけれども、令和２年の７月募集では７戸でした。それから令和２年１月ですと、これも７戸です。その前の７月ですと、４戸という形になっておりまして、年間通しますと、１０戸前後、１５戸程度というところかなと思っています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"前回の募集倍率が幾つだったかを伺いたいと思います。","respondent":"森住宅課長","answer":"募集倍率につきましては、令和２年７月ですと、単身向けで４６.５倍、世帯向けで３７倍となっています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり高い倍率になっておりますので、どうしても区営住宅増設に向けて力を尽くしていただきたい、増やしていただきたいと希望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"（仮称）品川区立環境学習交流施設の検討状況","agenda":"（仮称）品川区立環境学習交流施設の検討状況","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"太陽光などの運用があるというお話だったのですけれども、雨水の利用とかもありますか。そこら辺の活用状況を。今、学校では太陽光などの、今どれだけ発電しているといったことなどがパネルで表示されているではないですか。確認をしたいのですけれども、ペットボトルの自動販売機とかの設置というのは、まさか考えていないですよねといったところを確認させていただければと思います。","respondent":"提坂環境課長","answer":"自動販売機についても、当然、今、施設の中に設置を検討していますけれども、環境にやさしい容器を使うことを想定して、ペットボトルなどは極力使わないほうがいいということで考えてあります。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"パネルでの太陽光だったり雨水の利用の状況の確認は検討中ということだったのですけれども、環境館ですので、ぜひそういった施設でもこういった実践を行っているし、区としてもこういう方向性であるといったことを、きちんと実践していることが見えるようにぜひやっていただきたいと思います。","respondent":"提坂環境課長","answer":"例えば今年度はＥＣＯエコフェスティバルは残念ながら中止になったのですけれども、来年のＥＣＯフェスティバルですとか、区内の様々なイベント等でそういうものをまず提供して、まず試行した上で、環境学習交流施設の中でも常設できるとか。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、八潮に環境情報活動センターがあると思うのですけれども、そことの関係性が、今後、この環境学習交流施設ができたときにどうなっていくのか。今、３０くらいの講座をやっていると聞いているのですが、その講座なども引き継いでいかれるのか、伺いたいと思います。","respondent":"提坂環境課長","answer":"こちらについては、環境情報活動センターの方と、こちらの環境学習交流施設の開設とともに発展的解消という形にはなってありますけれども、せっかく今まで蓄積した講座ですとか、あと区民環境記者のレポートというものもあるのですけれども。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"子どもたちにこういった関心を持ってもらうために、先ほど公園でのフィールドワークという話もありましたけれども、やはりそういった実際に公園の中にあるわけですから、自然と触れ合える環境もあるわけなので、そういったフィールドワークなども講座とかでやっていけたらいいなと思いますし、これまでやってきた環境活動がありますので、それをしっかりと活かして引き継いでいっていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"未就学児向けコンテンツで、括弧書きで「単純で分かりやすい」と書いてあるのですけれども、単純で分かりやすいツールの近年の一番の流れとして、過日の本会議の質問にもあったように、ＶＲの活用も一つありかなと。これがまさに単純で分かりやすい、今、一番のツールだと思うので、そこのところをどのように活用されるのか、どのような方向性をＶＲに対して持っていらっしゃるのか、教えてください。","respondent":"提坂環境課長","answer":"シカが歩いているような場面もあるのですが、それに触ると餌を食べるとか、そういうことで自然を身近なものと感じ取っていただきたいということを想定しております。ＶＲの活用とかその辺についても、どういう形で活用できるかということは検討してまいりたいと考えています。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"これは大分進んでいる話でありますし、私が総務委員会のときにも契約案件とかで関わっておりまして、中身については気になりつつもあまり質問できなかったので、すみません、ここでそもそも論を聞かせていただきたいと思います。なぜこの施設を造ろうと思ったのかという根拠をまず示してほしいのです。そこからお願いしたいです。","respondent":"提坂環境課長","answer":"こちらの施設については、平成３０年度の予算措置前から検討を進めてきてまいりまして、設立の趣旨としては大きく２点ございまして、まず１点目は、世間で環境教育への需要の高まりがあるということで、国のほうでアンケートを実施しているのですけれども。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"ただ、なぜこの施設なのですかというところなのです。こういう施設というのは非常に難しいのです。うまくいけば人は入るだろうけれども、１回来て終わりとかになりがちな部分もあって、飽きさせないというようなイベント、体験型、何ていうのでしょうか、そういう状況にするためには相当な苦労が要るし、新しい技術も加えていかなければいけないことなのではないかなと思うのです。","respondent":"提坂環境課長","answer":"先ほどお子様、小学生の皆様がフィールドワークをやっていただくとかということもお話ししましたけれども、施設の中で体験をしていただくのと、実際の自然環境の中の、戸越公園の中を散策していただいて、自然環境の保全を感じ取っていただければと考えています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"「なぜここなの？細かい話をすると、小学生以上向けと未就学児向けという時間設定をしているのですけれども、例えば未就学児、開館から１４時まで、この時間帯に誰が来るのですか。学校の状況であったり、環境学習というものを含めて、一緒に考えてやっていくとか、あと幼稚園、保育園の先生方といろいろと何かできないかとかというふうにして、運用は決めていただきたいと思いますが、いかがですか。","respondent":"提坂環境課長","answer":"基本は小学校３年生から６年生ということで想定をしていますけれども、その中で主に３年生とか４年生の社会科見学の一環として、まずは利用していただいて、その上で先ほど申し上げたのですが、リピーターという形でのご利用を考えてあります。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"３年生から６年生というターゲットは分からないではないのですが、では３年から６年生の間にこれだけの税金を使うのですかという話になってしまうので、そうではなくて、いろいろな方々にそれぞれ学んでいただきたいという思いもあるわけなので、運用についてはこれからいろいろな所管課とも状況を踏まえて議論しながら決めていただきたいと思いますが、それだけお答えください。","respondent":"提坂環境課長","answer":"今、ご指摘のとおり、様々な所管課と協議を重ねてまいりまして、より利用しやすい施設にしていきたいと考えています。小学生の利用時間ということであっても、大人の方が来ても楽しめるような仕組みにしたいと考えています。","id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"先ほど忘れてしまったので２点ほどちょっと確認を。１点目が、障害児者の方たちも楽しめる整備がされているのかを確認させてください。","respondent":"提坂環境課長","answer":"あくまでも補完する避難所という形にはなりますけれども、地震だけではなくて、台風が来たときの風雨水害とか様々な有事に対応できるように、まず場所の提供ということで１階のコミュニティラウンジとか様々な部屋に一時的に避難していただくとか。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"防災のところも分かりました。通路とかも、今ここでは車椅子の方とかもイメージ図に載っていますけれども、本当に通れるのかということとかも、開設前に、直せる段階のときに、ぜひ当事者の方たちに来ていただいて、実際に通ってもらって確認をしていただければと思いますが、いかがでしょうか。","respondent":"提坂環境課長","answer":"必要に応じて、実際に車いすを利用されている方、あと健常者が車椅子に乗って体験してみるとか、そういう形で使いやすい施設なのかどうかということの検証を重ねてまいりたいと考えています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう環境についてのＣＯ２の排出量みたいなところは多分５年、１０年で大きく変わると思うので、そうすると、常にそういうところを切り替えていくことも視野に入れてやっていったほうが、品川区の１つのシンボルにしていただきたいと思っているので、そういうことも視野に入れてやっているのですよね、というところでお伺いしたい。","respondent":"提坂環境課長","answer":"こちらの建物ですけれども、国のほうでNet Zero Energy Building（ネット・ゼロ・エネルギー・ビル）、略称ＺＥＢということで、環境配慮建物の使用ということで評価を進めているところですけれども、その中で、Nearly ZEBといって。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、それはいいことなので、そこが私は中心だと思うのです。そこをどんどん突き詰めていっていただきたいし、それはいろいろ今度高知県ともそういういろいろなこと（カーボン・オフセットの取組）でやっているというのも、あれは５万円程度でいいのかというのもあるけれども、もっといろいろな形で交流をして、そういうものをやっていくとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"若林委員","kind":"提案","question":"以前のどこかの委員会で、フードドライブについて、いろいろなところで子ども食堂絡みとかで提案、発言させていただいていますが、この施設に関して言うと、運営事業者候補者からもこのフードドライブ事業についての提案というのか、希望、推進していきたいというお話があって、今日の資料では、項番２の「運営事業者候補者と協議中」というところには。","respondent":"提坂環境課長","answer":"可能な限り、こちらの環境学習交流施設だけでなく、ほかの様々なイベントの中でも開催したいとは考えてありますが、実際のこの施設の中で常設できるのか、それとあとはポイント、ポイントでやるかについては、まだ正式には決まったところではございませんけれども。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、頻度の問題はありますけれどもフードドライブ事業ということで取り組まれていくということで認識をさせていただきました。ここにもありますけれども、防災関連というところで、そこが一番入りやすい、理解しやすい、感じやすいというところで、そういう俯瞰した意味で、ＳＤＧｓという一貫性を持たせた何か見せ方、考え方というところを、もしお考えがあればお聞かせいただきたいと思います。","respondent":"提坂環境課長","answer":"こちらの施設とＳＤＧｓについては密接な関係があると考えてございまして、ＳＤＧｓは１７のゴールがありますけれども、その中でも少し考えただけでも、「海の豊かさを守ろう」ですとか、「陸の豊かさも守ろう」、「エネルギーをみんなにそしてクリーンに」。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区、行政の中でいうと、今回の長期基本計画でいわゆるＳＤＧｓがずっと一貫して、文字として表現をされていたと。具体的にはそういうＣＯ２とか地球温暖化とかを本当に身に感じていくという、そういう一貫性というのですか、ＳＤＧｓを一つ象徴として、区民の皆さんにまた広めていける、感じていけるという施設を望んでおりますので、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"しながわ区民公園北側ゾーンの改修","agenda":"しながわ区民公園北側ゾーンの改修","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、まずアンケートを実施するということで、それは良かったと思います。それで、今回、たたき台としての案が示されたということで、これは前回いろいろな話があった中で、そういったことも踏まえたところで案を出されたということでいいのかということも伺いたいと思います。それと実際、今回アンケートを行う中で、周辺住民の方の対象範囲がどこまでになるのか、伺いたいと思います。","respondent":"藤田防災まちづくり部長","answer":"それから周辺住民の範囲ですけれども、基本的には区民公園全体の周辺の方々にはポスティングはいたします。実際、今回工事を行うところのエリアのすぐ周辺のところについては、先ほども申したとおり返信用の封筒を付したアンケート用紙を個別に配付するという形で行うものです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"たたき台の案のところで少し伺いたいのですが、今回、野球場でサッカー利用も可能にするということなのですけれども、今回、多目的施設化とした目的が何か、伺いたいと思います。それと今回、災害時の活用のための主要園路整備ということで幅員６ｍの園路にするということですが、これは実際の災害時のときにはどう使われていくのか、伺います。","respondent":"藤田防災まちづくり部長","answer":"それから災害時ですけれども、今回、改修案のたたき台のところで、ピンク色の太い園路が、ちょうど下の図面の上のほう、右のほうから左のほうに、ずっとつながる形になってありますけれども、この園路が南側ゾーン、それから中央ゾーンにもつながっておりまして。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"アンケートの実施内容のところで、時期なのですけれども、１２月中旬とお知らせがあったのですが、具体的にいつ頃なのかということと、あとアンケートは公園内だとパークセンターにアンケート用紙とポストを設置ということだったのですけれども、ここはプレイパークがあるではないですか。","respondent":"藤田防災まちづくり部長","answer":"それからテニスコートの人工芝ですけれども、委員からもお話があったとおり、マイクロプラスチックの話は、今、環境の中では重要な課題だと捉えておりますので、その辺も検討案を具体化していく中ではしっかりと検討しながら進めていきたいと考えています。","id":"exchange-022"},{"speaker":"田中委員","kind":"意見","question":"プレイパークとの関係のところなのですけれども、北側ゾーンで利用した方がプレイパークに来たり、またその逆とかもあると思うので、ぜひ協力していただければ、子どもたちの意見もより届くと思うので、ぜひ協力をしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"野球場のところなのですけれども、この芝は、今現在、天然ですか。そうなったときに、多目的だといい面もあれば、該当する利用者が多くなるという意味でいうと、なかなか借りられなくなる状況も出てくることが起きやすいのではないかと思いますので、そのお考えをお知らせください。","respondent":"藤田防災まちづくり部長","answer":"それから多目的にすると使いたい方がいろいろと出てまいります。おっしゃるとおりですけれども、そこは今、スポーツ推進課ともルールづくりも含めてどういう形で進めるのがいいのかというのは、しっかりと協議を進めていかなければいけない事項だと考えています。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"天然芝ですけれども、しながわ中央公園では、結局難しかったです。いろいろな経緯があったのは分からないではないのですが、夜間まで使えるようにと、それも１つの要望としてあるわけなのです。ですので、区としては近隣の問題があって、絶対にやらないという状況なのか、それとも近隣の方々の了解が得られれば照明を付けてもいいとか、その辺は考え方としていかがなのですか。","respondent":"藤田防災まちづくり部長","answer":"その辺の中で様々なご意見があろうかと思いますので、よく確認しながら最終的には公園管理の観点も入れながら、いい案がまとめられるように努めていきたいと思ってあります。それから照明につきましても、いろいろなご意見があります。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、先ほど言いましたように、区としてここは絶対にやらないというのだったらいいのですけれども、今、いろいろなご意見を聞いてとおっしゃるので、だったらこういう書き方ではなくて、「夜間利用についてのお考えはいかがでしょう」という近隣の住民の方々にお聞きする項目を１つ入れてもいいのではないかと思うのですが、いかがですか。","respondent":"藤田防災まちづくり部長","answer":"それぞれ区としてそういう限定をしているという形ではございませんので、様々なご意見をいただく考え方の１つとしてお示しをしています。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"仮に（アンケートの）９番の「その他、ご意見があればお書きください」と書いたとしても、そういう項目が頭の中に入ってこないのです。ただ、いろいろな意見があって聞きたいというのであれば、こういうふうに断定してしまうと、なかなかご意見は出てこないのではないですかと言っているのです。これから再考していただけるものなのかどうか分かりませんが、検討していただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと確認を。現状平面図と改修案のところで、トイレと駐輪場の記載が改修案になると消えてしまっているのですけれども、これは特にこれをなくすとかではないということを確認させていただきたいと思います。桜の広場のトイレについては、「トイレの洋式化」と書かれているのですけれども、今の機能を洋式に改善するという捉え方でよろしいのか、確認させてください。","respondent":"藤田防災まちづくり部長","answer":"基本的にはトイレについても駐輪場についても設置をする考えです。トイレについては、今、設計を進めている中で、そのまま利用することが構造的に大丈夫なのかどうかも含めて、確認をして、位置等も含めて検討を加えて、最終的な結論を出したいと考えています。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"要望になるのですけれども、トイレについて、ぜひ障害児者の方たちも使えるものであることと、あと男性トイレにも子どものおむつ替えの設備が付くように。そして、女性トイレに子どもが座れる椅子があるのですけれども、その椅子のすぐ横に鍵があって、子どもにいたずらされて鍵を開けられてしまうことがあるので、ぜひ上のほうに鍵を設置してもらうとか、そういった配慮をお願いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"ですので、そこのところも十分に斟酌していただきながら、ここの整備をお願いしたいと思いますし、今後、少年少女のスポーツを考える場合に、やはりいろいろな多岐にわたっている部分もあるのでしょうけれども、サッカーの聖地、野球の聖地、バスケットボールの聖地、そういうような１つ特色ある球場づくりというか、練習場というか、試合場というか。","respondent":"藤田防災まちづくり部長","answer":"しながわ区民公園のこちらの野球場が少年少女の野球の聖地であることは私もよく耳にしているところで、その辺については十分感じておりますので、その辺も踏まえながら、整備の方法については検討していくべきだと考えています。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"利用団体の方から、このたたき台に対して様々なご意見も聞いているのだろうし、私も聞いているし、そうなると、それをしっかりと要望として出します。いかにその要望に応えらえるかが一つ。小学校１年生からの子どもたちもやる。それはきちんとそのときも説明したけれども、もう約１０年も経つわけだけれども、そういうことも含めて、意見は出すけれども、よく考えてほしい。","respondent":"藤田防災まちづくり部長","answer":"その辺については、どう折り合いがつけられるかについて、十分に区の中で検討を進めていきたいと考えています。小学校１年生の打球の話等も伺いまして、おっしゃるとおりだと思いますので、その辺についても十分検討の中で参考にさせていただきたいと思ってあります。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"照明の件で、私もテニスコートの利用者の１人として、照明が非常に見にくいです。夜、テニスボールが見えないというくらい見づらい。それは考慮してほしいということであるのですが、あとここは照明があるのです。隣りの野球場はないのです。ですから、先ほどのアンケート用紙の話に入っていってしまうのですが、２回も言いませんけれども、その辺はどういう現状なのでしょうか。","respondent":"藤田防災まちづくり部長","answer":"これからどういう形が一番いいのかについては十分検討を加えていきながら、近隣の方々のことも踏まえ、区の案としてまとめていかなければいけないと考えています。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"今回の工事なのですが、下流部でいくと、地下深さ３５ｍというところをシールド工法で掘っていくということですけれども、最近、調布市のほうで大深度工事に関わって陥没があったと思うのですが、そこの近くで空洞も２か所発見されたということで、この工事はそういう心配がないのかということで伺いたいと思うのですが、いかがでしょうかということと、上流部シールドのところで、今回。","respondent":"松本河川下水道課長","answer":"２点目の家屋調査です。家屋調査につきましては、今回、シールドで下水道管を造っていくのですが、トンネルから約４５度の角度で家屋調査を実施する予定です。当初設計では６６０戸の調査をする予定でしたが、現地を精査した結果、７１７戸に変更するものです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでも上流部の工事はしてきているところではありますので、そういった安全面をしっかりとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"提案","question":"それから全体の公園のことをやっていきますというお話、いつもそう言われるのだけれども、これは逆にいつ頃そういう提案は出てくるのですか。河川下水道課の所管とちょっと違ってしまうのだけれども、みんなずっとあそこでやっているのはいいのだが、児童相談所も含めて全部そういうのをやるのだけれども、公園の計画は令和５年くらいでないと出てこないという理解でいいのかどうかだけ、少し。","respondent":"稲田土木管理課長","answer":"今、委員がおっしゃったように、今後、では全体、いつそういうのが分かってくるのかというのは、今現在、私のほうではその辺がいつ頃かというのは把握していないという状況です。今後の進み方等々を見ながら、これから全体を考えていくという話です。","id":"exchange-035"}]},{"id":"topic-04","title":"令和２年度 区内一斉防災訓練の実施","agenda":"令和２年度 区内一斉防災訓練の実施","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"冒頭にもコロナの感染状況を鑑みて、今回参加しないというところもありましたので、そういった、やはり地元の意見を尊重しながら、防災訓練も重要な訓練ですのでやっていっていただきたいと思います。その中で、少しご説明があったかとは思いますが、この新型コロナの対策をどのようにしてこの訓練をやっていくのかを伺いたいと思います。","respondent":"大森災害対策担当課長","answer":"各避難所につきましては、例年ですと、避難所の運営本部の立ち上げですとか、避難者の受付ですとか、それから物資の配給・配布訓練ですとか、そういった訓練を共通訓練としまして。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今回のコロナを踏まえた訓練というところで、今のご答弁があったと思うのですけれども、私が聞きたかったのは、実施するにあたってのコロナ対策を聞きたかったので、そういうご答弁がありましたらよろしくお願いします。","respondent":"大森災害対策担当課長","answer":"各避難所に対しましては、訓練の実施をそもそもやるかやらないかも含めて検討していただく際に、９月上旬に防災課のほうで訓練をやるにあたってはこういった形であれば実施について検討できますというところについて、通知を流しています。","id":"exchange-037"},{"speaker":"西本委員","kind":"確認","question":"目的のところです。この目的で、なぜ一斉防災訓練をするのかということなのですね。毎回、参加されない地域があって、それぞれやります。それはそれでいいと思うのです。そこの目的の「相互の連携を確認するとともに」というところが重要なのではないかと思うのですが、今回も含めて、コロナは別にして、一斉で訓練を行う意義、区との連携をどう確認して、どうやっていくのですかというところはいかがですか。","respondent":"大森災害対策担当課長","answer":"実際に災害が起きますと区の参集職員が動員計画に基づきまして、各避難所に派遣になりまして、被災状況ですとか、避難者の受付状況ですとか、その他安否確認情報ですとか、その辺は避難所連絡会議の地域の方と情報交換をしながら。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ単にそこの避難所の町会たちとの連携とかということであるならば、別に一斉にしなくてもいいということになるではないですか。だから品川区全体として、区内一斉に訓練を行う意義は何でしょうかということなのです。別にその意義がなかったらほかの日であっても構わないわけです。そこをやはり明確にすべきだろうと思うのです。そこを明確にしていただきたいと強く思うのですが、いかがですか。","respondent":"大森災害対策担当課長、藤田防災まちづくり部長","answer":"実際に一斉防災訓練につきましても、もともと始めた当初は１３避難所くらいから始まりまして、昨年ですと４５の避難所まで増えているという状況がありますので、委員がおっしゃるように、それぞれ昔からの訓練サイクルの中で。各避難所の訓練そのものはそれぞれの避難所の訓練として実施はできると思うのですけれども、一番大事なのは、区としてその情報を一斉に集めて処理することができるか、あるいは一斉に支援することができるか。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"今、部長がおっしゃっていることはまさにそのとおりだと思っておりまして、それをやはり伝えていただきたいと思います。もう１点だけ。全部がそうです。なかなかこれをこっちの町会をあっちに行ってとかというのは難しい部分があるので、だからほかの施設を利用するとか、民間の施設をお願いするとかということで、それなりにカバー率を上げていかなければいけないのではないかと思うのですが、いかがですか。","respondent":"中島防災課長","answer":"例えば、学校によっては、ほかの学校の補完避難所になっているというケースもありますし、都立学校などの施設も活用いたしまして、区全体でしっかりと避難者を受け入れるような体制で考えているところです。","id":"exchange-040"},{"speaker":"西本委員","kind":"意見","question":"民間の方々のご協力をいただいたりとかして、いろいろと考えられていると思うのです。どういう使い方をしていいか分からないので。ですので、そういう方も含めて避難所の在り方について、区はこう考えてやっているので、町会・自治会の方々に一緒になって考えてもらうとか、認識を高めてもらうとかしていただければと思うので、今後ご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"対応はしているけれども、実際に聞き取りを行っていないといったところがありまして、今後、どういう情報提供がいいのかを、機会を捉えて行っていくといったご答弁だったと思うのですけれども、どのような機会を捉えているのかと、現状どういった情報提供をされているのかを伺いたいです。","respondent":"中島防災課長","answer":"私から外国人への情報発信について、机上にお配りさせていただきました資料に沿いまして説明します。初めに、１、外国人への情報発信の現況です。主なものとして４点ほど記載しています。初めに、（１）ラジオのインターＦＭです。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"そのタブレットを少し調査したときに、庁内と各地域センターで５０台所有していて、外国人の方たちに対する１３言語と手話の通訳機能を備えたタブレットを持っているということだったのですけれども、こういう何か災害時だったりとかにそれは活用できないのかというところを少し確認させていただきたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"２番のところなのですが、これは、国際友好協会はそれはそれでいいのですけれども、それだけで済むのでしょうかと思うのです。国際友好協会がいろいろと活動されているのは分かります。例えば学校とか、親が海外の方とか、現状として、クラスに１人、２人以上いると思うのです。現状、それだけで分かるのだろうかと思うのですけれども、ほかのツールはありませんか。","respondent":"中島防災課長","answer":"防災課と連携している国際友好協会の事業の中で、結構、多国籍な方々が地震の体験であったり、いろいろなお勉強をされているところですので、ある程度のカバーはできているというところでこのように考えておりますが、不足する部分であったり。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"もちろん国際友好協会ではいろいろな方々とお付き合いがあるので、情報はたくさんあるかなと思うのですけれども、ただやはりこういうものは個々のニーズになってくると思うのです。そういう方法もぜひ考えていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"若林委員","kind":"提案","question":"そういう方たちが被災された、発災に遭遇された場合に、いわゆる区の多言語による情報発信がない場合、どこに頼るかというところが私たちの問題意識としては前段にあって、それは例えば、今出たような、では商店街で外国人の方に、マンツーマンというのですか、いわゆる助け合い、そういう共助の地域をつくっていこうというのは提案したりした覚えがあるのですが。","respondent":"中島防災課長","answer":"情報発信につきまして、今回は４点ほど書かせていただいていますが、そのほか品川区の外国人向けの生活情報誌であるとか、様々な媒体で広報広聴課では発信しているところでございまして、今後もより良いツールは、連携して。","id":"exchange-046"},{"speaker":"若林委員","kind":"質問・要望","question":"大崎第一地区の、例えばタイ大使館とかインドネシア大使館。インドネシア大使館は、結構、積極的に地域に来られるという様子もうかがっています。今の話は、いざ何かあったときのいわゆる連携、事前の防災訓練みたいな話で、今回は防災に関する情報発信についてという角度のお話なので、今のお話とはまた違う展開になるのだろうというところも含めて、今後、取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"少し勉強不足なのですが、今回、外国人への情報発信ということで４点、書いていただいているのですけれども、外国人の方が実際にここにつながっていけるのかなと思うのです。もし地震など災害が起きた場合に、まずどこに行くというのか、何をするとか、外国人の方がどうつながっていくと区では考えているのか、伺いたいと思います。","respondent":"中島防災課長","answer":"そういうところとか、先ほどの国際友好協会の事業など、使えるところをしっかりと捉えながら、情報発信に普段から努めていきたいと考えております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"意見","question":"観光客として来られた外国人の方だと、そういう普段の発信とかは分からないです。そういう方たちが地震とかが起きた場合に、まず何をすればいいのかが分かるようなところを区でも考えていただいて、情報発信ということであればそこにつながっていける、得られるというふうにしていかなければいけないのではないかと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40856,"voices":143}},{"id":"r02-20201201-9","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"文教委員会","time":"午前１０時００分～午後 １時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"希望申請者の割合が大分減ったと思うのですけれども、その理由はどのようなものと分析しておられますでしょうかというのが１つと、あと、そもそも論として、区教委としてなぜ学校選択制を行っていいるのか、ねらいは何なのか、改めて伺いたいと思います。","respondent":"篠田学務課長","answer":"学区域を変更したことによりまして、これまで中学校と小学校の結びつきの関係で、これは１つの小学校から幾つもの学校に分かれてしまうという状況があったのが、グルーピングがされたということで、今までですと、例えばお友達がほかの学校に行ってしまうので。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"改めて伺ったわけですけれども、教育の現場に競争原理みたいなことを導入すると、やっぱり違和感がどうしても、今の答弁を聞いてもあります。それと、具体的にお伺いしたいのですけれども、その前に、全体の評価としては、希望割合が減っているのに抽選校は増えていると思うのですけれども、これは選ばれる学校と選ばれない学校の差が開いているということになるのでしょうか。","respondent":"篠田学務課長","answer":"増えている学校についてですけれども、逆に言うと、今のと裏腹の部分ではあるのですが、ある程度、規模が大きい学校が選ばれる傾向がこれまでもございましたので、そういった点では、そういった学校を選ばれる人が増えているのかなと考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それと小・中一貫校ですが、小学校の希望申請では、転入がかなり多いと思うのですけれども、中学校の方では、転出が大分多いと思うのですが、その理由はどのように考えていらっしゃるのかを伺えればと思います。","respondent":"篠田学務課長","answer":"こちらは、それぞれ特段の事情がありますので、特に今時点では、まだ入学された時点で今回の学事制度の変更がなかった時代に入学されているお子さん方ですので、そういった意味では、小・中の連携がまだされていない形で入学されるお子様方が小学校に在籍されて、そして。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"抽選校の中でも、住民基本台帳上の数と比べてかなり逼迫している学校が、御殿山ですとか、第二延山もそうですかね、この見通し、去年までは一応ぎりぎり入っているとはいえ、今後、どのように見通して対策を考えていらっしゃるのでしょうか。","respondent":"篠田学務課長","answer":"これに関しまして、どちらも実は改築をされたばかりの学校なので、なかなか対策をとるのが、我々も苦慮しているところではあるのですけれども、でも、来年度あたりに関しましては、いろいろと工夫をしまして、新しく普通教室として使える環境が、今、出てきまして、これから先。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"ある程度、この入学希望者数、あるいは住民基本台帳上の新入学者の数は、数年先まで見通せるものだと思うのです。そうすると、例えば３年、５年先、こうした学校はまだまだ増えるような状況なのでしょうか。","respondent":"篠田学務課長","answer":"その先に関しましては、いわゆる区の人口推計等を踏まえながら、一応、今のところでは、まだこの先１５年ぐらい子どもが増えるという推計が出ていますので、それを踏まえまして、どういった対応をとっていくかは、直近の対応ではないのですけれども。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"来年度に特別教室、あるいはその他、教室を潰して転用して教室を増やすというのは幾つぐらいですか。","respondent":"篠田学務課長","answer":"今の時点で、来年度の工事計画等は予算との絡みもあるのですけれども、ここのところ、例年ですと、５校前後で増やしていくような状況がありますので、これも人口の増加と併せて、同じぐらいの数をこういう形にしていくが必要あるのかなと考えているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"こういう結果になってしまったことに対する対応とか対策は、どのようにお考えになっているのでしょうか。","respondent":"篠田学務課長","answer":"それぞれの学校はいろいろと考えながら、お子様方を自分の学校に、できるだけ地域のお子さんが残る形でそれぞれ対応をとっています。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほども答弁があったかと思うのですけれども、本来自分の行けるところの周辺の学校が改築されて、新しくなって、そっちのほうが魅力的だと映る場合もあるかと思うのですが、そうすると、やはり改築を全体的に急いでやっていただいて、その改築で新しくなったかどうかが選ばれる基準になってしまうと、結構、古い学校は厳しいかと思うのですけれども。","respondent":"有馬庶務課長","answer":"若干、そういう影響はあるだろうと思っていますけれども、教育の中身で充実していくということは、校長先生も、日々、学校説明会でも行っておりますので、そういったところもしっかりとバックアップしていきたいと考えております。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"基本的なこの見方について、１番の小学校のほうの城南小学校でいくと、住民基本台帳が１５１名いらっしゃる。だけれども、そもそも住民基本台帳上、減を除いて１４０名の方が、そのまま予定どおり希望したとすれば、抽選で仮に１番目になっていたとしても、抽選で誰一人入れないと、こういう理解でいいのでしょうか。","respondent":"篠田学務課長","answer":"受入れ枠は１３０名なのですけれども、小学校の一定の数の方が私立へ行かれるということがあるものですから、そういった減も見込んで、受入れ枠を１３０名ほどの４クラスの設定でしています。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"ですので、個別の細かいところまではなかなか難しいかとは思うのですけれども、表の見方の基本的な部分の分かりやすい説明文をつけていただくなど、ホームページ等で工夫をご検討いただきたいと思っているのですが、いかがでしょうか。","respondent":"篠田学務課長","answer":"変更したのは、「入学予定者数」とこの表では書かれているのですが、こちらを「入学希望者数」という形で、結局、予定者数が何かがよく分からないというお声もありますので、そちらに名称を変更した上で、欄外に、この表にはないのですけれども。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"幾つかお聞きしたいのですけれども、私は去年も質問させていただいたのですが、特別支援学級の数とかが出てこないのです。答弁で、年度末に合わせてということで、年度末に数はあったのですけれども、改めて、特別支援学級の数を載せていないのはなぜかを教えていただきたいです。そういったところも理由として入れていただきたいと。","respondent":"篠田学務課長","answer":"そういうことも踏まえまして、学校選択の運用の中で、いわゆる特別支援については、思いとしては私どもも受け止めしますけれども、制度上の違いがあるということから、なかなかそのような形で取り込んでいくことは難しいかと考えているところです。","id":"exchange-011"},{"speaker":"せお委員","kind":"質問・要望","question":"最初の特別支援学級は別で、相談でということなのですけれども、広報にも特別支援学級の数は載っていないのです。そういったときに配慮がないというのは、上のお子さんが在籍しているときにはあってというのも、それだけど私は寂しいと思っていて、そのような方だけではないのですけれども、いろいろな状況の方のお話も聞いていただきたいと思うのですが、そこら辺は状況としては無理でしょうか。","respondent":"篠田学務課長","answer":"難病でいらっしゃって、どうしてもかかりつけの病院のそばでないとだめとか、そういったレベルでないと、今のところは対応をしていないところです。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"確かに個別で全部聞いていると、本当に大変かと思うのですけれども、兄弟枠があるということは、兄弟枠だけではなく、違った枠での検討もしてほしいと私は思っていますので、そこは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほどからのやり取りを伺っていて確認させていただきたいのですけれども、この表の中には、特別支援学級に進まれるお子さんは、完全に数字に入っていないということなのでしょうか。住民基本台帳枠で、例えば城南小学校１５１人とありますけれども、このエリアの中に特別支援のお子さんが例えば３人いて、本当は１５４人なんだけれども、そこは除いて１５１という書き方をされているのでしょうか。","respondent":"篠田学務課長","answer":"ただ、学校選択自体をされる・されないは、特別支援の方でされる方もゼロではないということではあるのですけれども、そこは就学相談等々の関係もありますので、必ずしも特段、その時点では相談中ということでされていなければ、そのまま学区域の学校に。","id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"確認ですけれども、住民基本台帳上の数字は、全てのお子さんを含んでいて、希望申請は出されないから、この枠、それ以降の右の枠には入ってこない、受入れ枠も、支援学級がここの数字に入っていないということですか。","respondent":"篠田学務課長","answer":"というのも、これから就学相談等を受けられて、特別支援学級に行かれるかどうかということは、まだ確定はしてございませんから、逆に言うと、いわゆる普通学級に進級されて、特別支援教室の対応等、様々ありますので。","id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"とすると、左の住民基本台帳上の数字には含まれていて、受入れ枠には含まれていないということは、単純な足し算・引き算だけでは、いわゆる普通学級の過不足についてプラスマイナスは、厳密には計算できないということになりますよね。細かい数字の話で恐縮ですけれども、確認です。それと、先ほど、せお委員が言われていた兄弟枠の話です。そこの矛盾はどのように考えていらっしゃるのか。","respondent":"篠田学務課長","answer":"何らか、そういった先行きを見通したものが対応が取れるのであれば、そういったやり方もあろうかとは思うのですけれども、現状ではなかなか、そういった体制をとるところまで踏み切れないところがありますので、思いとしては私どもも受け止めするのですが、制度化していくことは。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれ、現状はそうであるという考え方は分かりました。それと、１点質問を付け加えさせてください。いろいろな仕組みが、今のところ区立中学校に限定して提供されているものが多いと思うのですけれども、３割は私立中学校で担っているのは、品川区としても、その状況を必要としているわけですので、そこはぜひ、よりオープンにということでご検討いただきたいのですが、いかがでしょうか。","respondent":"齋藤教育次長","answer":"私立を選択された方には、子ども政策の中で様々な取組みをさせていただいています。小学生であれば、まもるっちをお配りする、奨学金などのいろいろな取組みをしておりますが、基本は、義務教育を基本に運営していますので、ご理解をお願いいたします。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"私立中学校も義務教育だと思うのですけれども、私立は義務教育の一環ではないのですか。","respondent":"齋藤教育次長","answer":"すみません、言葉が足りなかったと思います。公立の義務教育中学校と、義務教育後期課程の管理・運用をさせていただいているです。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"私は、教育委員会には、品川区の子どもたち、特に義務教育段階にある品川区の子どもたちに対して、全てに愛情を注いでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"令和元年度品川区立学校における体罰等の実態把握","agenda":"令和元年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"そもそもですけれども、これはいつぐらいから始まって、毎年やっていらっしゃるのかどうかということと、それから、幸いにして体罰はゼロだということなのですが、私も勉強不足で、体罰と不適切な行為、特にアの不適切な指導、手をはたく等、この辺の線引きが、非常に分かりづらいと思うのですけれども、その辺の、どのような線引きでこれは体罰でなくて不適切な指導になるというようことが分かれば。","respondent":"工藤指導課長","answer":"挙がってきたものは、最終的に校長がその学校の対応等を確認して報告していただき、私どもも精査をし、最終的には東京都教育委員会とやり取りをする中で判断しているものです。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、軽微な非該当に当てはまるものは、わざわざ場を改めて設けるというよりは、聞き取りをしたときの中で、もしくはどこか別のところで、一つ一つ細かく、これはそうだこうだとやらないかもしれないけれども、子どもたちが分かるようにしているのかということと、あと質問が最初と違いますけれども、教員本人とか他の教員から出ているケースについては、数は少ないですが、大体。","respondent":"工藤指導課長","answer":"児童・生徒へのフィードバックについては、聞き取りをする中で、「実際にそうだったんですね」と理解を示すものもありますし、また、そのように丁寧に説明しています。例えば不適切な指導を行った場合は、教員自体、本人が申し出るのがほとんどですけれども、そこに居合わせた教員からも上がってくるというところはありますので、そういったことで、こういった案件を報告するようになっているところです。","id":"exchange-021"},{"speaker":"芹澤副委員長","kind":"確認","question":"４３件になったのは、内容としては非該当がほとんどということですけれども、それがどんと増えた理由は、説明されていたと思いますが、もう一度伺えればと思います。","respondent":"工藤指導課長","answer":"挙げた結果、それが例えば非該当ということもあるのですが、やはりこれらは、そういった事案の掘り起こし、そういったことを根絶するために必要なことであると繰り返し説明する中で増えてきているのは、私どもで言えば。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"もう少し、この挙がってきた案件を分類する過程といいますか、もう少し説明してもらいたい。誰がどのように最終的に関わって判断するのかという、その申告からの流れをもう一度お伺いしたいのと、あとは、学校のほうの報告数ですけれども、これは「特にありませんでした」と言っていれば報告がないというふうになるということで、全５２校中の２４校ということでよろしいのか、これを伺いたいと思います。","respondent":"工藤指導課長","answer":"これは調査期間だけではなく、４月１日からですので、先ほど申し上げたように、例えば不適切な指導の事案は、その日のうちに入ってくるものが当然ここに集約されてくるというところがありますので、そういった、それまでに報告があった事案も含めて、また、掘り起こしも含めて。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"成長途中の子どもの体だけでなく、心にも複雑で深い傷を残すと思いますので、体罰をなくしていく努力は常に必要だと思うのですけれども、禁止とか根絶を叫ぶというか、言葉にして言ったりとか、それは啓発という意味では大事だと思いますが、あるいは通報とか罰則強化も、それだけではなかなかというのがありまして、やはりなぜ体罰がいけないのかを、基本的人権とか子どもの権利の視点などから。","respondent":"工藤指導課長","answer":"先ほどご指摘いただいたように、例えば３ページ、学校の取組事例の冒頭に挙げさせていただきました人権教育プログラムなどを活用して、職員の連絡会等で人権意識を高めるということは、学校で取り組んでいただいているところです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"体罰が学校で禁止であるというのは、考え方としては定着していると思うのですけれども、改めて学校内での体罰の禁止は、どういった法律に基づいているものなのか、そして、その解釈はいつ頃から言われているものなのかを教えてください。","respondent":"工藤指導課長","answer":"本調査も含めまして、これは本区だけでなく、東京都全体の取組みの中で言えば、この調査が始まった平成２４年度、その段階で体罰等の関連行為のガイドラインを東京都が示し、全区市町村で取り組むというところが大きな流れと認識しています。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"ご存じのとおり、児童虐待防止法が改正されまして、今年の６月から、親、親権者であっても、体罰禁止と法的に規定されました。新しくできたものなので、かなり今の考え方を取り入れていると思います。学校の中で先生たちご本人、それから第三者から見ても、それがどの程度取り入れられてきているのか、体罰に対する新しい考え方に、今後、学校も合わせていくべきだと思うのですが、そこはいかがでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"指導上許される範囲内であっても、大きな声を出すだけで、それに対しては、やはり怖いと感じる児童・生徒がいるのも、本調査の場合では、例えば非該当に当たる内容であっても、それらを学校にきちんと周知をして。保護者会や新１年生の保護者会では、「そのようなことがあった場合は通告します、それが義務です」ということも、委員おっしゃったような事案、ネグレクトについてもそうですし、直接的な暴力行為でなくても、虐待の認識を持つことや。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこを平成２４年の段階でもこのようなことを言っているということではなくて、新しい考え方ややり方を、学校でもどんどん取り入れていただきたい、そのような姿勢も持っていただきたいのですけれども、そこはいかがでしょうか。","respondent":"工藤指導課長","answer":"ご指摘のように、社会の様々なそういった流れもありますけれども、私どもは、やはり児童・生徒に対して適切な、丁寧な指導を行う中で、あってはならないことが起きないようにという観点を持ちながら、様々なことを勘案しながら。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"他の自治体の事例ですけれども、そういった中学校での児童・生徒の暴力行為などが多い学校の事例を１つご紹介させていただきたいのが、生徒の心の傷に寄り添うこと、また、新たな心の傷を作らないこと、どならない、触らない、話は短く、罰を与えないということがすごく大切だということに気づいたという話を聞いたことがあるのですけれども、なるべく苦痛やストレスを極力与えずに指導していただくことが。","respondent":"工藤指導課長","answer":"児童・生徒への聞き方ですけれども、例えば本調査の場合には１２月ですが、ふだんから目安箱等を設置している中で、実際に、アンケート紙が目安箱の中にあったという報告があった案件も含まれてありますし、また、学校によっては、様々、アンケートを学期に１回行うであるとか。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"学校作りということに関しても、ぜひお聞かせいただきたいと思います。一人ひとりの先生方への知識ですとか、意識の向上みたいなところも、もちろん大切になってくると思うのですけれども、学校全体のそうした意識だけでなく、学校作り、子どもたちも教職員の皆さんもですが、安全な学校作りというところ、体罰を根絶していくための学校経営、学校作りについての現在のお考えをお聞かせください。","respondent":"工藤指導課長","answer":"個々の指導に当たりましては、複数の教員で当たれるような体制が、学校によっては、いわゆる自分一人で抱えられないときには、ＳＯＳカードを用意しておいて、これを職員室に持っていくことで、職員室に行った場合に職員室で駆け付けられる、それで。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"それがいいということではないのですけれども、個人の責任とか、個人の改善していただく部分と、学校全体として、また、品川区の教育委員会全体として取り組んでいくべき部分があるかと思いますので、そちらをきちんと切り分けていただいて、今できることをぜひ進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問・要望","question":"なので、そこは、そちらをメインにしていただきたいと思うのですけれども、そのような体罰等の報告をする専用の用紙、書式が決まったシートとか、そういったものはあるのでしょうか。その２つをお聞かせください。","respondent":"工藤指導課長","answer":"そういった意味では、特に大きな不適切な行為が起きたら、その当日、もしくは遅くとも翌日には私どもに報告が上がってくる案件ですので、そういったものも集めて、この調査自体は１２月にまとめてということがあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"体罰かどうかの最終的な判断権者が東京都教育委員会だということで、結局、５３件中４１件が非該当になってきて、大体、８割方が非該当になっているのですが、軽微といえど、有形力の行使を非該当にするのは、結構、難しいかとは、私は思うところですけれども、具体的にどのようなケースが非該当とされたのか。幾つか具体的な事案があれば教えてください。","respondent":"工藤指導課長","answer":"いわゆる軽微であっても有形力の行使というのは、それが指導の範囲内なのかどうかという吟味になりますので、基本的に有形力を行使した場合は、非該当に入るのは実はないということで私どもは認識しています。","id":"exchange-032"}]},{"id":"topic-03","title":"品川区教育大綱の改訂","agenda":"品川区教育大綱の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そういった中で、こういった大綱という形で長がつくるということなのですけど、教育委員会が行政の中の計画にすっぽりと組み込まれていくというのは、先ほど言いました教育の自主性、独立性からいって、やはりうまくないのではないかというか、問題があるのではないかと思うのですが、そこら辺、区の教育委員会としては、教育の独立性、自主性についてどのように考えていらっしゃるのかを伺いたいと思います。","respondent":"有馬庶務課長","answer":"例えば、教育委員会としての独立性はそのまま維持しつつも、予算編成ですとか条例の提案とかそういった法律上のものは首長にもあるということも現実的にありますし、分かりやすいところで言えば、放課後児童対策を学校ですまいるスクールを行っているということで。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"当然、すまいるスクールですとか様々なところで区の教育施策との連携というのはもちろん必要になってくると思いますけど、やはり行政の長が教育に口を出してくるという背景のもとでこういう流れが生まれているというのは事実ですので、連携はもちろん強めていく必要はあると思いますが、教育委員会として、住民、子どもの立場に立って言うべきところはしっかりと言えるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"教育大綱なのですけれども、位置づけをお伺いしたいのですが、大綱というのはまさに骨組み的なものだと思うのですけれども、今回といいますか、前回もそうですが、品川区の教育大綱は、大綱というだけではない様々な観点が割と細かく入っているかと考えています。","respondent":"有馬庶務課長","answer":"ただし、それであっても個別の事業までは書いていませんので、この方針に基づいた個別の事務事業については、これに沿って行っていこうと、ちょうどそのぐらいのレベルの大綱になっているです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"この大綱は、今後、印刷、配布ということなのですけれども、どの程度印刷して、どのようなところに配布をするのか。この教育大綱をどういった方々に理解していただき、共有したいのかを教えてください。","respondent":"有馬庶務課長","answer":"今、私どもが聞いているところでは、大体四、五百ぐらいを今回については印刷すると聞いておりまして、各所管のほか、例えば区政協力委員ですとか、地域の青少年対策地区委員の人たちとか、そういったところに配るようなことを聞いているところです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"せっかくつくった品川区の教育の根本の部分をより多くの区民にご理解いただいて、共通の目標の中で一緒に子どもたちを育てていくことができればと思うのですけれども、四、五百印刷で区政協力委員、青少年対策地区委員の方は読んでくださる方もある程度いらっしゃるかと思うのですが、さらにこうしたことに関心を持っていただくための方策を考えていただきたいというのが１つと、その際に。","respondent":"有馬庶務課長","answer":"前回つくったときも、見出しですとか写真を挿入したりとかいうような形でつくっておりますので、同じような形、大幅に変わるかどうかは難しいと思いますけど、そういう意見があったということは申し伝えておきたいと思います。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"前半の質問なのですけれども、パンフレット以外にどのような形で周知を図っていくかということについて。","respondent":"有馬庶務課長","answer":"基本的にホームページで公表すると聞いてあります。","id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"そうすると、これだけの労力をかけた教育関係の施策、あるいは思いなどについてもしっかりと詰まったものが、ほとんどの区民の目に触れないのでは、言葉は悪いのですけど、これは単なる役所の自己満足というか、こなし仕事になってしまっては大変よろしくないので、そこはぜひ工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"長期基本計画は中間見直しとかが行われていると思うのですけど、教育大綱も中間見直しは行われるのでしょうか。当然、時代の変化とかにあわせて直すところは直さなければいけないのかと思っているのですけど、その点、どうなのでしょうか。","respondent":"有馬庶務課長","answer":"今回につきましては、長期基本計画とあわせた計画をある程度踏まえてつくっていますので、当然、長期基本計画は中間見直しが行われると思いますので、そういったタイミングがあればそのときにあわせてこちらのほうも見直すということになります。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区総合教育会議なのですけど、傍聴もさせていただきまして、教育委員のご意見を少し伺った中で、そこに関連して伺っていきたいと思っています。状況ですとか課題ですとか、もしありましたら。今後のシルバー大学などでのカリキュラムであったりプログラムづくりに関して、どのように関わっていくのかというところの考え方について教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"横山委員","kind":"意見","question":"すみません。そうしましたら、ちょっと変更させていただけたらと思うのですけれども、今後どのように連携を図っていくというか、連携の状況といいますか、教育委員会からの連携の状況に関しての部分で構いませんので、お聞かせください。","respondent":"有馬庶務課長","answer":"あるいは、最後の質問の回答になりますけど、連携をということでありますと、今、学校では、学校の施設そのものが社会資本ということで、一般の施設開放利用ということで校庭開放や体育館の開放も行っていますので。","id":"exchange-043"},{"speaker":"せお委員","kind":"質問","question":"７ページのすまいるスクールなのですけれども、私は一般質問でもお聞きしましたが、全児童放課後等対策事業となっているのですね。答弁でもありましたが、医療的ケア児は安全の面でも通えないということで、ここのところで、教育大綱で掲げられていますので、全児童放課後等対策事業というものは改めてどういうものなかということと、すまいるスクールの１０年間の方向性がありましたらお聞かせください。","respondent":"廣田子ども育成課長","answer":"あり方としていいかどうかということとは別の問題で、低学年、小学校１、２年生はほぼ参加、登録も９割ほどされているので、安全・安心を考えたら、低学年についてはその形を守っていくというのはマストであると思いますし。","id":"exchange-044"}]},{"id":"topic-04","title":"子ども家庭支援センター開所日の追加","agenda":"子ども家庭支援センター開所日の追加","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ご説明いただきましたけど、当初から土曜日開所というのはある程度考えていて、準備の関係で今回、来年１月からということになったのか、それとも、今年４月に開所していろいろとやっていく中で土曜開所の必要性が出てきて追加的に行ったのかという、そこら辺の考え方をお伺いしたいのと、それと、土曜開所は当然いいことだと思うのですけど。","respondent":"崎村子ども家庭支援センター長","answer":"土曜日開所の考え方というご質問ですけれども、他区の子ども家庭支援センターにつきましては土曜日も開所しているところが３分の２ほどございまして、そういった子育ての相談をお受けする子ども家庭支援センターの機能を強化するといったことで。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"参考までに、開所してからこれまでの相談件数、特に１日平均の件数と、あと、土曜も開いてほしいという具体的なお声なり要望があったのでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"そういったところで、我々もこれまで柔軟に対応することで土曜日の訪問面接ですとか家庭訪問などを実施してきたところなのですけれども、改めて土曜日も開所しているということを周知いたしまして、相談を広くお受けしていきたいと考えているところです。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問","question":"土日は平日以上にニーズが大きい部分もあるかと思いますので、今後も体制を充実していただければと思います。それと、夜間や日曜日のご相談というのはどこが受ける形になっていて、それが子ども家庭支援センターにどのような形で共有されるのかも教えてください。","respondent":"崎村子ども家庭支援センター長","answer":"子育ての相談につきましては、一旦、宿直でお受けした後に、開庁日にご相談をいただくということで子ども家庭支援センターの連絡先をお伝えしていただいて、また、連絡先を教えていただければ我々のほうで月曜日以降にご連絡をして、お話を聞いているといった対応をしています。","id":"exchange-047"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれ開設日が９月１日になっていますけど、こういった開所に至るまで、品川区としてどういう考え方を示して開所に至ってくるのか、何か具体的な、開所の場所ですとか時期ですとか規模みたいな考え方をある程度持ってこういう事業者に募集みたいな、探してみたりとか誘致をしたりとかそういうふうになるのか、そこら辺の考え方を伺いたいと思います。","respondent":"若生保育支援課長","answer":"グローバルキッズ立会川園のご質問ですけれども、これも含めましてですが、開所の区としての考え方というところで、区としましては、待機児童対策でニーズ、需要、これは子ども・子育て支援事業計画にのっとって開設を進めているところですけれども、その中で必要量を算定し。","id":"exchange-048"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと勉強不足で申し訳ないのですが、そういった形で募集をしているということですけど、当然、ホームページということは誰でも見れるというか、そういう形で掲載されているのかという確認と、あと、今のご説明ですと、開設日ですとか、あるいは１歳児園なのかゼロ歳児園なのかとかというのも、ある程度品川区のほうの考え方を出してそれで募集しているということでよろしいのかも。","respondent":"若生保育支援課長","answer":"ただ、区として申し上げているのは、集団保育の観点からは、６０人以上の定員が必要であるという考え方があるので、６０人以上の定員を設定してくださいというような形で事業者のほうにはお伝えしています。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"今回、年度途中で２園開設ということなのですけれども、来年度については、４月の８園とこの２園のほかにまだ進行中のものというのはあるのでしょうか。それ以降の年度で何か見通しがあれば教えてください。","respondent":"若生保育支援課長","answer":"今年度につきましては、今回の９月開設の２園で、今のところはそれ以外の開設の予定はございません。それから来年度に関しましては、現在、ホームページのほうで募集をかけている地域があります。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"参考までに、例えば大井町などでは、ひろまち保育園がなくなって、あのあたりの受け皿がぐっと減ったかと思うのですけれども、地域的に今ちょっと入りにくいエリアというのは、どのあたりと認識されていますでしょうか。","respondent":"立木保育課長","answer":"大井町周辺を含めまして、保育支援課のほうで新規開設を進めておりますし、また、年度途中でも開園していますので、そこら辺は地域バランスをとりながらやっていっているという認識です。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40849,"voices":138}},{"id":"r02-20201201-5","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"総務委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"質問ですけれども、今回の補正予算ですが、今の第３波に対応するものなのかどうか伺いたいと思います。ご承知のとおり、都内では４００人、５００人と陽性者が確認されたり、最近では重症化し、入院されて、そのベッド数が足りないという深刻な状況が生まれていると思います。","respondent":"品川財政課長","answer":"予備費等もありますので、状況に応じて、必要なときにはそれらも活用しながら対応していきたいと考えています。ご質問にありますように、区としては、第３波は認識して、状況に応じてどういう対策を取ればいいかということは日々検討しながら進めている状況です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"確認","question":"先ほど伺ったのですけれども、第１波、第２波、第３波と感染拡大状況や医療体制の逼迫、また社会経済への影響を思うと、危機的な状況だと私は思っているわけですが、区は危機的な状況だと思っているのか、そこを改めて伺いたいと思います。基本的なことですけれども、検査の拡大で感染をしっかり抑制するという立場に立つことが必要だと思いますけれども、その点はどのようにお考えでしょうか。","respondent":"品川財政課長","answer":"ＰＣＲ検査については、区としてもＰＣＲ検査センターを設けて、必要な方については随時対応してきているところです。今回の補正予算でも東京都の補助もありますが、介護入所者等については対応していくなど、ＰＣＲ検査についても徐々にしっかり進めている状況です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"現在ホームに入所されている方は対象としない。障害者施設に至っては、今回対象にしていないというのは改めるべきだと思います。改めて伺いたいと思います。政府の資料でも、新宿歌舞伎町で感染が拡大した際に、ＰＣＲ検査を大規模に行って、感染が抑制できたということは統計的にも明らかになっておりますので、区もぜひ検討していただきたいと思いますが、いかがでしょうか。","respondent":"品川財政課長","answer":"こういった状況も踏まえて、現場サイドとしては、国・都の補助金の申請の細かい部分がまだ出てきていなかったというところがあり、最近になって少し出始めているというところで、その情報をしっかりと把握して、対応できる部分については進めていきたいと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど言った高齢者や、介護施設の職員全員や利用者の方々に対して、国や東京都も助成を行うとしているわけですし、今の第３波の急激な感染拡大に直ちに対応していただきたいと要望したいと思います。区はどのように考えているのか。しかも１回限りなのです。長期化しているわけですから、この支援を拡充・継続していくべきだと思うのですが、その点を伺いたいと思います。","respondent":"品川財政課長","answer":"今回は、区としてコロナ禍の中で医療機関に頑張ってくださいということで、応援金という意味でお出ししているというのが１つの趣旨かと考えています。これはまた状況に応じて必要な部分があれば、今後も対応していきたいと考えています。それから２番、販路拡大です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"一層強めていただきたいと思います。何よりも国の対応があまりにもずさんだと私は思っております。国は、持続化給付金、家賃支援給付金、雇用調整助成金といったさまざまな支援をやっておりますけれども、最後に改めて国に対してそれを一度限りで打ち切りとするのではなく、継続して、財源も含めて実施するよう求めていただきたいと思いますが、いかがでしょうか。","respondent":"品川財政課長","answer":"区民が安全に暮らせるように、中小企業もしっかりと事業が継続できる、それから、新型コロナウイルス感染症についても、スピーティーに対応していくことを今後も進めていきたいと考えております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ国に対しても意見を求めていただきたいと改めて求めたいと思います。今、経済とのバランスというお話がありました。新型コロナウイルス感染抑止か経済かみたいな議論をテレビでよく見るのですけれども、命に関わる問題を経済と比較するというのはあまりに乱暴な議論だと私は思っております。そういうお立場に立っていただくことを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"多分いろいろな相談が増えて、その対応のためということは分かりますが、具体的にいつもと比べてどれぐらい相談が増えているので、これぐらい見込めば、普通に対応できるだろうという見込みがあって、こういう補正予算をつけられたのだと思うのですが、この中身についてもう少しご説明いただきたいのですけれども、いかがでしょうか。","respondent":"黒田人事課長","answer":"今回の補正予算ではそういったところの年度末までの見込みの費用も含めて、あと、その他、保健所以外でも、商業・ものづくり課の融資あっ旋のメニューですとか、生活福祉課の各種給付金の申請業務が増えているところにも人的措置をされておりますので。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"東京から来た人と、何日か一緒に過ごした家の人を受け入れたら、そこから感染が広がるのではないかと思っても仕方ないようなところがあるではないですか。その辺のことについて、私が知っているぐらいですから、皆さんにもそういう認識はおありになると思うのですけれども、先ほどからのご答弁で出ているＰＣＲ検査が必要な人というのをどの辺まで考えていらっしゃるのか改めて伺いたいと思います。","respondent":"品川財政課長","answer":"ですので、必要に応じて保健所のほうに連絡をしていただき、そこで検査体制をとるという体制は十分にとっておりますので、そういったところをご利用して対応していただきたいと考えております。","id":"exchange-008"},{"speaker":"吉田委員","kind":"確認","question":"分かりました。もう一つ、さっき私が聞き漏らしたのだと思うのですけれども、１８ページの児童保育費の保育関係事務費で感染拡大防止対策物品購入が計上されていて、これは一般財源ですか。さっきこれも新型コロナウイルス感染症対策指定寄附金と聞こえたのですけれども、その辺を確認させてください。","respondent":"品川財政課長","answer":"これは、基本的に寄附をもとにして対応していくという趣旨のものですが、金額的に寄附の額等で対応できない部分もあったところもありますので、そういう部分については一般財源を入れて予算を計上しているというものです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"ということは、児童保育費については、ここだけは一般財源が充てられたと理解してよろしいですか。","respondent":"品川財政課長","answer":"補足します。公立と私立でちょっと考え方を変えておりまして、寄附金は私立の保育園のほうに充てているもので、４目の児童保育費については全て一般財源で対応していると、そのような考え方です。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"最初に、１７ページの子ども食堂への運営費補助ですが、これは私も詳しいことが分からないので恐縮なのですが、申請が６カ所だけだと書いてありますが、実際にはもっとたくさんありますよね。なぜこうなっているのか、それとも補助金が使いにくいのか、その辺についてお聞かせください。","respondent":"品川財政課長","answer":"ですので、現行、子ども食堂でやっている業務よりも拡大する部分について補助を出していこうという考え方の補助金です。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"議論するつもりはないですが、本来なら、例えば母子家庭の方の就労先がなくなったり、現在大変な状況ですから、それならばさらに支援をして、子ども食堂で食事を出せないならば届けるとか、何かそういうふうに広げるのが本当は趣旨だと思うのですけど、区の事業ではないのですが、ちょっとそれだけは異議を唱えたいと思います。","respondent":"品川財政課長","answer":"今、そこに対して区として融資をしていくというところで対応策はとっていますが、融資といっても、例えば固定費を補う部分での融資という言い方もありますし、新規業態として何かをやっていくための融資というところもこの辺には含まれていると思います。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、Ｇｏ Ｔｏイートということで、本当にこの１２月、かき入れ時に区内産業、特に飲食業が何とか生き残るということは、大勢の人を救うのではないかと考えています。４人でどうなのか。こんなことをしていたらだめだと思うので、ぜひ財政課のほうで日本をリードするような手法をとっていただいて、皆さんが何とか乗り切れるようにやってほしいのですが、何かご見解をいただけますか。","respondent":"品川財政課長","answer":"ただ、経済も回していかないと、そういう部分で命を落とす方もいらっしゃると思いますので、やはりここの部分についてはバランスをとりながら進めていくということは非常に大事なことだと考えています。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、中小企業の新型コロナウイルス感染症対策に対しては、調査も含めて東京都が主体でやっているのは分かります。ですけど、やはり身近な自治体は品川区ではないですか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"確認","question":"ご説明ありがとうございました。１点だけ、電話相談センター等対応経費の部分の補正予算、年度末までの人員確保のためと確認をします。当初、２０人体制から、９月に、感染が拡大したことを受けて２３名に拡充していただいておりますが、この２３名は、保健所に関わる、自分が感染したかどうかＰＣＲ検査を受けたほうがいいのかどうかという相談員というところでの２３名でよろしいのでしょうか。","respondent":"黒田人事課長","answer":"この２３名の内訳ですが、帰国者・接触者電話相談センターの電話相談を６名体制で行っておりまして、そのほか濃厚接触者の健康観察業務というところで他の人員を配置していますので、そういった意味では、その中でローテーションで行っておりますので。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問","question":"今、少しずつ状況も見えてきましたけれども、爆発的に感染が拡大をした第１波のときに、どこに相談をしていいのか分からない、また電話がつながらない、そういう中での区民の不安が多くありました。その際には、東京都がやっていただいておりますけれども、土日の品川区の相談体制の考え方もぜひ柔軟にご検討いただければと思いますが、いかがでしょうか。","respondent":"黒田人事課長","answer":"相談業務体制につきましては保健所のほうで体制を組んでおりますので、また、今日いただいたご意見につきましては保健所のほうに伝えてまいりたいと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"予備費も積み増しておりますので、緊急対応としての予備費の活用や、また、次の第１回定例会は大分時期が離れていますので、第１回定例会を待たずに臨時で補正予算を組むことも含めて早急な対応を要望して、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"品川区教育大綱の改定","agenda":"品川区教育大綱の改定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"改訂について、その中身について１点伺いたいのですけれども、人権啓発課で昨年作ったマイセルフ品川プランにおいて、性の多様性について、重点項目として学校教育が位置づけられたと思うのですけれども、今回長期基本計画の変更に合わせて反映させたということですが、こちらの性の多様性については見当たらないのですけれども、どのような取り扱いになっているのか伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"委員がご指摘の点に関しましても、今後品川区総合教育会議の中でさまざま議論しながら、追加を検討してまいりたいと考えております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"追加を検討という説明だったのですけれども、長期基本計画全体の議論の中でも多様性というのが１つのテーマになりまして、とりわけマイセルフ品川プランでは、性の多様性についてうたっておりますので、ぜひそこを踏まえていただきたいと要望したいと思います。そこにも関わって、首長との関係、教育委員会の独立性について、区長部局としてはどのように認識されているのか、併せて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"どちらかというと、教育よりも、生涯学習、シルバー大学、また児童相談所との連携という、ご質問が教育委員会委員よりございましたので、そちらに関しまして区長の認識といいますか、その辺で1)2)のとおり生涯学習に関しましては、非常に重要な視点であるとか。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"今の答弁の趣旨は、総合教育会議にかかわる法改正とか、議事録公開ということで理解しているのですけれども、公開は当然ではありながらも、大変評価をいたしますけれども、この会議を傍聴したときに、資料の配付が一切なかったのですけれども、最近一般的にいろいろな会議が公開されて、資料の提供もあり、昔は資料をそのまま置いていってくださいというのが、持ち帰りも許されるようになって。","respondent":"立川総務課長","answer":"総合教育会議については、総務課が所管しておりますので、私からお答えいたします。資料につきましては、後日議事録とともに公開することになっておりますので、その場での配付はしなかったです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"ほかの会議でもそういうことだと思うのですけれども、特にこの会議について資料の配付が困難とか、何か差し障りがあるとか、そういうことなのでしょうか。非常に理解しにくい。せっかく傍聴にいっても、内容がよく分からないのは大変もったいないというか、せっかくの公開の場も、効果が半分ぐらいに減ってしまうのではないかと思うのですけれども、その辺について改めて伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"意見","question":"そういうこともきちんと載せるなりしてやっていかなければしようがないのではないか。今の人事制度では、品川区に３年いたら区外に出ていっていいわけで、またほかの教員が東京都のどこかから来る。その辺について、お答えはできにくいのかもしれないのですけれども、教育制度の充実も図ることが今後必要ですという一文を入れるべきではないかと思います。意見だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"私も要望だけになってしまうのですけれども、青少年教育の充実の中で、ＳＮＳ等情報通信のツールの適切な利用などが新しく追記になったというお話があったのですけれども、これがまさしくそうで、現在、関係機関と連携しているというのは認識しています。やはり子どもと保護者、先生がちゃんとした連携をとれる時間を見つけるとか、そういった充実の強化を強く要望したいと考えています。","respondent":"佐藤企画調整課長","answer":"私の説明がちょっと不足だったと思うので、２ページをご覧いただきまして、品川区の教育大綱の総務的な方針を定めるものというところです。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"義務教育課程においては、ＧＩＧＡスクール構想を前倒ししたことによって、生徒１人に１台のタブレットが与えられるといったところで対応が急がれている。高齢者だけではなく、外に出ることが今すごく怖いと思っている基礎疾患を持っている方の学びについて、今後大綱においてはどのようにしていく方針なのかを教えていただければと思います。","respondent":"佐藤企画調整課長","answer":"こちらの図でも触れているところですが、２ページに書かれておりますとおり、長期基本計画にも当然書かれていますけども、今後実施計画のほうでも改めて定めまして、着実に進めていくというところで、理念的な面も含めまして、今回大綱に載せているところです。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"質問・要望","question":"新型コロナウイルス感染症はだれもが初めて経験するものなので、本当に探り、探りというところもあるかと思います。子どもたちはもちろん、大人、高齢者といった方々それぞれが品川区で学び続けられるようなものになればということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"品川区庁舎機能検討委員会の実施状況","agenda":"品川区庁舎機能検討委員会の実施状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"品川区庁舎機能検討委員会の実施状況が説明されたわけですが、この間私はＤ案を撤回してほしいと述べてきましたが、区はＤ案を予定している。現在も庁舎機能の検討を進めているという状況です。ならば、新庁舎は延べ床面積が何平米なのか、何階になるのか、改めて建設費用は幾らを見込んでいるのか、そこを伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"規模についてです。現在利便性の向上を中心に延べ床面積を大きくすることを検討しておりまして、今現在これぐらいだというものは、まだ検討している段階です。建設費用につきましても、規模や構造に関わってきますので、今現在では検討している段階です。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私は、この前の議会に対しての説明会で同じ質問をしたときと答弁が違うので、正直どうしたものかと思っているのですけれども、これまで延べ床面積については７万平米ぐらい必要だとご答弁されているわけです。なので、Ｄ案でいくというのであれば、何平米なのか、何階なのか、建設費用は幾らなのか、改めて伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"延べ床面積につきましては、大きくすることを想定して検討を進めている段階です。建設費用につきましても、規模や構造が決まってきた段階で、概算を出していくことになっておりますので、まだ今は検討中です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"庁舎機能を検討しているわけだから、どういう規模の建物を想定して、それがないわけがないので、そこはぜひ示して説明すべきだと強く求めたいと思います。建物的には、まだ１６年もつのだと、いや、機械整備が困難だなど、いろいろ話はありますけれども、少なからず数百億円の公共事業になるわけですから、今は一旦議論を延長し、着工は延期していくべきだと思いますが、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"新庁舎整備計画ですが、現状庁舎は老朽化していたり、新たな行政需要に対応していくという課題もありますので、まだ長くかかる事業です。庁舎機能の検討をしっかり進めまして、整備計画を着実に進めていくことが必要だと考えております。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"第５回で終わらせるのではなくて、期間を延長して審議を深めていくべきだと思うのですが、改めていかがでしょうか。そして、工事の着工日ですけれども、延期の考えはないということなのか、そこを確認させていただきたいと思います。このコロナ禍のもと、なおさら延期すべきだと思いますけれども、改めていかがでしょうか。パブリックコメントは実施すべきだと思いますが、それぞれいかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"庁舎機能検討委員会ですが、２回目で防災・環境、３回目で区民に開かれた庁舎、また執務機能等、４回目で長く使われる庁舎、またセキュリティーやＩＣＴといったことをもしっかりと検討していきましたので、第５回で庁舎機能検討委員会を終えまして。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つのテーマを実質１回しか審議しないというのはあまりにも乱暴だと思います。ぜひ庁舎機能検討委員会の会期は延長していただきたいと強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"なので、この機能検討委員会のまとめが出た段階で、そこから抽出されたもっと具体的な事について検討されてはどうかと思うのですが、いかがでしょうか。ワンストップ窓口と一口に言っても、機能として持たせるのはすごく大変だろうと。トイレのことです。だから、そういうことを深めていくような機能検討の場がその次の段階として考えられるのではないかと思うのですが、その点についてお考えを伺います。","respondent":"濱中庁舎計画担当課長","answer":"さまざまな件につきましてご質問をいただきまして、まさに庁舎機能検討委員会であるべき姿や具体的な項目を検討していますが、今後基本構想や、例えば、設計のほうでどんどん深めていくものですので、これで検討が終わりではなくて、窓口の在り方とか。","id":"exchange-031"},{"speaker":"吉田委員","kind":"提案","question":"今日のところは、今ご提案したようなことはここで決めるようなことではありませんので、あくまで意見として申し述べました。今、本庁舎３階にユニバーサルベッドがついたトイレがある。生活ネットワークとしても、今の段階で急いで計画を立てることを進めるのではなく、ここで検討が始まったのであれば、丁寧に議論を進めるほうに重点を置いてやっていただきたいと要望して、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"世田谷区では、トイレについてさまざまな当事者の考え方も踏まえて、意見を出し合って、新しい形のトイレも検討されておりますので、ぜひそういうのも視野に品川区において検討を深めていただきたい。それでもまた新たな課題が見つかってくるものなのですけれども、バリアフリーについては羽田空港国際線での視点もぜひ十分踏まえていただきたいと思いますが、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"トイレも含めた共用スペースは、快適性、利便性、障害のある方や高齢者の方に配慮したものが必要になってくると思いますので、さまざまな先進自治体の事例や民間施設の事例を研究しながら、快適で使いやすい、またバリアフリーに配慮した庁舎を検討していきたいと考えています。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区庁舎機能検討委員会の実施状況についてということなので、私は意見だけ述べさせていただきたいと思います。というのは、今コンクリートにしても、鉄骨にしても、長寿命化で恐らく１００年もつという構造、資材を使うはずなのです。せっかく本体が１００年もっても、いろいろな場所に問題が起きたときに、何も改修工事ができないと困るので、それはちょっと考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"１日目の高橋しんじ議員の区政運営についてのご質問の中で、会計事故に関しての監査委員のご見解、たしか２つ見解を求められたと認識しております。もう一つのほうがよく理解できなかったので、本来使うべきでないお金について処理したことについてのご見解を改めて伺いたいと思います。","respondent":"今井監査委員事務局長","answer":"高橋しんじ議員に対する代表監査委員の答弁のうち、歳入歳出外現金による事故対応について申し上げたいと思います。答弁の中では、限られた時間の中で会計処理の方法を検討し、適用したものと理解していますと答弁いたしたものです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"それがご見解ということでよろしいのでしょうか。ちょっと変な聞き方ですけれども、要は、代表監査委員としては、そういう状況であれば、本当は歳入歳出外現金を使うべきではなかったけれども、今回の場合は限られた時間の中でやむを得なかったというのがご見解というご答弁だったのでしょうか。その辺がちょっと理解できなかったので、改めて伺います。","respondent":"今井監査委員事務局長","answer":"初めに、監査委員制度というのは独任制ですので、代表監査委員は外部的に全委員を代表しているものではございませんけれども、既に決算特別委員会の決算審査意見書の中で監査委員合議の上で決算審査意見書をまとめる際に。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"つまり、見解としては、会計事故については、こういうことが起きたことは大変遺憾だというご答弁をなさっていますが、その後の処理については理解したというところまでで、それが妥当であったとか、不適切であったという見解は出しておられないということでよろしいのでしょうか。","respondent":"今井監査委員事務局長","answer":"代表監査委員の答弁のとおり、会計管理室が限られた時間の中で会計処理の方法を十分検討して、監査委員としてはそれを適用したものと理解しているということで答弁したものです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"つまり、それがいいとか悪いとか、代表監査委員としては、そういう発言をする立場にはないという趣旨で理解してよろしいのでしょうか。","respondent":"今井監査委員事務局長","answer":"適用というお示ししている言葉の使い方としては、限られた時間の中でこのような方法をとったものも対応の一つということで理解しているということで、そのように受け止めていただければと思います。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"もしかしたら説明はあったのかもしれないけれども、今のやりとりの前提となっている会計事故が何なのかが分からなくて、限られた時間の中で対応したというのは、何があったのですか。そこだけちょっと教えていただけますか。","respondent":"立川総務課長","answer":"ただいまいただいた質問につきましては、現在会計管理室で再発防止策を進めているところですが、指定金融機関の協力が必要な再発防止策について現在協議を進めておりますので、協議が整い次第、改めて所管のほうから報告します。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":35057,"voices":109}},{"id":"r02-20201203-14","meetingId":"r02-cm12","date":"2020年12月3日","dateIso":"2020-12-03","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781582?Template=document&Id=6100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1118,"voices":7}},{"id":"r02-20201204-18","meetingId":"r02-cm12","date":"2020年12月4日","dateIso":"2020-12-04","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ０時０８分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの動画についてです。動画を見せていく対象をお知らせください。そして、制作がオリンピック・パラリンピック準備課ということだったのですけれども、作成する際には、区のほうからこういった条件でお願いしますといった条件や要望が出されていたのかというのを確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"作成する際の条件というか、作成の過程なのですけれども、もちろん区役所の職員も入りながら一緒に企画をして、撮影の際にはもちろん同行して、作成をしたものです。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"大変興味・関心を引く動画だと思ったのですけれども、とても残念なのが、対象が区民全般ということだったのですが、まずＵＤフォントだったりとか、仮名が振られていなかったり、また、音声での説明がないことから、障害がある方が楽しむことがどうなのだろうと。その工夫がされているのかというところも確認をさせていただきたいと思うのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今までもいろいろなご意見をいただいているところもありますので、それをいつも考えながらやっているところですが、引き続きいろいろなご意見をいただいて、作成はしていきたいと考えています。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"オリンピック・パラリンピックですので、なおさら慎重に作られるべきだったと思うのです。障害がある方たちも楽しめるというか、理解ができる動画であるべきだと思ったので、これから、これもオリンピック・パラリンピック準備課だけに限らず、この庁内でそこについての関心を持っていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、６本の動画を見ていただいた中で、２本がブラインドサッカーに関するものです。こちら、選手もインタビューといいますか、そこにも出ておりましたとおり、日本ブラインドサッカー協会もご協力のもと、作っているものです。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"批判はなかった。そうなのですね。特に問題がなく見られたということでしょうか。分かりました。ではそういうことでしたら、問題がなかったならよかったなとは思うのですけれども、ぜひそういった様々な障害のある方でも楽しめる動画を、作る際にはそういった意識を持っていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"レガシーということなのですが、大会施設とかインフラにとどまらないものだと、もちろん思います。伺いたいのですけれども、競技場の建設費と年間のランニングコストというのは幾らくらいになるのか。ホッケー専用の会場というのは、ここの大井以外にというのは、日本にどれくらいあるのでしょうか。伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは東京都の施設ということで、今現在は資料を持ち合わせておりません。大きな施設というものは、日本全国には４か所くらいあるというふうに記憶しております。関東近辺では初めての大きな施設で、あとは広島県ですとか、栃木県ですとか、割と遠くです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"メインピッチとサブピッチとがありますけれども、大会後というのはどちらも使えるのでしょうか。会場の管理者というのはどこになって、料金設定というのは使いやすいものになっていくのか。ホッケーだけではなく、様々な競技やイベントなどにも使えるようになるのか、区民が気軽に使えるかなどの運営の方向性や考え方について伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは東京都の施設で、東京都が管理をしているものです。実際の運用に関しては指定管理者が入るというふうに聞いております。大会後の使い方ですが、まず１つは、ホッケーの競技にはいろいろな大会がありますが、そういったことに使うのがまず１つあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"それで、使いやすい料金。ホッケーの用途であれば、私は無料でもいいのではないかなと思うのです。区民には開放してほしいというふうに思いますし、同時に多目的にという話もありましたけれども、すばらしい会場なわけですから、なるべく空いている枠内は様々な用途に、これも低廉な料金で開放すべきだと思うのですが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京都の施設ですので、なかなか私どもで区民だから安くいつでも使わせてくださいというのはなかなか厳しいかなというふうには認識しております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば区内最大の事業所の１つなわけですから、少しでも働き方を変えていくとか、スポーツに親しめるような、時間を持てるような働き方を率先して進めていく。それが、社会にも、区内にも波及していくというような、そういったスポーツに親しめるような環境づくりというのが私はレガシーだと思うのですけれども、ぜひそういったことを区としても進めていっていただきたいと思うのですが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"現在、ほかの所管課ですけれども、スポーツ推進計画も立てておりまして、その中でもそれはうたわれていることですので、区を挙げてそれは進めていきたいと考えております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの動画のことなのですけれども、ＤＶＤは地域と町会に配られたということなのですけれども、そもそもどのような活用を考えられているのかというところと、あと動画作成などについての予算内訳をお知らせいただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの予算についてなのですが、これだけで委託をしていませんで、ほかのもの、いろいろな啓発事業も含めてやっているので、これだけというのは金額として出すことはできないのです。申し訳ないのですが、今、お答えができません。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"幼稚園児だったり保育園児にも貸し出すときがあって、見る場合があるときには、先ほどもお話ししたのですが、仮名が振っていなかったり、仮名が振っていないと漢字だけだと読めなかったり、そもそも読んでくれないと聞けない、まだ文字も読めない子たちもいるので、そういったところの配慮というのをどのように考えられているのかというのを伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これも、今お見せしたとおり、できてまだ３か月、１か月、２か月など、ものによってできたタイミングが違うのですが、今年に入ってからですので、なかなか町会もいろいろなイベントもしていないという状況です。","id":"exchange-010"},{"speaker":"湯澤委員","kind":"質問","question":"例えば小さい頃には、けがをしないような、正式な競技では使わないような用具など、そういったもので競技をしていったりして、水をまいていなくても、そういったところで、砂の上でも競技をしていくのかとか、そういったところというのはどうお考えなのか、教えていただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ですから、芝でウォーターベースというのは、小さなお子さんですとか、競技をやっている中高生にとっては憧れの場所みたいなもので、普段の状況の中で練習というのもできるのかなというふうにも認識しております。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"意見","question":"どうもありがとうあります。品川区においてもホッケーチームが発足したということでありますので、ぜひほかの２競技、ビーチバレーボールとか、ブラインドサッカーも。ホッケーというのがかなりマイナーなところがあると思いますので、オリンピック開催地である品川区においては、競技人口も増えていくようなそういった取り組みをお願いしたいなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先日、ホッケーとビーチバレーボールとを見る機会をつくっていただきました。ですから、ぜひレガシーとしては、これからもそういう見る機会をつくってもらいたい。以前には大井町のどんたく通りでやっていただいて、今後の考え方として、どんたく通りではまず来年のコロナの状況が分からない状況にありますけれども、予定としては来年の実施を考えていらっしゃるのかとか、その辺を教えていただきたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ビーチバレーボールのほうなのですが、どんたく通りでこれからということなのですが、今回品川オープンを大森ふるさとの浜辺公園でやったのも、もともとはどんたく通りでやる予定でございました。そのときの予算が２,０００万円だったのです。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"残念な話に聞こえてしまうのですけれども、どんたく通りでやったとき、自分も通りがかりにのぞきに行ったりなどしますと、かなりの人数が見ていらっしゃるし、あれは通りがかりの人もいるので、区としてどのくらいの人数が、観客といいますか、通行しながら見たというか、どのくらいの人数を捉えていらっしゃるのか。その辺の数字を教えていただければ。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どんたく通りで昨年５月に行っておりますが、そのときが約５,０００名です。それから、その前もやったことがございまして、あれは平成２８年度です。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは先ほどの答弁とは逆みたいに聞こえてしまうのですけれども、要望しておきたいと思うのです。それから、恒久的施設ということで、ホッケーの競技場はあるけれども、品川区として、ビーチバレーボールの競技場を。これはやってほしいなという意味の質問なのですが。広さは分かるので、例えば２面くらい造ったときに、どのくらいの費用がかかるかというのを積算したことがあるのかどうか、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"恒久施設としてのビーチバレーボール競技場の検討ですが、過去においては、費用の話以前に適地といいますか、それを探すというので幾つか検討したようなことはあったかに聞いております。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"せっかく品川区でビーチバレーボールをやって、レガシーにしようという中で、もう少し検討してもらいたいなと。でも、何か考えておいてもらいたいなと、これは改めて要望しておきたいと思います。その辺もそういう先方の、例えばビーチバレーボールの関係者の方とかに調整しておいて確認をしてもらえれば、先に進めていただきたいなということで、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"ブラインドサッカーなのですけれども、目の不自由な方がそれをやるわけですが、健常者の方々がやるようなことというのは考えられないのですか。何かアイマスクみたいなものをして、そして、その下には何かもう一つ目を隠せるようなものがありましたけれども、健常者がそれを普通にやるとなれば、不可能なことでもないような気がするのですが、何かそういうものの動きはないですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"アイパッチを貼りまして、それでまた上からアイマスクをするという形で、これは目が見える見えないに関わらず楽しめるスポーツです。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問","question":"これは普通の試合、競技をやっている最中には、選手がその遮眼帯みたいな顔にカバーをするものをつけないのですが、なぜその差というのがあるのですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホッケーの際にマスクみたいなものをするということですね。反則があったときに、サッカーで言うコーナーキックみたいなものがありまして、そのときに、守りの選手が。守備はゴールキーパーと、あと５人しかいないということで、それで、非常に近いところから打つわけです。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"どうしてもホッケーの場合には、スティックを使うものですから、競技中に大きなけがというのや、そういうものはあるものでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そうですね。選手に聞いた話ですと、ボールが当たったですとか、それであざができるとか、そういったことは割とあるというふうにはおっしゃっていました。やはりけがも伴うような、それはあるのかなというふうに思っています。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"ボールくらいだったら何とか大丈夫でしょうけれども、スティックというもの、物すごく硬いものでしょうから、それが当たると大きなけがにつながるような、顔に当たったり、何かそういう事例があるのかどうか、それだけ教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"けがの詳細のところまでは把握はしていないのですが、ただ、ホッケーは相手の体にスティックが当たってしまうと反則になって、コンタクトプレーは基本的にございませんので、そういう意味では、スティックが当たってしまって大きなけがをしたというのは。","id":"exchange-020"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"湯澤委員ですとか鈴木真澄委員から、また、議員連盟でも動きがありますので、その中で得た情報ですとかもお話をさせていただいたりしているのですが、１つ大枠で捉えたときに、こういうことを考えているかどうかというのを教えていただきたいのが、今回お出しいただいた資料というのが、オリンピック・パラリンピック準備課のほうでなさっているようなことが中心で出てきていて。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"残念ながら繰り延べてしまいましたので、今年度は作ることはございませんが、今までの活動というものは何かしらの形で記録に残しておくような予定はあります。","id":"exchange-021"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"当然開催区ですから。輝き度が高いというのでしょうか、すごくいい砂らしいのですけれども。そういう話も伺ったりしていて、多分大森ふるさとの浜辺公園の４分の１もあればちゃんと整備はできるのだけれどもな、などという話もしていたのです。競技場はなくなってしまいますから、先ほどご答弁もいただいているのですが、何かいろいろ少し検討していただきたいなと思うのですが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと、例えば新庁舎のところに何かを置くだとか、それとも学校に行くか、いろいろな形でレガシーとして残すということは考えられるかなと思いますので、こちらは今後の研究課題にさせていただきたいと思います。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"今、渡部副委員長が前段でお話されたことを私も思っていたところなのです。というのは、教育委員会でオリンピック・パラリンピックの学習教材として、今回この機運醸成を盛り上げてきた。意識として残していくというレガシーのあり方もあっていいのかなと思うところですが、いかがでしょうか。ですから、ここは教育委員会と連携を取ってやっていただくというところになりますが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員がご提案になっているのは、市民科の教科書に載せるだとか、先ほど渡部副委員長からもございましたようにしながわ歴史館に何か残すとか、いろいろな形が考えられると思いますので、私どもの所管課だけで考えるのではなくて、全庁的にどんな形が取れるのかなというのは。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"今、渡部副委員長とこんの委員からもありました。その上で、今日はホッケーとビーチバレーボール以外もよろしいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"オリンピック・パラリンピック準備課ではなくて、それが発展的にどういうふうになっていくかということもあると思うのですが、担い手というのは、今こんの委員からあったように教育委員会だったり、いろいろな地域、町会であれば地域振興部だったりとなってくると思うのですけれども、レガシーを続けていく予算というのですか、財源というのは、どういったところに求めることができるのか、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区のほうは、先ほど記録的なものを残すような予定でおりますというものがありますし、それ以外でもいろいろな形でどうやって残していくかというのは、大会が終わってまだその後、１０月以降も半年はありますので、そこで一定程度の形をつくっていくといいますか。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"どういう形でそれを確保して、また、逆に言うといい意味での地域展開というのでしょうか、行政が引っ張ったり後押しということではなくて、地域の取り組みとして定着していくということがいいのかなと。そういった部分では、レガシーというお金のかからない、先ほど心の話もありましたけれども、それを１つの糧としていただくというのは当然プライスレスだと思うのです。","respondent":"山崎文化スポーツ振興部長","answer":"もともと、品川区では、オリンピックの推進には区長をトップにした品川区２０２０年オリンピック・パラリンピック推進本部ということで、全庁的に連携をしながら取り組んでまいっておりますので、そうしたこれから東京２０２０大会を実施するに向かっての調整。","id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"ありがとうございました。大きい方向性は今理解をさせていただきました。当然、ソーシャルディスタンスを取りながらやっていく。そして、地域に定着化させていくというそういったところも必要になるかなと思うのですが、具体的な部分で今のパブリックビューイングの有り様も含めて、観戦の形を品川区としてどうアプローチをつくっていくかというところについて、もし何かお考えがあれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"翻ってみますと、ラグビーワールドカップのときは本当にパブリックビューイングも本当に盛り上がっていまして、来訪者の外国の方も、チケットを持っていない試合に関しては、自分のホテルやスポーツバーなどで見ている方が町なかでも非常に多かったというふうに認識しております。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"だから、来年度東京都のお金でいろいろあった競技観戦の子どもたちの学校連携観戦プログラムで、本来は競技会場に行くとかがあったわけですけれども、例えばそれがならぬとなったときには、ではそれの次善策として、今ある端末とかを活用して見られる仕組みが、いろいろ放映権も含めて可能なのかどうかというところが必要になってくるのかなと。最後、何かあれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いろいろな形を考えていただきたいということでした。私どももまさにそれを考えているところでして、会場に行かなくても家でテレビを見るだけではなくて、自分があたかもそこにいるようなことというのは、いろいろな形で実証実験なり、いろいろな通信会社がやっております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、そうしたクラシック音楽を。当然音楽ですと、オンラインとかとも相性がいいと思いますので、そうした今回の東京２０２０大会を機に、品川区の文化・芸術振興というものも進めていっていただきたいと考えています。例えばその中でクラシックとお話ししましたけれども、その点いかがお考えなのでしょうか。","respondent":"古巻文化観光課長","answer":"今、具体的に何という形で、おっしゃったことに対してのいろいろな区としての展開というのはなかなか難しいですけれども、そういったものも含めて様々に情報収集しながら、きちんと文化プログラム、それから文化・芸術の振興を図っていきたいというふうに考えております。","id":"exchange-029"}]},{"id":"topic-02","title":"しながわホッケーまちづくりプロジェクト事業","agenda":"しながわホッケーまちづくりプロジェクト事業","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"（３）の事業の1)のほうですけれども、スポーツツーリズムの実現を目指すというその目的というのですか、品川区の目的を改めて伺いたいのと、あと、今回実証実験を行うということですが、その実証実験後の展開というのは、どういうふうに今どこで考えていらっしゃるのか。2)については、ワークショップ、オンライン学びの講座というのは、どんな内容なのか、もう少し具体的に伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回の実証実験のその後ということですが、こちらに来ていただいた方にはアンケート等を取らせていただいて、今後どういった観光コースを創るだとか、どういった形で宣伝していけばいいのかというところまでの取り組みまでを考えるような予定となっております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"今回、大井ホッケー競技場が恒久施設でできるということもありますし、スポーツのホッケーという競技自体がまちの活性化につながっていくということ自体はもちろんあると思いますけれども、私もこの間ホッケー議員連盟のほうの学習会ですとかでルールを学んだりとか、あるいは会場で試合も拝見させていただいて、ホッケーの競技としての魅力というのですか、紳士淑女のスポーツということで。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういう意味では、ワークショップをする中で、町会関係の方だとか、スポーツ関係の方、事業者の方、いろいろな方に集まってもらって、その方からまた広めていただくというような形が今回取れれば、さらに魅力を区全体に広げられるかなと思っていますので。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"内容として、ホッケーを応援して、地域を盛り上げる事業を展開するということで、この事業は分かりました。ということは、逆にさっきに戻ってしまうのです。ビーチバレーボール。この事業予算が５５０万円。費用対効果は絶対に高いと思います。ただ電車で来るだけでいい。そこら辺をもう１回考えておいてもらいたいと思うのですけれども、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、いかんせん１回にかかる額というのも大きいというような、一過性で見ますとそういった側面もあることも否定できないところですので、それは今後の課題とさせていただきたいなと思います。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、金額を言われましたが、金額は確かに５５０万円。さっき、前のときには２,０００万円かかると考えたときに、品川区の中で８,０００人くらいが来たときと考えたときの２,０００万円は効果あるのではないか、そんなに大きな金額ではないというふうに私は思うのです。財政面もあるでしょうし、いろいろな担当部署との調整もあるのでしょうが、ぜひ考えていただきたいというのを改めて要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"1)で、せっかく地方からお客様が来るわけで、モニターツアーですから、多分アンケートか何かにお答えいただくような仕組みなのだろうけれども、これ、ぜひ、今日の明日で間に合わないかもしれないけれども、アンケートは書いてもらわなくてもいいから、細かい項目を区のほうで出して丸をしてもらったほうがいいですよ。アンケートをしても「よかった」で終わってしまうのです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"アンケートの内容等についてのご質問ですが、職員も入って一緒にやっておりますので、戻り次第確認をして、項目の深さといいますか、どういったものが入っているのかというのは、もう一度確認をして、なるべく今後に役立つようなアンケートを作成したいと思います。","id":"exchange-034"},{"speaker":"渡部副委員長","kind":"意見","question":"値段の安い高いもそうなのだけれども、実際これだけのお金を使って、様々なことをやる中で、身になるといったらおかしいのですけれども、目に見える形の答えが欲しいですよね。課題が出たら、逆にまちづくり協議会と一緒にこれをどうやって解決しようかとまた次のステップに行けるわけで、そうなると、こういう体験ツアーは思い切り生きると思いますので、間に合えば、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、私の勉強不足で教えていただきたいのですけれども。1)のところで、主催が旧東海道品川宿周辺まちづくり協議会ということでした。会場は、八潮のほうになりますけれども、屋形船で巡る東京２０２０大会競技会場の見学ツアーということで、どういったいきさつから、ここの地域がツアーを組むことになったのか。屋形船になったことも。私、勉強不足でそこら辺もお知らせいただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホッケーのオリンピック会場を使うということで、船から見るというのはなかなか東京都民でも近くに住んでいる方でも体験しないことですので、品川区の売りの１つといいますか、楽しめる、非常に魅力のある内容だろうということで、その内容について今回選んでいるところです。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"品川区の売りの１つがこの屋形船ということで、行政が選んだというところでよろしいですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そもそものボランティアビレッジの起こりですが、大会のときに、特に競技ボランティアの方が１０日間以上、競技のボランティアをするにあたって、宿泊するところがもう不足していると、泊まるところもないかもしれないということと、それから。","id":"exchange-037"}]},{"id":"topic-03","title":"はじめに、(1)議会閉会中継続審査調査事項","agenda":"はじめに、(1)議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"オリンピック・パラリンピックを考える上では避けて通れない内容だと思いますので、１点だけ。策定委員会では、そういうスポーツ施設の増設という要望ですとか意見というのは、出なかったのか、そこだけお伺いします。","respondent":"中元スポーツ推進課長","answer":"「スポーツ施設の計画的な改修・整備」という項目は目標の中にはつくらせていただいてございまして、今後新たなスポーツ施設の設置についても計画的に進めていきたいというものは、計画の中に盛り込まれてあります。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"維持・管理みたいなことしか書いていないので、この場をお借りして要望したいのですけれども、区民が気軽に使えるスポーツ施設の増設というのは、委員会の中でも出たということなので、ぜひ課題にも施策にも入れるべきではないかというふうに思いますので、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問","question":"長期基本計画の中にも、スポーツに関して出てくる中で、「『する』スポーツに加え、地域のにぎわいや産業活性化にもつながる『みる』スポーツの充実もめざし、施設の整備を進めます」と。今、施設の整備とか必要性もあるのですけれども、「みる」施設ということで、この計画の中にどの程度含まれているのか。私はまだ全部読み切れていないので、そこの部分を教えてください。","respondent":"中元スポーツ推進課長","answer":"区内の運動施設にトップレベルの大会やスポーツイベントを誘致することで、トップアスリートの方が参加する競技を区民の方が見られる、促す取り組みを行いますということで書いてあります。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１点だけ、スポーツを見るための施設ということもこれからも検討していってもらいたいということで、要望しておきますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、もしかしたら区民委員会でも議論があったかもしれないのですが、障害者の方たちへのパブリックコメントの周知などはされているのかというところを確認させてください。","respondent":"中元スポーツ推進課長","answer":"障害者の方だけに特に何かをやったというものではなくて、ホームページにデータを２つあげてあります。音声読み上げに対応した素案のファイルも入れさせていただいているところです。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706411?Template=document&Id=6586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":34221,"voices":106}},{"id":"r02-20201209-10","meetingId":"r02-cm12","date":"2020年12月9日","dateIso":"2020-12-09","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"東京都後期高齢者医療広域連合議会第２回定例会本会議が、令和２年１１月２５日に開催されました。一般質問がまず２名。金額で言うと、歳入は６５億２,８００万円。歳出は６４億４,２００万円。差引き８,６００万円。それから、議案２番目として、令和元年度後期高齢者医療特別会計決算。歳入が１兆４,４４１億８,４００万円。歳出が１兆４,０４８億９,６００万円。差引き３９２億８,８００万円。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"私のほうから、１点、今局長からも説明がありましたが、防災訓練が行われます。ぜひ皆さん確認をしていただきたいと考えています。丈が長い。靴がない。腕章がないなど、ヘルメットもそうでありますが、帽子。今日確認をしていただきたいと思いますので、よろしくお願いを申し上げます。その他で何かありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5388#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10459,"voices":29}}]);
